window.__TRANSKY_ATLAS_DATA__=window.__TRANSKY_ATLAS_DATA__||[];window.__TRANSKY_ATLAS_DATA__.push("僧\"],\"objects\":[\"泰国佛珠\",\"表演海报\"],\"places\":[\"泰国表演场\",\"双龙寺\"]},{\"key\":\"x048\",\"id\":48,\"title\":\"5 · 买药\",\"kind\":\"prequel\",\"volume\":null,\"start\":2807,\"end\":2809,\"summary\":\"得知附近药房有相关药品后，雨晴取出存钱，特地坐车远离家附近，以免被父母发现。大型连锁药店因没有处方拒售，她羞惭又失落，之后在私营小药店加价买到药。整段以紧张、兴奋和隐瞒交错，写出她首次私自用药的孤立处境与不规范交易。\",\"turn\":\"身体探索走入秘密行动，相关药物只作剧情记录。\",\"time\":\"秋天；首次买药\",\"people\":[\"苏雨晴\",\"连锁药店收银员\",\"小药店店员\"],\"objects\":[\"存钱罐\",\"药盒\",\"处方\"],\"places\":[\"杭州\",\"老百姓大药房\",\"私营小药店\"]},{\"key\":\"x049\",\"id\":49,\"title\":\"6 · 偷窥洗澡（上）\",\"kind\":\"prequel\",\"volume\":null,\"start\":2810,\"end\":2812,\"summary\":\"七八岁暑假住外婆海边村，雨晴跟三个表哥玩耍。表哥们提议偷看表姐洗澡，带她翻墙上树；她年幼不懂他们的动机，却因身体差异产生想成为女孩的羡慕。这是侵犯他人隐私的童年事件，不能用原文玩笑口吻美化，也不能将未成年身体描写带入展示。\",\"turn\":\"隐约身份愿望再度显露，表哥带领的越界行为将被发现。\",\"time\":\"七八岁暑假\",\"people\":[\"苏雨晴\",\"大表哥\",\"二表哥\",\"三表哥\",\"表姐\"],\"objects\":[\"老槐树\",\"窗帘\"],\"places\":[\"外婆海边渔村\",\"表姐家院子\"]},{\"key\":\"x050\",\"id\":50,\"title\":\"7 · 偷窥洗澡（下）\",\"kind\":\"prequel\",\"volume\":null,\"start\":2813,\"end\":2815,\"summary\":\"表姐父亲撞见树上的孩子，表哥们慌乱坠地，三表哥接住雨晴并先把她送出墙洞，自己被抓。大伯从现场痕迹识破窥视，三位表哥都受父母惩罚，未把雨晴供出；她回去对母亲隐瞒，既庆幸逃脱又担心哥哥。本篇明确表姐与三表哥是亲姐弟。\",\"turn\":\"窥视事败，三表哥的保护成为雨晴对亲人亲近记忆的一部分。\",\"time\":\"接上篇当晚\",\"people\":[\"苏雨晴\",\"大表哥\",\"二表哥\",\"三表哥\",\"表姐\",\"大伯\",\"苏雨晴的母亲\",\"表哥们母亲\"],\"objects\":[\"院墙小洞\",\"老槐树\"],\"places\":[\"表姐家\",\"外婆家\"]},{\"key\":\"x051\",\"id\":51,\"title\":\"8 · 女装\",\"kind\":\"prequel\",\"volume\":null,\"start\":2816,\"end\":2818,\"summary\":\"父母结婚纪念日外宿，第一次给雨晴整日独处空间。她上完课去银泰吃肯德基，再羞怯地买下粉白连衣裙，藏进书包带回家。穿上后她感到安稳、轻松与自我一致，连夜也穿着入睡；秘密女装体验由想象变成能够确切记住的归属感。\",\"turn\":\"独处让雨晴首次主动实践女装，安稳感强化未来选择。\",\"time\":\"接近学期末的夏日；父母结婚纪念日\",\"people\":[\"苏雨晴\",\"苏雨晴父母\",\"服装店服务员\"],\"objects\":[\"父母纸条\",\"两百元\",\"粉白连衣裙\",\"书包\"],\"places\":[\"银泰百货\",\"肯德基\",\"苏家\"]},{\"key\":\"x052\",\"id\":52,\"title\":\"9 · 莫空的旅行\",\"kind\":\"prequel\",\"volume\":null,\"start\":2819,\"end\":2821,\"summary\":\"离开家主位置后莫空辗转旅行，在杭州登上开往小城市的列车，本无固定目的。戴白帽的雨晴误坐其窗边座位，他不打扰却被她忧伤眼神触动，决定也去小城市停留。到站后他唤醒熟睡的她，前传以他的视角重述正文最初相遇。\",\"turn\":\"莫空停留并非纯偶然：他已因雨晴产生难以解释的牵动。\",\"time\":\"正文开篇相遇之前及当日\",\"people\":[\"莫空\",\"苏雨晴\"],\"objects\":[\"火车票\",\"白色鸭舌帽\",\"烟盒\"],\"places\":[\"杭州\",\"开往小城市的列车\"]},{\"key\":\"x053\",\"id\":53,\"title\":\"10 · 曲奇的故事（上）\",\"kind\":\"prequel\",\"volume\":null,\"start\":2822,\"end\":2824,\"summary\":\"曲奇尚是奶猫时被原主人因排泄问题弃在公园，大黄狗把它带到郊区垃圾场，与失去幼崽的花母猫共同抚养。流浪者也分给食物；大黄狗一度被狗贩抓去，为给家人带食物带伤逃回。跨物种家庭让曲奇学会依恋与责任，而非天生只亲近雨晴。\",\"turn\":\"曲奇的养父母与受助经历解释其后来顾家和珍惜陪伴的性格。\",\"time\":\"遇雨晴约三年前\",\"people\":[\"曲奇\",\"大黄狗\",\"花母猫\",\"曲奇原主人\",\"流浪者\",\"狗贩\"],\"objects\":[\"废沙发猫窝\",\"纸箱\",\"食物\"],\"places\":[\"花鸟市场\",\"公园\",\"郊区垃圾场\"]},{\"key\":\"x054\",\"id\":54,\"title\":\"11 · 曲奇的故事（中）\",\"kind\":\"prequel\",\"volume\":null,\"start\":2825,\"end\":2827,\"summary\":\"曲奇长大后与大黄狗共同觅食，垃圾场清拆建化工厂迫使一家流浪。花母猫病重，黄狗负责背护，曲奇承担找食物；老猫指点海边捕鱼，却路途远、只能带少量。地下室虽能遮风，母猫仍逐渐失去行动能力，冬天将至，曲奇决意寻找更稳定食物。\",\"turn\":\"居所被拆与母猫病重使曲奇由受照顾者变成家庭供养者。\",\"time\":\"曲奇出生半年多后至冬前\",\"people\":[\"曲奇\",\"大黄狗\",\"花母猫\",\"老流浪者\",\"老猫\",\"施工工人\",\"顽皮儿童\"],\"objects\":[\"猫粮\",\"废沙发\",\"海鱼\"],\"places\":[\"垃圾场\",\"城市街巷\",\"海边\",\"地下室\"]},{\"key\":\"x055\",\"id\":55,\"title\":\"12 · 曲奇的故事（下）\",\"kind\":\"prequel\",\"volume\":null,\"start\":2828,\"end\":2830,\"summary\":\"曲奇为照顾病猫学会潜入店铺与住家觅食、储存肉干，家庭一度能安稳过冬。流浪动物清捕突然到来，衰弱母猫无法奔跑，大黄狗背她逃离仍被追上。曲奇反击后，大黄狗留下阻挡，示意它带养母走；它背起母猫逃脱，养父就此失散。\",\"turn\":\"大黄狗以保护家人换曲奇脱身，最终死亡并未在此明确。\",\"time\":\"冬天\",\"people\":[\"曲奇\",\"大黄狗\",\"花母猫\",\"流浪猫群\",\"捕捉人员\"],\"objects\":[\"储备肉干\",\"猫粮\",\"网兜\"],\"places\":[\"酸菜鱼馆\",\"地下室\",\"城市小巷\"]},{\"key\":\"x056\",\"id\":56,\"title\":\"13 · 莫空和曲奇的故事（上）\",\"kind\":\"prequel\",\"volume\":null,\"start\":2831,\"end\":2832,\"summary\":\"春日莫空独自在新河堤烤鱼喝柳叶茶，注意到一只瘦弱而敌视人的黑猫。旁白补明曲奇逃亡后再没见黄狗，花母猫也病亡，它亲自埋葬后因悲伤衰弱。莫空的流浪者气质令它既熟悉又警惕，食物香气把两个漂泊者带到一起。\",\"turn\":\"曲奇失去原生陪伴，与莫空建立新联系的机会出现。\",\"time\":\"养父失散、养母死亡后的春天\",\"people\":[\"莫空\",\"曲奇\",\"大黄狗\",\"花母猫\"],\"objects\":[\"鲈鱼\",\"螃蟹\",\"柳叶茶\"],\"places\":[\"新建河堤\",\"地下室\"]},{\"key\":\"x057\",\"id\":57,\"title\":\"14 · 莫空和曲奇的故事（中）\",\"kind\":\"prequel\",\"volume\":null,\"start\":2833,\"end\":2835,\"summary\":\"曲奇趁莫空取水偷食，虚弱摔倒后以为会遭惩罚，对方却只安静吃饭，随后分给半条鱼与茶水。它把他的气质联想到善良流浪者，放下部分戒心。莫空也回忆莫家院落常喂猫的日子，二者的信任在不强迫、不打扰的相处中建立。\",\"turn\":\"莫空用克制的照料恢复曲奇对人的有限信任。\",\"time\":\"接上篇\",\"people\":[\"莫空\",\"曲奇\",\"莫家院落黑猫\"],\"objects\":[\"烤鱼\",\"螃蟹\",\"柳叶茶杯\"],\"places\":[\"河堤\",\"莫家小院回忆\"]},{\"key\":\"x058\",\"id\":58,\"title\":\"15 · 莫空和曲奇的故事（下）\",\"kind\":\"prequel\",\"volume\":null,\"start\":2836,\"end\":2838,\"summary\":\"曲奇在莫空身旁熟睡，醒来时他已离去，却留下外套、挡风石圈与鱼。恢复精神后它再访河堤，与莫空重逢并捕鱼回报。莫空直接叫它曲奇，又问星空是否真实、为何每次来都像第一次；前传未解释这些超出当时关系的信息，只为轮回与现实疑问添线索。\",\"turn\":\"人与猫成为互相照料的朋友，莫空提前知名与既视感保留悬念。\",\"time\":\"春天；两次会面相隔一段时间\",\"people\":[\"莫空\",\"曲奇\"],\"objects\":[\"外套\",\"挡风石圈\",\"烤鱼\",\"柳叶茶\"],\"places\":[\"河堤\"]},{\"key\":\"x059\",\"id\":59,\"title\":\"16 · 张思凡的故事（上）\",\"kind\":\"prequel\",\"volume\":null,\"start\":2839,\"end\":2841,\"summary\":\"大学时张思凡急于筹齐身体手术费用，在论坛结识者介绍下接受富商包养，以为一个月便能实现目标。头几日较为宽松的待遇与高额报酬令她放下戒心，第四日起却遭拘束和严重性虐待。前传揭示她曾把快速赚钱当捷径，却落入剥夺自主的暴力环境。\",\"turn\":\"最初自愿交易转为强迫侵害，不能把后续虐待称为同意。\",\"time\":\"大学期间\",\"people\":[\"张思凡\",\"论坛介绍人\",\"富商\"],\"objects\":[\"论坛私信\",\"现金\",\"电脑\"],\"places\":[\"富商别墅群\"]},{\"key\":\"x060\",\"id\":60,\"title\":\"17 · 张思凡的故事（中）\",\"kind\":\"prequel\",\"volume\":null,\"start\":2842,\"end\":2844,\"summary\":\"富商持续拘禁、羞辱并加重对张思凡的身体侵害，试图消磨她反抗的能力。她表面顺从以降低对方戒心，心里始终寻找脱身机会，身体和精神都接近极限。一次富商外出后，她观察窗外逃生路径，决定抓住可能唯一的空档离开。\",\"turn\":\"顺从是求生伪装，张思凡的主体性通过持续逃离意志显现。\",\"time\":\"接上篇拘禁期间\",\"people\":[\"张思凡\",\"富商\",\"邻栋被包养者\"],\"objects\":[\"束缚物\",\"窗户\"],\"places\":[\"富商别墅\"]},{\"key\":\"x061\",\"id\":61,\"title\":\"18 · 张思凡的故事（下）\",\"kind\":\"prequel\",\"volume\":null,\"start\":2845,\"end\":2847,\"summary\":\"趁富商不在，张思凡艰难摆脱束缚，带走此前所得一万元、身份证与家门钥匙，从窗口逃出别墅，再乘出租车转火车离开。直到车厢开动她才稍稍放松，重新体会自由的珍贵。正文中看似外向能干的人，由前传补出沉重而未获司法交代的创伤。\",\"turn\":\"张思凡成功自救离开；富商与介绍人的后续责任未交代。\",\"time\":\"拘禁期间一次富商外出时\",\"people\":[\"张思凡\",\"富商\",\"出租车司机\"],\"objects\":[\"一万元\",\"身份证\",\"家门钥匙\",\"火车票\"],\"places\":[\"富商别墅\",\"出租车\",\"火车站\"]},{\"key\":\"x062\",\"id\":62,\"title\":\"19 · 曲奇和咖啡的故事\",\"kind\":\"prequel\",\"volume\":null,\"start\":2848,\"end\":2850,\"summary\":\"曲奇把幼鼠送给雨晴却未被接受，原想当作食物，见它不逃反而亲昵依赖，逐渐产生好奇。幼鼠误把它当母亲寻找喂养，唤起曲奇曾被大黄狗救养的记忆。它放弃捕食，开始梳理幼鼠毛发，咖啡由猎物变成被照顾的家人，跨物种的善意被传递下去。\",\"turn\":\"曲奇的受养经历回收到它对咖啡的保护欲。\",\"time\":\"咖啡初次出现前后\",\"people\":[\"曲奇\",\"咖啡\",\"苏雨晴\",\"大黄狗\",\"莫空\"],\"objects\":[\"幼鼠食物礼物\"],\"places\":[\"小城市空地\"]},{\"key\":\"x063\",\"id\":63,\"title\":\"20 · 胡玉牛的往事\",\"kind\":\"prequel\",\"volume\":null,\"start\":2851,\"end\":2853,\"summary\":\"十三岁的胡玉牛视父亲为英雄，刻苦练家传木剑与体能，盼超过父亲。父亲把家族振兴寄托在他身上，连饮酒也作为男子气概鼓励；母亲阿玉温柔照顾，却怀疑家族负担的必要，夜里感叹若孩子是女孩就好。前传呈现热烈亲情与沉重继承期待并存的家庭。\",\"turn\":\"承担家族与男子气概被紧密绑定，为后来的身份和责任冲突铺底。\",\"time\":\"胡玉牛十三岁\",\"people\":[\"胡玉牛\",\"胡玉牛父亲\",\"阿玉\"],\"objects\":[\"木剑\",\"啤酒\",\"被子\"],\"places\":[\"胡家\",\"村口小河\"]},{\"key\":\"x064\",\"id\":64,\"title\":\"21 · 父母的保护\",\"kind\":\"prequel\",\"volume\":null,\"start\":2854,\"end\":2856,\"summary\":\"母亲圆圆与其兄通话，证实她一直获知雨晴离家后的状况。被称作大伯的长辈也是大表哥父亲，曾替超市火灾压事，买昂贵茅台误想帮雨晴挣提成，再打给总经理嘱咐照看。他支持雨晴做女孩，批评父系族规，并与母亲谈再育孩子以减继承压力，揭开暗中保护网络。\",\"turn\":\"陌生购酒人是家人，疏离表象下仍有支持；亲属称谓在原文混用。\",\"time\":\"雨晴超市工作时期\",\"people\":[\"苏雨晴\",\"苏雨晴的母亲\",\"苏雨晴的大舅\",\"苏榕槐\",\"大润发总经理\"],\"objects\":[\"龙年茅台\",\"手机\",\"照片\"],\"places\":[\"大润发超市\"]},{\"key\":\"x065\",\"id\":65,\"title\":\"22 · 方莜莜和她的前男友\",\"kind\":\"prequel\",\"volume\":null,\"start\":2857,\"end\":2859,\"summary\":\"初用药时方莜莜接受一位喜欢男性的男友追求，身份选择尚在犹疑。首次同宿，她多次拒绝进一步身体接触，对方虽暂缓仍因欲望不满，次晨又未经充分同意亲吻她。前传展示她对亲密、身体与关系信任的不安；其后如何分手、此人姓名均未在本篇交代。\",\"turn\":\"接受恋爱不等于同意全部身体接触，关系终局此篇未写。\",\"time\":\"方莜莜初用药时期\",\"people\":[\"方莜莜\",\"方莜莜前男友\"],\"objects\":[\"女装\"],\"places\":[\"前男友房间\"]},{\"key\":\"x066\",\"id\":66,\"title\":\"23 · 林夕晨的过去\",\"kind\":\"prequel\",\"volume\":null,\"start\":2860,\"end\":2862,\"summary\":\"林夕晨生于偏远山村，是三个姐姐之后被当作唯一儿子养育的孩子。父亲给她最好的食物、礼物与读书机会，甚至以长姐彩礼供高中；这份爱伴随明显重男轻女。进入青春期后她身体发育与预期不同，逐渐拒绝父亲过度亲近，又用交女友解释增加的生活费，难言之隐埋下返乡冲突。\",\"turn\":\"父亲宠爱依赖“儿子”身份，后续毁灭性落差有了家庭背景。\",\"time\":\"童年至高二\",\"people\":[\"林夕晨\",\"林夕晨父亲\",\"林夕晨母亲\",\"林夕晨三个姐姐\"],\"objects\":[\"自行车\",\"试卷\",\"礼物\",\"长姐彩礼\"],\"places\":[\"偏远山村\",\"县城小学初中\",\"城市高中\"]},{\"key\":\"x067\",\"id\":67,\"title\":\"24 · 莫空的幼年\",\"kind\":\"prequel\",\"volume\":null,\"start\":2863,\"end\":2865,\"summary\":\"莫空作为族长独子自幼享特权，曾指使同伴殴打仆人，父亲还称赞其领导力。初中起他厌倦虚伪权争，读书思考、尝试真诚结交却难获信任，十三岁已否定随意改写过去的人生价值。父亲病逝后众人基于不同利益推他任家主，他最终放弃位置离家。\",\"turn\":\"由滥用继承权力转向主动放弃，不能把其童年写成始终温和。\",\"time\":\"莫空童年、十三岁至父亲病逝后\",\"people\":[\"莫空\",\"莫家父亲\",\"莫空母亲\",\"受伤仆人\",\"同龄族人\",\"家族元老\"],\"objects\":[\"家族藏书\",\"假想回溯物\"],\"places\":[\"莫家\",\"藏书阁\",\"祠堂\"]},{\"key\":\"x068\",\"id\":68,\"title\":\"25 · 拜佛\",\"kind\":\"prequel\",\"volume\":null,\"start\":2866,\"end\":2868,\"summary\":\"雨晴从把佛理解为许愿者，逐渐发现父母信仰更像精神寄托。初二随家人到天竺寺，她祈愿变成女孩，一度仿佛看见佛像微笑，连续一个月期待醒来便实现；落空后明白仍须自己行动。此后念佛握佛珠主要用来安定心神，信仰和自我认同交织。\",\"turn\":\"佛像微笑仅为恍惚感受，许愿最终转为对自身努力的寄托。\",\"time\":\"第一次初二时及此前\",\"people\":[\"苏雨晴\",\"苏雨晴父母\"],\"objects\":[\"纯金佛像\",\"高香\",\"佛珠\"],\"places\":[\"苏家\",\"天竺寺\"]},{\"key\":\"x069\",\"id\":69,\"title\":\"26 · 年少时的天语遥\",\"kind\":\"prequel\",\"volume\":null,\"start\":2869,\"end\":2872,\"summary\":\"天冲云从小机灵且拒绝随大流，梦想由贪官、将军到老板，都围绕领导他人。课堂讨论困境中的苹果分配时，他强调功用和战斗力，忽略感情因素，令老师无从简单评价。缺少恰当引导与青春期求异结合，最终使他以混混头目的身份实现扭曲的领导愿望。\",\"turn\":\"强硬、求异和控制欲的成长背景被补足；旁白教育理论仅属作者观点。\",\"time\":\"天冲云童年至青春期\",\"people\":[\"天语遥\",\"天语遥父母\",\"幼儿园老师\",\"小学老师\",\"同学\"],\"objects\":[\"课文中的苹果\"],\"places\":[\"幼儿园\",\"小学\",\"街头\"]},{\"key\":\"x070\",\"id\":70,\"title\":\"27 · 天冲云救美\",\"kind\":\"prequel\",\"volume\":null,\"start\":2873,\"end\":2876,\"summary\":\"天冲云听见少女求救，率部与雷神帮冲突并救下夏归月，交换联系方式。读者随后得知所谓危险原是手下老六策划的英雄救美：他实为雷神帮副帮主兼卧底，既追求夏归月也试探地盘，却被老大抢先破局。天冲云确实出手救人，也主动经营英雄形象争取她好感。\",\"turn\":\"恋情始点来自未被主角识破的骗局；老六潜伏后续未在本篇交代。\",\"time\":\"天冲云与夏归月初识\",\"people\":[\"天语遥\",\"夏归月\",\"老六\",\"老二\",\"老三\",\"雷神帮成员\",\"黄枸\"],\"objects\":[\"手机号码纸条\",\"修车铁棍\"],\"places\":[\"帮派交界街巷\"]},{\"key\":\"x071\",\"id\":71,\"title\":\"1 · 林夕晨（一）\",\"kind\":\"meta\",\"volume\":null,\"start\":2878,\"end\":2880,\"summary\":\"《故事之外》用作者第一人称讲角色素材：称夕子是读者群中少言温柔的熟人，曾经历手术并发问题、经济依赖和收入困境，后旅行经过作者城市，与其见面。文内明确角色名为化名，形象与身高经过创作调整；这属于未经核实的作者元叙述，既非正文夕晨生平，也非可据以诊疗的材料。\",\"turn\":\"说明素材与角色存在改写，不应从作者口吻直接推出真人或正文事实。\",\"time\":\"作者称与夕子网识约半年后\",\"people\":[\"作者（故事之外）\",\"元叙述中的夕子\",\"群友\"],\"objects\":[\"QQ昵称\",\"手术相关叙述\",\"电脑手机\"],\"places\":[\"读者群\",\"沿海城市\",\"景区\"]},{\"key\":\"x072\",\"id\":72,\"title\":\"2 · 林夕晨（二）\",\"kind\":\"meta\",\"volume\":null,\"start\":2881,\"end\":2885,\"summary\":\"元叙述继续写作者与夕子共餐、逛超市：她喂流浪狗、向往领养女孩，购物车被夺后受辱落泪；作者陪伴安慰、安排旅馆，次日车站分别。此后联络逐渐中断，作者承认不知道她的下落或是否活着，只保留温柔而易受伤的印象。这一失联状态不可混同正文明确死亡。\",\"turn\":\"作者所称素材人物下落未知，未提供任何死亡证据。\",\"time\":\"一次会面及之后失联\",\"people\":[\"作者（故事之外）\",\"元叙述中的夕子\",\"流浪狗\",\"夺购物车老人\",\"超市儿童及父母\"],\"objects\":[\"烤肠\",\"购物车\",\"车票\",\"香水\"],\"places\":[\"西餐厅\",\"超市\",\"旅馆\",\"火车站\"]},{\"key\":\"x073\",\"id\":73,\"title\":\"3 · 苏雨晴（一）\",\"kind\":\"meta\",\"volume\":null,\"start\":2886,\"end\":2889,\"summary\":\"元叙述称小晴家境优渥、离家仅一周便获父母支持，与作者同城多次游玩，爱游戏、说话傲娇而好奇活泼。爬山时她强撑到顶后身体不适，由作者背下山。作者对外貌与身体投入大量个人化描写，展示素材人物与正文受困少女的差异；这些印象和用药说法均应保留叙述来源。\",\"turn\":\"家庭支持与性格差异明确属于素材附录，不能覆盖正文离家三年情节。\",\"time\":\"作者称初见小晴十七岁\",\"people\":[\"作者（故事之外）\",\"元叙述中的小晴\",\"元叙述小晴父母\"],\"objects\":[\"游戏角色\",\"糖果\"],\"places\":[\"同城街道\",\"山路\"]},{\"key\":\"x074\",\"id\":74,\"title\":\"4 · 苏雨晴（二）\",\"kind\":\"meta\",\"volume\":null,\"start\":2890,\"end\":2893,\"summary\":\"元叙述称小晴在父母支持下手术、迁台重读高中，与旧同学保持友谊；所谓冉空城素材人曾有好感，却因喜欢男性而未发展恋爱。她适应新学校后上线渐少，作者仍祝她生活快乐，并猜测夕子失联也可能因新生活。此篇未写小晴死亡，关于寿命和身体的说法是作者及人物言论。\",\"turn\":\"元叙述小晴仅联络减少，不能拿此否定正文终局，也不能将寿命偏见当医学事实。\",\"time\":\"作者称小晴十八岁赴台重读高一\",\"people\":[\"作者（故事之外）\",\"元叙述中的小晴\",\"元叙述小晴父母\",\"元叙述旧同学\",\"元叙述中的夕子\"],\"objects\":[\"QQ\",\"户籍\",\"手术相关叙述\"],\"places\":[\"小晴家\",\"台湾高中\"]},{\"key\":\"x075\",\"id\":75,\"title\":\"5 · 张思凡\",\"kind\":\"meta\",\"volume\":null,\"start\":2894,\"end\":2897,\"summary\":\"元叙述称思思赴作者城市学淘宝美工，租到昂贵狭小无窗房，后来练瑜伽、与控制欲强的网文作者男友主动分手。父母发现其用药后限制外出，她在身份、身体与是否继续转变间摇摆。作者最后承认久未联系、现状未知；关于她想成为无性人的解释只是作者推测。\",\"turn\":\"本篇未交代结婚领养等正文结局，素材与剧情须分列。\",\"time\":\"两次见面相隔约一月，叙事跨次年冬季\",\"people\":[\"作者（故事之外）\",\"元叙述中的思思\",\"元叙述思思男友\",\"元叙述思思父母\",\"房产中介\"],\"objects\":[\"笔记本电脑\",\"假发\",\"耳环\"],\"places\":[\"培训城市\",\"一楼无窗出租房\",\"瑜伽班\",\"思思家\"]},{\"key\":\"x076\",\"id\":76,\"title\":\"6 · 天语遥\",\"kind\":\"meta\",\"volume\":null,\"start\":2898,\"end\":2901,\"summary\":\"元叙述称小遥主动手术后后悔中间身体状态，离家受贫困、失业和羞辱，见面时易怒且有严重自伤表现。作者说明正文雨晴早期流落经历借用其素材，又把其现实口吻中的家庭改为较支持的家庭，把主动手术改成被迫。篇中精神疾病与未来暴力等判断缺乏核实，只能作为叙述者主观看法。\",\"turn\":\"集中展示跨角色移植素材；不能以作者猜测登记诊断或未来命运。\",\"time\":\"作者称小遥十八岁时会面\",\"people\":[\"作者（故事之外）\",\"元叙述中的小遥\",\"元叙述小遥父母兄弟姐妹\",\"餐厅服务员\"],\"objects\":[\"丢失钱包\",\"行李\"],\"places\":[\"陌生城市\",\"餐厅\",\"商场\",\"乡村家庭\"]},{\"key\":\"x077\",\"id\":77,\"title\":\"7 · 胡玉牛\",\"kind\":\"meta\",\"volume\":null,\"start\":2902,\"end\":2905,\"summary\":\"元叙述称胡玉牛素材人是作者熟悉的卡车司机，体格与护士装形象被借入小说，性格却开朗豪放，短期好奇用药后便停止，现有女友且生活平稳。作者写二人游戏、同宿和搭卡车的趣事，并明确只借外形而大量重写内心；这与正文胡玉牛自杀死亡、IF获救都属不同层次。\",\"turn\":\"元叙述阿牛仍生活工作，不能合并为小说人物的真实结局。\",\"time\":\"作者回忆时期\",\"people\":[\"作者（故事之外）\",\"元叙述中的阿牛\",\"元叙述阿牛女友\"],\"objects\":[\"卡车\",\"护士装\",\"网络游戏\"],\"places\":[\"街道\",\"卡车\",\"游戏场景\"]},{\"key\":\"x078\",\"id\":78,\"title\":\"8 · 方莜莜\",\"kind\":\"meta\",\"volume\":null,\"start\":2906,\"end\":2909,\"summary\":\"元叙述称莜莜白天以男装上班、隐瞒身体转变，与父亲继母关系疏远；杨豪伟素材人是亲近但保持界限的朋友。安念远程送生日蛋糕促成恋爱，两人仍异地交往，未来未知。作者明确同居后的故事是模拟畅想，因此方莜莜篇相亲、自杀未遂和分离不能视为素材人物已经发生的事。\",\"turn\":\"明示外传后段为创作模拟，元叙述停留于异地相爱与未定未来。\",\"time\":\"作者写附录时恋情仍未结束\",\"people\":[\"作者（故事之外）\",\"元叙述中的莜莜\",\"元叙述安念\",\"元叙述杨豪伟\",\"元叙述莜莜父亲\",\"元叙述莜莜继母\"],\"objects\":[\"生日蛋糕\",\"淘宝礼物\"],\"places\":[\"莜莜公司\",\"杭州乐园\",\"异地住处\"]},{\"key\":\"x079\",\"id\":79,\"title\":\"后记\",\"kind\":\"afterword\",\"volume\":null,\"start\":2910,\"end\":2911,\"summary\":\"作者后记回顾一年创作，称作品混合现实素材与浪漫想象，人物各是自身故事的主角，并与《我妻》共享彩蛋。其称雨晴于2016年4月4日死亡、呼应开书日，但正文同日明确写安葬，应保留日期矛盾。其余为更新经验、新作计划、读者致谢与榜单，属于出版元信息，不是新增小说剧情。\",\"turn\":\"后记不自动为现实素材真实性背书，4月4日口径与正文必须并列提示。\",\"time\":\"2016年4月4日（作者所述）；完结时\",\"people\":[\"乱世银娘\",\"致谢读者\"],\"objects\":[\"后记\",\"粉丝榜\"],\"places\":[\"创作附录\"]}],\"characters\":[{\"id\":\"person-1\",\"name\":\"苏雨晴\",\"aliases\":[\"小晴\",\"清泉\",\"泉\",\"苏默冉（曾提议，未采用）\",\"苏雨晴（清泉）\"],\"identity\":\"全书主视角人物。2004年15岁从杭州出走的跨性别女孩，网名清泉；在小城市谋生，与伙伴建立临时家庭，后归家迁台、复学、结婚并成为养母。\",\"traits\":[\"羞怯且怕麻烦别人：陌生人前常结巴，宁拖行李步行也不借电话\",\"细心整洁：把租屋和面馆桌面反复擦净，耐心核对商品\",\"不愿白受照顾：拒绝月橙寄钱，以种植、家务和工作回应帮助\",\"有主见亦会迷茫：两次离开父母控制，仍反复想家、怀疑选择\",\"善于共情但会受外貌偏见影响：先不适胡玉牛举止，后来努力理解其自主权\",\"熟悉后能开玩笑：与张、方相处逐渐放松\",\"敏感\",\"善良\",\"害羞\",\"规矩\",\"倔强\",\"艺术感受力强\",\"渴望被接纳\",\"细腻重情：朱雀仅陪几日仍郑重安葬\",\"勤劳节俭：查货、做饭、记账并放弃电脑购买\",\"敏感且自我阻拦：反复拒绝冉的联系，也不敢向林明说喜欢\",\"守界限：约周带朋友、坚持分付餐费，尝商品后拒再偷吃\",\"体贴：为夕晨留她喜欢的饭菜、病时细心照料。\",\"节俭且负责：收银失误后拿七百元积蓄自行填补，绕路只为省公交换乘费。\",\"心软但有道德判断：质问天语遥害人，仍在其神志混乱时联系母亲接走。\",\"逐渐主动：新年告白、申请辞职，开始把读书、重返父母身边等列为人生愿望。\",\"体贴而依赖：为林求情、交卡救父，失去她后生活失序。\",\"胆怯但愿意行动：持续求职、学习促销、承担遛狗。\",\"珍惜关系和记忆：保存五十张旧照片与林的遗物。\",\"细腻念旧：携夕晨遗物迁台，在婚礼及梦中继续悼念\",\"渴望被爱又怕失去：莫空照料使她安心，也使她迟疑归家和升大学\",\"逐步拥有照料能力：尊重双胞胎意愿，耐心安慰思兄的养女\"],\"portrait\":\"她敏感、怕被拒绝，也有愿意冒险保护他人的勇气；同样会自卑、依赖、嫉妒，并以未经理解的道德判断伤到身边人。成长主要体现为逐渐能看见别人的处境，以及在收养选择中尊重孩子意愿。\",\"fate\":{\"name\":\"苏雨晴\",\"label\":\"正文死亡；外传转生\",\"tone\":\"red\",\"text\":\"婚后重病，家人与莫空救治未果。正文于2016年4月4日安葬她；死后外传转生为叶洛夜，并失去前世记忆。\",\"note\":\"4月4日在正文是安葬日，后记却称为死亡日；不能无保留写成确定死亡日期。\",\"refs\":[\"c665\",\"x001\",\"x079\"]},\"status\":\"正文：2016年春手术中病逝，4月4日安葬。死后外传：转生为2010年出生的叶洛夜，失去前世记忆。IF：与林夕晨结婚并育有女儿苏慕夕。元叙述“小晴”另属作者素材口吻，仅联络减少，未写死亡。\",\"statusRefs\":[\"c657\",\"c660\",\"c662\",\"c665\",\"x001\",\"x043\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"她从富裕家庭的受保护孩子变成靠小面馆生存的独居者，面对遗失证件、身体不适、性别羞辱与两次侵害。认真劳动、艺术兴趣和未来愿望支撑她，老板夫妻、莫空、张思凡和猫鼠逐渐提供信任。父母寻来后她忍痛再次离开，先在田园共同生活，再与三位同伴进城合租。到本段末，她以女性身份做理货员、学习厨艺，生活能力在增长；同时对莫空的好感与命运焦虑都尚未获得答案。\",\"segmentFate\":\"截至c120，在白兔小区与张思凡、方莜莜、小玉合住，于大润发开始工作；未做手术、未与莫空确立恋爱，父母未重逢。\",\"refs\":[\"c001\",\"c008\",\"c020\",\"c035\",\"c049\",\"c062\",\"c079\",\"c098\",\"c108\",\"c118\",\"c120\"],\"layer\":\"main\"},{\"scope\":\"正文 c121—c240\",\"arc\":\"这段从旧同桌的保护回忆出发，经超市血案、群居生活和夕晨到来，逐渐把孤独分给具体的人。她开始熟悉工作、敢和同事开玩笑，却仍因身体、父母与未来而反复自责。对冉空城的留恋、对莫空的安全感与对夕晨的爱情体验并存；病中喊出两人都可以是女朋友，初步松动照顾别人便等于做男性的误解。每次受伤后，小礼物、画与猫又把她接回日常。\",\"segmentFate\":\"c240时已从台风期间高烧中恢复并复工，与夕晨亲密但未确立恋爱；未返家，未知来电未查明。\",\"refs\":[\"c121\",\"c124\",\"c125\",\"c154\",\"c160\",\"c161\",\"c198\",\"c218\",\"c225\",\"c232\",\"c235\"],\"layer\":\"main\"},{\"scope\":\"正文 c241—c360\",\"arc\":\"她在劳动中学会预算与家務，从优裕家庭走向珍惜廉价物件和普通饭菜。共同生活填补孤独，却也使她更怕失去，独居、开学、中秋和宠物死亡都唤回父母旧友。她误以为父母已经放弃，实际父母已决定支持，构成信息落差。对林的暗恋逐步有双向牵手、依偎与画作回应，仍没有正式告白；对冉则在怀念与切断间挣扎。梦境不断出现自我替换与惨剧，现实生活仍继续。\",\"segmentFate\":\"截至c360仍在超市工作及白兔街合租，梦想与经济计划持续；父母接纳决定未知，和林未正式定关系。\",\"refs\":[\"c243\",\"c251\",\"c258\",\"c262\",\"c279\",\"c286\",\"c294\",\"c303\",\"c328\",\"c340\",\"c345\",\"c351\",\"c352\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"她从羞怯猜测夕晨心意，到正月初一确认相爱，在工作与共同居住中获得归属。阿牛之死使她一度投射自身前途的绝望，莜莜用未尽心愿帮她重拾希望。搬回集装箱房后，她继续接受思凡帮助，也意识到同伴各有生活。夕晨获身体新消息时，她主要感到喜悦而非竞争；面对报复者，她能够同时谴责行为和救助眼前的人。\",\"segmentFate\":\"截至c480仍与思凡、夕晨住集装箱房，超市辞职开始办理，爱恋继续；手术、回家、继续读书均未实现。\",\"refs\":[\"c366\",\"c370\",\"c391\",\"c405\",\"c406\",\"c420\",\"c421\",\"c450\",\"c452\",\"c454\",\"c465\",\"c471\",\"c476\",\"c480\"],\"layer\":\"main\"},{\"scope\":\"正文 c481—c600\",\"arc\":\"她从超市转去加油站，拒绝二少的金钱控制，攒款完成自愿手术。与冉的友谊遭遇距离，旧合租伙伴先后离开，林成为最亲近的伴侣。得知林受供养并遭虐后仍保护她、帮助筹救父款；林返乡死亡使她经历自杀危机与失眠绝食，最终在梦中告别、宠物和莫空支持下选择继续生活，入职宠物店，重新想起求学与返家愿望。\",\"segmentFate\":\"截至c600存活，住海景房、在风音宠物店工作，仍怀念林，尚未返父母家。\",\"refs\":[\"c500\",\"c503\",\"c524\",\"c529\",\"c555\",\"c574\",\"c587\",\"c594\",\"c600\"],\"layer\":\"main\"},{\"scope\":\"c601—c665；x001—x079（全部补充篇）\",\"arc\":\"本段从咖啡死亡后的独居伤痛，走向接受莫空、父母和亲族的支持。她坚持保留旧名，在完成身体与证件变更后复学，主动建立同伴关系，也拒绝为了满足母亲愿望强行拆散兄妹。高中毕业、结婚与育女让她获得长期渴望的普通生活；梦中向夕晨讲述近况表明怀念能够与新的爱情共存，最终仍无法逃过小说安排的疾病与死亡。\",\"segmentFate\":\"正文：2016年春手术中病逝，4月4日安葬。死后外传：转生为2010年出生的叶洛夜，失去前世记忆。IF：与林夕晨结婚并育有女儿苏慕夕。元叙述“小晴”另属作者素材口吻，仅联络减少，未写死亡。\",\"refs\":[\"c601\",\"c617\",\"c622\",\"c633\",\"c645\",\"c655\",\"c657\",\"c660\",\"c662\",\"c665\",\"x001\",\"x043\"],\"layer\":\"main\"}],\"refs\":[\"c001\",\"c008\",\"c020\",\"c035\",\"c049\",\"c062\",\"c079\",\"c098\",\"c108\",\"c118\",\"c120\",\"c121\",\"c124\",\"c125\",\"c154\",\"c160\",\"c161\",\"c198\",\"c218\",\"c225\",\"c232\",\"c235\",\"c243\",\"c251\",\"c258\",\"c262\",\"c279\",\"c286\",\"c294\",\"c303\",\"c328\",\"c340\",\"c345\",\"c351\",\"c352\",\"c366\",\"c370\",\"c391\",\"c405\",\"c406\",\"c420\",\"c421\",\"c450\",\"c452\",\"c454\",\"c465\",\"c471\",\"c476\",\"c480\",\"c500\",\"c503\",\"c524\",\"c529\",\"c555\",\"c574\",\"c587\",\"c594\",\"c600\",\"c601\",\"c617\",\"c622\",\"c633\",\"c645\",\"c655\",\"c657\",\"c660\",\"c662\",\"c665\",\"x001\",\"x043\"],\"group\":\"核心群像\",\"layer\":\"main\",\"core\":true},{\"id\":\"person-2\",\"name\":\"莫空\",\"aliases\":[\"莫成\",\"年轻写作者\",\"不修边幅的男子\",\"莫空（莫成）\"],\"identity\":\"旅人、小说作者，笔名或自取名莫成，曾任莫家家主。早在雨晴离家的火车上出现，后来长期相助并成为她的丈夫、语默的养父；带有家族与轮回悬疑。\",\"traits\":[\"平静细致：扶面碗、讲心算、做烤蟹烤鱼\",\"行动果断：救出酒吧受害的苏，雨中赠伞\",\"不强求回应：照顾后常默默离开\",\"喜欢旁观与体会：徒步、登楼、换工作收集人生经验\",\"清贫而自立：吃不上饭时钓鱼，熬夜写作\",\"沉稳\",\"随性\",\"疏离\",\"体察人心\",\"重精神自由\",\"守护而不索取\",\"观察敏锐：能从对话触及苏心结和天割舍\",\"尊重分寸：与胡河边相处不过问隐私\",\"复杂善意：曾帮混混识字学艺，也承认参与过其违法活动\",\"选择自由：亲历家族迫害后离开权力\",\"不急于评判：听阿牛说身份并表示不歧视。\",\"以提问和比喻促选择：放回岸上鱼后谈适合环境、关系责任。\",\"干预有边界：夕晨拒伞后不强迫；归月坚持寻人后才给纸条。\",\"行为带象征性：捐折扣券不留名、雨中抓鱼烤食、仿佛知道将至危险。\",\"平静而神秘：多次准确出现在转折处，常不解释信息来源。\",\"能共情亦保持距离：听苏倾诉、帮助动物，却也说无法救所有。\",\"表里有差异：外表淡然，删稿与凝望显示复杂心绪。\",\"照料细致：陪诊、做饭、接送、托举雨晴的日常生活\",\"洞察而隐瞒：知道梦中名字，谈轮回后改称小说对白\",\"权力态度改变：前传曾滥用继承特权，后来厌弃家族争斗离开\"],\"portrait\":\"从容、善于观察，愿意付出实际帮助，却也习惯保留信息、替他人安排路径。后期的亲密关系并没有消除他与常人经验之间的距离；雨晴之死第一次彻底打破他对未来的笃定。\",\"fate\":{\"name\":\"莫空\",\"label\":\"存活，继续抚养女儿\",\"text\":\"与雨晴结婚并共同领养语默。雨晴死后安葬她与曲奇，承诺代她照顾女儿。\",\"note\":\"第三十九次轮回等线索没有完整解释；最后未能挽救雨晴。\",\"refs\":[\"c650\",\"c656\",\"c662\",\"c665\"]},\"status\":\"正文终局存活，安葬雨晴和曲奇，继续抚养莫语默；超常身份及轮回规则未在本段完整揭示。IF中主要担当手续信使和婚礼神父式角色，与雨晴没有夫妻关系。\",\"statusRefs\":[\"c656\",\"c659\",\"c665\",\"x052\",\"x058\",\"x067\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"他从列车上唤醒苏的陌生人，变成面馆熟客、讲故事者和危急时刻的援手。鱼鹰寓言与现实不保圆满的谈论让苏既被理解又感不安；烤蟹、烤鱼、救援和赠伞则以具体行动建立信任。叙述在c076明确他珍惜苏、无占有欲，感情尚称不上爱。到本段末，苏的爱慕愈深，但莫的家庭、完整身世和未来行程仍未揭开。\",\"segmentFate\":\"截至c120仍在小城市活动，赠伞后离去；未与苏表白或确立恋爱。\",\"refs\":[\"c002\",\"c013\",\"c020\",\"c028\",\"c051\",\"c060\",\"c063\",\"c071\",\"c072\",\"c076\",\"c093\",\"c095\",\"c104\",\"c118\"],\"layer\":\"main\"},{\"scope\":\"正文 c121—c240\",\"arc\":\"六月揭开他失去父亲与族长身份的过去：面对族中刁难，他看到祖椅被虫蛀的腐朽象征，放弃权位靠写作与零工生活。他从面馆得知雨晴身份与离家处境仍维护她，在海边森林接住受自己玩笑惊吓坠落的她。向阿牛讲寓言、买两种烟体验人物心理，说明他也通过生活找答案。台风时对世界线发问，明确对雨晴有爱意而选择不打扰的守护。\",\"segmentFate\":\"继续游历写作并独住，对雨晴有爱意未表白；世界线疑问与别墅少女联系尚未解释。\",\"refs\":[\"c135\",\"c136\",\"c137\",\"c138\",\"c139\",\"c169\",\"c170\",\"c196\",\"c198\",\"c224\",\"c236\"],\"layer\":\"main\"},{\"scope\":\"正文 c241—c360\",\"arc\":\"本段揭示他的神秘占卜和现实过去并存：给苏星空球及暗示、给林血色卡，自己又遭遇狐形木卡与天台幻女。他到海边听雯雯诉说未来来历，提出留信物，却没有解释机制。家族仇怨已由他利用斗争清算，离开权位后仍在陌生人边缘生活中给予食物、故事或劝言。胡与天两条仇怨线都与他相接，莫能点出心结但未实际化解冲突。\",\"segmentFate\":\"截至c360仍在小城市工作生活，了解天处境并劝放过去；母亲下落及神秘少女联系未明。\",\"refs\":[\"c269\",\"c270\",\"c271\",\"c272\",\"c276\",\"c277\",\"c281\",\"c288\",\"c348\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"他在本段既是倾听者也是有限介入者：劝阿牛慎重选择，却未能阻止危机；公益捐券留下日常善意；雨中扶夕晨，尊重她拒绝。夏归月寻找时，他先劝放下，最后在其恳求下给方向，使真实会面成为可能。叙事常赋予他预知般的气氛，但不能据此断言现实超能力或其真实身世。\",\"segmentFate\":\"截至c480仍行踪不定，未解释自身过去；c478未具名男子由c479明确确认是他。\",\"refs\":[\"c383\",\"c414\",\"c437\",\"c470\",\"c471\",\"c478\",\"c479\"],\"layer\":\"main\"},{\"scope\":\"正文 c481—c600\",\"arc\":\"他先给夏与黄枸提供救天线索，闲游放归蝌蚪，后与苏家救援形成联系。苏的告别梦中他是引路者，现实又复述梦中话，暗示能够干预意识而非真正复活林。雪后结识秋易、促成黑皇收养，私下与曲奇如旧友相见；对苏既安慰又鼓励自我坦诚，真实身世及能力边界尚未全明。\",\"segmentFate\":\"截至c600仍居天台阁楼写作，持续关注苏；无本人终局。\",\"refs\":[\"c489\",\"c490\",\"c504\",\"c573\",\"c585\",\"c588\",\"c590\",\"c592\",\"c593\"],\"layer\":\"main\"},{\"scope\":\"c601—c665；x001—x079（全部补充篇）\",\"arc\":\"前传使他从天然完美的保护者变得复杂：童年曾指使伤人，阅读思考后才拒绝家主道路。正文末段承认因雨晴留城，接纳她的过去，陪她完成归家、迁台和育女，并逐渐在苏父公司承担责任。他对历史、未来和感受的知情不断超出常理，却总以委托、心理学、运气或小说解释。最终投入救治仍不能挽救雨晴，以守护养女延续婚姻承诺。\",\"segmentFate\":\"正文终局存活，安葬雨晴和曲奇，继续抚养莫语默；超常身份及轮回规则未在本段完整揭示。IF中主要担当手续信使和婚礼神父式角色，与雨晴没有夫妻关系。\",\"refs\":[\"c606\",\"c615\",\"c617\",\"c619\",\"c623\",\"c642\",\"c650\",\"c656\",\"c659\",\"c665\",\"x052\",\"x058\",\"x067\"],\"layer\":\"main\"}],\"refs\":[\"c002\",\"c013\",\"c020\",\"c028\",\"c051\",\"c060\",\"c063\",\"c071\",\"c072\",\"c076\",\"c093\",\"c095\",\"c104\",\"c118\",\"c135\",\"c136\",\"c137\",\"c138\",\"c139\",\"c169\",\"c170\",\"c196\",\"c198\",\"c224\",\"c236\",\"c269\",\"c270\",\"c271\",\"c272\",\"c276\",\"c277\",\"c281\",\"c288\",\"c348\",\"c383\",\"c414\",\"c437\",\"c470\",\"c471\",\"c478\",\"c479\",\"c489\",\"c490\",\"c504\",\"c573\",\"c585\",\"c588\",\"c590\",\"c592\",\"c593\",\"c606\",\"c615\",\"c617\",\"c619\",\"c623\",\"c642\",\"c650\",\"c656\",\"c659\",\"c665\",\"x052\",\"x058\",\"x067\"],\"group\":\"核心群像\",\"layer\":\"main\",\"core\":true},{\"id\":\"person-3\",\"name\":\"林夕晨\",\"aliases\":[\"夕子\",\"小夕子\",\"夕\",\"夕子姐姐\",\"夕晨\",\"夕儿（IF小名）\",\"林夕晨（夕子）\"],\"identity\":\"网名夕子，插画师，雨晴的室友与后来的恋人。来自重男轻女、存在暴力的农村家庭；正文就医情节另揭示先天性发育差异，按小说设定记录。\",\"traits\":[\"寡言\",\"观察细致\",\"外冷内热\",\"创作与手工天赋\",\"不善表达\",\"幻想丰富\",\"自主\",\"寡言但有行动关怀：赠画、洗碗、拥抱并给天饼干\",\"专注细致：可长时画画、以对照样图耐心教苏\",\"情绪隐藏：画令人不安的抽象画后立即丢弃\",\"珍视亲缘且警惕：给家寄钱信却不留回址\",\"外表寡言，关心常经行动表达：撑伞、披衣、抱睡、赠药。\",\"艺术表达复杂：画中常出现难受扭曲的意象，也可耐心教雨晴。\",\"依赖与主动并存：病时请求照顾，正式表白愿与雨晴在一起。\",\"喜悦时能流畅说话并笑唱，平日的冷淡不代表没有情感。\",\"外冷内热：沉默少言但照料苏、弹筝作画、照顾流浪动物。\",\"责任感与自我压抑：长期汇款救父，隐瞒经济与侵害困境。\",\"保护与动摇并存：曾考虑带苏换钱，最终放弃，独自承受施虐。\",\"温柔照料：IF守护病床上的雨晴、主动回应共同育女愿望\",\"幼年少言勤学：凭学习离开偏远村落\",\"父亲的偏爱以儿子身份为条件，造成长久隐瞒\"],\"portrait\":\"外表安静温柔、擅长照料与绘画，内心却压着愤怒、负疚和沉重家庭责任。她习惯独自承担并隐藏痛苦；对雨晴的保护与对原生家庭的无法脱身共同构成悲剧。\",\"fate\":{\"name\":\"林夕晨\",\"label\":\"正文死亡\",\"tone\":\"red\",\"text\":\"回乡后遭父亲暴力与禁闭、母亲未能保护，最终杀害父母后自杀。警方与新闻在后文确认死讯。\",\"note\":\"山村旅行与短暂醒来是雨晴的梦；c660再见仍是梦。不能写成现实复活。\",\"refs\":[\"c581\",\"c582\",\"c584\",\"c586\",\"c587\",\"c660\"]},\"status\":\"正文：此前已死亡，c660仅梦中重逢。IF：幸存，接受手术、成为苏慕夕母亲并与雨晴结婚。元叙述“夕子”：作者自称失联，不知道是否在世，不能与正文死亡混同。\",\"statusRefs\":[\"x040\",\"x041\",\"x043\",\"x066\",\"x071\",\"x072\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"夕晨带着画具进入住处，少言和面无表情使人误认没有感情。她以奶饮、礼画、握手、陪病和宠物照料表达关心，幻想世界与抽象画承载难言情绪；学游泳会恐惧，面对猫鼠会微笑，刷墙工又令她落泪。她有独立收入和节俭存款，却因女性身份与唯一儿子的家庭期待陷入负疚。原文同时保留受父虐待、潜藏杀父念头与深爱辛劳父亲的回忆，不宜删成单面人格。\",\"segmentFate\":\"继续创作并照料雨晴、猫鼠，约有三万元存款；未与雨晴确立恋情，未实施杀父行为，仍未返家。\",\"refs\":[\"c156\",\"c157\",\"c158\",\"c160\",\"c161\",\"c168\",\"c178\",\"c199\",\"c200\",\"c223\",\"c225\",\"c228\",\"c237\",\"c238\",\"c239\"],\"layer\":\"main\"},{\"scope\":\"正文 c241—c360\",\"arc\":\"从看似不参与家务、沉默冷淡，到主动牵苏写生、互赠肖像、枕腿和拥抱，林以非语言形式越来越多地表达亲近。她寄钱揭示原生家庭的牵挂，父亲偏爱唯一儿子、虐待姐姐们，使她无法坦然归家。绘画既是收入，也可能是情绪出口：普通瑕疵画会修补保存，抽象画则丢弃；出版的无字画册又与莫的寓言相连。她对苏和天都能给予具体安慰，但内心秘密尚未说明。\",\"segmentFate\":\"截至c360仍同住、从事绘画，与苏持续亲密；家人不知身份，神秘画作含义未解。\",\"refs\":[\"c242\",\"c270\",\"c286\",\"c287\",\"c293\",\"c294\",\"c313\",\"c317\",\"c326\",\"c328\",\"c329\",\"c343\",\"c351\",\"c358\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"她的亲密情感从动作和象征逐步走向明说，春节与雨晴正式相爱。另一边父亲患病和寄款使经济压力升高，神秘外出、名牌与男子现金留下未解线索。一次发热后在医院得知身体发育与原有认知不同，她由难以表达转为公开欢喜，设想回家并与雨晴拥有未来。这些都是书内人物希望，尚未证明生育或婚姻结果。\",\"segmentFate\":\"截至c480活着、与雨晴恋爱，知道检查结果，计划存钱后找父母、再咨询手术；没有在本段实施手术。\",\"refs\":[\"c366\",\"c367\",\"c368\",\"c369\",\"c384\",\"c388\",\"c404\",\"c406\",\"c409\",\"c420\",\"c421\",\"c470\",\"c471\",\"c473\",\"c474\",\"c475\",\"c476\"],\"layer\":\"main\"},{\"scope\":\"正文 c481—c600\",\"arc\":\"第一人称揭开丰富内心与供养依赖；她把父亲医治置于自身手术愿望之前，经济压力升级后接受李任飞处高价侵害，又极力阻止苏受伤。获救后终于说出父病，用苏给予的援助返乡，本希望说明身份、帮父治疗。面对母亲拒绝、父亲殴打禁闭与饥寒，旧伤和长期压抑引发精神崩溃，杀害父母后自杀，临终后悔且不舍苏。\",\"segmentFate\":\"正文c582与父母同亡，c584警方、c587新闻证实；c586短暂苏醒只发生于苏的告别梦中。\",\"refs\":[\"c521\",\"c522\",\"c547\",\"c563\",\"c566\",\"c572\",\"c574\",\"c581\",\"c582\",\"c586\"],\"layer\":\"main\"},{\"scope\":\"c601—c665；x001—x079（全部补充篇）\",\"arc\":\"前传揭示她在三个姐姐之后作为唯一儿子被偏爱，教育资源甚至来自长姐彩礼。这样的爱没有接受真实身份的弹性，青春期后她开始隐瞒身体变化。正文末段只通过雨晴的遗物、发型、婚礼回忆及明确梦境出现，死亡从未被取消。IF则由雨晴陪同返乡改变命运，虽然父母仍死亡，她幸存后与雨晴结婚并生育苏慕夕。\",\"segmentFate\":\"正文：此前已死亡，c660仅梦中重逢。IF：幸存，接受手术、成为苏慕夕母亲并与雨晴结婚。元叙述“夕子”：作者自称失联，不知道是否在世，不能与正文死亡混同。\",\"refs\":[\"c608\",\"c615\",\"c660\",\"x039\",\"x040\",\"x041\",\"x043\",\"x066\",\"x071\",\"x072\"],\"layer\":\"main\"}],\"refs\":[\"c156\",\"c157\",\"c158\",\"c160\",\"c161\",\"c168\",\"c178\",\"c199\",\"c200\",\"c223\",\"c225\",\"c228\",\"c237\",\"c238\",\"c239\",\"c242\",\"c270\",\"c286\",\"c287\",\"c293\",\"c294\",\"c313\",\"c317\",\"c326\",\"c328\",\"c329\",\"c343\",\"c351\",\"c358\",\"c366\",\"c367\",\"c368\",\"c369\",\"c384\",\"c388\",\"c404\",\"c406\",\"c409\",\"c420\",\"c421\",\"c470\",\"c471\",\"c473\",\"c474\",\"c475\",\"c476\",\"c521\",\"c522\",\"c547\",\"c563\",\"c566\",\"c572\",\"c574\",\"c581\",\"c582\",\"c586\",\"c608\",\"c615\",\"c660\",\"x039\",\"x040\",\"x041\",\"x043\",\"x066\",\"x071\",\"x072\"],\"group\":\"核心群像\",\"layer\":\"main\",\"core\":true},{\"id\":\"person-4\",\"name\":\"张思凡\",\"aliases\":[\"月橙\",\"思思\",\"思思姐\",\"橙子\",\"金发女装熟客\",\"张思凡（月橙）\"],\"identity\":\"网名月橙，常被称思思。初登场以女性身份生活，是雨晴姐姐般的朋友；计算机专业大学生。后与孙昊决裂、回到男性社会生活，再与董花火成家。\",\"traits\":[\"外向活泼、爱玩笑：带苏出游、游戏和茶话会\",\"孤独而需要伙伴：收藏双份游戏、生日求苏留下\",\"慷慨互助：赠衣、收留朋友、多付房租，论坛耐心回答新人\",\"冲动花钱、拖延：买手办渔具超预算、常逃选修课\",\"存在越界：数次未经同意触碰苏，不能把此写成纯善亲昵\",\"脆弱被乐观遮掩：惧怕出柜、身体变化与旧创伤\",\"活泼\",\"热心\",\"嘴硬\",\"好胜\",\"精于料理\",\"渴望亲密\",\"边界意识不稳定\",\"外向贪玩：游戏、小说、模型枪和高热量料理\",\"慷慨重友情：送GBA、给孙寄生日礼物、为方请假筹庆生\",\"常偷懒：回避家务又易冲动花钱\",\"边界感不足：谎逗、擅动他人身体，收到批评后仍反复\",\"外向爱玩笑：以早茶、出游、猫狗玩笑化解共同悲伤。\",\"承担日常责任：骑车接送雨晴，给夕晨请假看病、背其上楼。\",\"珍爱手工收藏，被忽视时易冲动：春节与家人激烈冲突后负气返城。\",\"并非永远洒脱：会害怕父母拒绝、恋人背叛，也会羡慕夕晨检查结果。\",\"热心大方：赠苏电动车、电脑，留下集装箱变卖款。\",\"渴望真诚恋爱：为孙搬城、长期容忍分居和可疑解释。\",\"行动果断：分手后迅速剪发、埋旧物、返乡。\",\"善交际且能照顾孩子：蹲下耐心与清雾交谈\",\"回避痛苦与失去：想坦白过去又怕妻子离开，终究保守秘密\",\"前传有求生韧性：遭拘禁侵害后伪装顺从、成功逃脱\"],\"portrait\":\"在熟人面前爱开玩笑，在网上耐心帮助新人，现实生活却长期独居、交友有限。她慷慨照顾雨晴，也曾以玩笑之名越过对方的身体边界；热闹外表下有孤独、自卑与受控制的旧创伤。后来选择改变生活路径，应按个人经历理解。\",\"fate\":{\"name\":\"张思凡\",\"label\":\"婚后收养，开始新生活\",\"tone\":\"green\",\"text\":\"与孙昊决裂后停止女性化，回家并恢复男性社会生活。后来与董花火结婚，在福利院收养林清雾。\",\"note\":\"按经历阶段记录身份与原文代词，不把个人选择上升为所有人的“正确答案”。\",\"refs\":[\"c560\",\"c561\",\"c580\",\"c652\",\"c656\"]},\"status\":\"正文：已婚、收养林清雾，妻子知不育但不知全部过往。IF：继续女性生活，回到朋友群并完成手术。元叙述：作者久未联系，现况未知。\",\"statusRefs\":[\"x038\",\"x043\",\"x059\",\"x060\",\"x061\",\"x075\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"线上热心的月橙在现实中既是活泼姐姐，也是缺乏未来信心的青年。她曾为手术费遭富人虐待，初恋孙昊使她渴望被作为女性珍惜，却也显出依赖和不安全感。带苏酒吧兼职出事后深感内疚，照顾她并退出该工作。之后收留苏与方、支持小玉、承担较多房租，逐步把“有同类在一起”的愿望变成共同生活；自己的学业、收入、家庭秘密和恋情仍不稳定。\",\"segmentFate\":\"截至c120与孙昊恋爱，父母尚不知身份，在读同时做账本录入校对兼职；住白兔小区，郊区屋保留。\",\"refs\":[\"c023\",\"c027\",\"c035\",\"c036\",\"c043\",\"c072\",\"c086\",\"c089\",\"c100\",\"c106\",\"c108\",\"c112\"],\"layer\":\"main\"},{\"scope\":\"正文 c121—c240\",\"arc\":\"外表总是大大咧咧的思思，既有办公室能力与烧烤西餐手艺，也背负被富商控制、侵害的旧创伤。父母催婚使她更依赖孙昊的承诺，她能要求恋人尊重阿牛，却忽视对方只在女装与伪女声时更热情、对室友的窥视与名分淡化。她照护发烧的雨晴，也发起惊吓和强迫亲密的游戏玩笑。肯德基的公开羞辱让她与孙昊冲突，表面和好并未消除不被理解的痛。\",\"segmentFate\":\"与孙昊仍在交往，一周来访尚在进行，工作继续；创伤未解决，恋情已有明显裂缝。\",\"refs\":[\"c130\",\"c140\",\"c141\",\"c143\",\"c189\",\"c190\",\"c191\",\"c208\",\"c209\",\"c210\",\"c211\",\"c212\",\"c222\",\"c227\",\"c240\"],\"layer\":\"main\"},{\"scope\":\"正文 c241—c360\",\"arc\":\"她以笑闹维持家庭热闹，给方的生日惊喜显示真正投入，孙离城后仍寄模型枪维系亲密；但玩笑会让苏被灌醉、让天初访受冒犯，方多次提醒尊重别人同意。阅读幻想小说激发豪言，却不等于此段已精神失常。她储蓄一万多，想实习结束后安排手术仍犹豫，也未对父母坦白。管理员月橙与现实身份的揭示使她成为天进入合租群体的入口。\",\"segmentFate\":\"截至c360仍在实习并同住，与孙维持亲密联系；手术未实施，已邀请天常来。\",\"refs\":[\"c244\",\"c284\",\"c312\",\"c313\",\"c315\",\"c330\",\"c334\",\"c346\",\"c351\",\"c355\",\"c358\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"春节收藏被毁使她误以为父母不重视自己，不知父母正在借钱筹她开店。母亲电话修补关系，却也让她为隐瞒身份犹豫。阿牛死亡后她强作爽朗照顾众人，莜莜离去则触动她对最终只剩自己的恐惧。孙昊来访时她设想毕业后相聚，又试探雨晴的生活安排；带夕晨就医后，她既真心祝福又独自消化比较之苦。\",\"segmentFate\":\"截至c480继续实习并与晴夕同住，恋爱维持；毕业后手术、离城投奔孙昊均只是计划。\",\"refs\":[\"c394\",\"c407\",\"c424\",\"c425\",\"c435\",\"c451\",\"c453\",\"c455\",\"c456\",\"c469\",\"c471\",\"c473\",\"c474\",\"c475\"],\"layer\":\"main\"},{\"scope\":\"正文 c481—c600\",\"arc\":\"前半段仍是大家生活中的支持者，毕业后投奔孙昊，却独居等待对方毕业。恋爱背叛引发严重创伤，也使他重新解释个人身份经历，决定停止女性化；叙述从此使用“他”。回乡被父母接纳并获创业资金，随后与董花火试交往。此改变是他当下自我选择，不能将文中对群体的泛化视为普遍事实。\",\"segmentFate\":\"截至c600在南方家乡，已与孙分手，准备互联网方向创业，并开始与董花火接触。\",\"refs\":[\"c506\",\"c530\",\"c533\",\"c537\",\"c545\",\"c560\",\"c561\",\"c576\",\"c580\"],\"layer\":\"main\"},{\"scope\":\"c601—c665；x001—x079（全部补充篇）\",\"arc\":\"前传揭露他曾为筹手术费接受富商安排，却遭强迫侵害，成功逃离后的创伤给外向形象增添深度。正文福利院重逢时，他已选择新的男性社会生活，与宽容的董花火相爱，也仍隐瞒过往转变经历。得知无法生育后，夫妻转向收养，以养子形成家庭。此选择仅属于正文，IF中的思思则在失恋后保持女性生活，并完成手术、主持朋友婚礼。\",\"segmentFate\":\"正文：已婚、收养林清雾，妻子知不育但不知全部过往。IF：继续女性生活，回到朋友群并完成手术。元叙述：作者久未联系，现况未知。\",\"refs\":[\"c649\",\"c652\",\"c656\",\"x038\",\"x043\",\"x059\",\"x060\",\"x061\",\"x075\"],\"layer\":\"main\"}],\"refs\":[\"c023\",\"c027\",\"c035\",\"c036\",\"c043\",\"c072\",\"c086\",\"c089\",\"c100\",\"c106\",\"c108\",\"c112\",\"c130\",\"c140\",\"c141\",\"c143\",\"c189\",\"c190\",\"c191\",\"c208\",\"c209\",\"c210\",\"c211\",\"c212\",\"c222\",\"c227\",\"c240\",\"c244\",\"c284\",\"c312\",\"c313\",\"c315\",\"c330\",\"c334\",\"c346\",\"c351\",\"c355\",\"c358\",\"c394\",\"c407\",\"c424\",\"c425\",\"c435\",\"c451\",\"c453\",\"c455\",\"c456\",\"c469\",\"c471\",\"c473\",\"c474\",\"c475\",\"c506\",\"c530\",\"c533\",\"c537\",\"c545\",\"c560\",\"c561\",\"c576\",\"c580\",\"c649\",\"c652\",\"c656\",\"x038\",\"x043\",\"x059\",\"x060\",\"x061\",\"x075\"],\"group\":\"核心群像\",\"layer\":\"main\",\"core\":true},{\"id\":\"person-5\",\"name\":\"方莜莜\",\"aliases\":[\"优子\",\"悠悠\",\"莜莜\",\"莜莜姐\",\"方宇悠\",\"宇悠\",\"方莜莜（方宇悠）\"],\"identity\":\"本名方宇悠，网名优子，亦称悠悠。擅厨、从事网络维修工作的伙伴，长期失眠，与安念从《传奇》相识到现实同居。正式外传继续讲述她的感情终局。\",\"traits\":[\"温柔且有边界：抱苏前询问，不追问家庭伤口\",\"擅长照顾：做清淡饭、教切菜做汤、主动让电脑\",\"成熟务实：求职时调整呈现，愿多付房租\",\"也有脆弱：长期失眠、酒后沉默，未详述旧事\",\"温柔\",\"细心\",\"节俭\",\"懂技术\",\"有管理能力\",\"偶有腹黑\",\"家庭感情疏离\",\"温柔负责：免责送餐失误、培养朱志杰、照顾室友饭食\",\"勤奋节制：工作多职并储蓄三万元\",\"渴望关爱又自卑：安念生日蛋糕令其落泪，却怕见面暴露\",\"开始果断：为了恢复时间愿辞去好工作\",\"做事周全：辞职前完成交接，培养朱志杰。\",\"温和而能承担：组织饭食、保管备用钥匙、在急救车上圆融交涉。\",\"能理性劝慰：鼓励阿牛说出困境，认真回应雨晴对死亡的迷思。\",\"恋爱中也脆弱：害怕坦白后遭弃，独居寂寞时一度用反话求关心。\",\"温柔但能主动表达：雨中要求安说明感受、策划未来。\",\"社会经验丰富：懂求职、手续和学习开店。\",\"渴望接纳：在身份暴露和被歧视时脆弱，珍惜安与亲人的照顾。\",\"温柔体谅却容易压抑需要：陪恋人相亲，隐藏自己受到的伤害\",\"关心朋友且能辨别矛盾：查橘子往事，要求他面对现实\",\"边界逐渐明确：获救后拒见安念，以结束联系保护自己\"],\"portrait\":\"温柔细心、能照料一屋人的日常，却常把自己的需求往后放。越是害怕被抛弃，越容易以退让换取关系；正式外传把这种忍耐推到极限，最终以获救与离开收束。\",\"fate\":{\"name\":\"方莜莜\",\"label\":\"外传获救，离开安念\",\"text\":\"正文与安念同居开店；正式外传中难以承受隐秘恋人和被催婚的处境，自杀未遂后由橘子救援。二人均活下来，她拒见安念，关系结束。\",\"note\":\"未写她与橘子确立恋爱，也不能把雨晴早年的死亡噩梦当作莜莜终局。\",\"refs\":[\"c338\",\"c538\",\"c562\",\"x034\",\"x035\"]},\"status\":\"方莜莜篇：自杀未遂获救，存活，与安念彻底分离；未确认与橘子恋爱。IF：与安念共同婚礼，选择不接受手术。元叙述：所谓素材仍与安念异地恋，后段同居与分离明确为作者模拟。正文末段雨晴打其电话已停机，不能靠外传推出死亡。\",\"statusRefs\":[\"x031\",\"x034\",\"x035\",\"x043\",\"x065\",\"x078\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"她以论坛好友优子身份来到张的家，初次相处即通过尊重与从容建立苏的信任。三人生活中苏害怕被冷落，方用邀请参与和“一家人”的说法把她拉回共同生活。擅厨使方成为稳定照护者，专业与学历则帮助她迅速就业并承担较多房租。其家庭只知她外出工作，具体冲突和过往仍未揭开；温婉不意味着没有疲惫或失眠。\",\"segmentFate\":\"截至c120在白兔小区合住，做网络维修部门组长、照料饭食并教苏厨艺；本段无恋情或手术结局。\",\"refs\":[\"c100\",\"c101\",\"c102\",\"c104\",\"c105\",\"c106\",\"c107\",\"c108\",\"c120\"],\"layer\":\"main\"},{\"scope\":\"正文 c121—c240\",\"arc\":\"她在公司独撑新部门、教初中毕业的朱志杰修电脑，在家又常为大家安排食物与日常。与思思的互损最默契，台风时替其请假、照料雨晴，能理解同性爱情也会参与令雨晴不自在的起哄。身世补出失联生母和关系淡薄的父亲继母，说明她对家庭的向往与现有家庭并不相同。传奇里被有条色狼救下后建立公会、交换姓名，产生持续新联系，但明确还只是朋友。\",\"segmentFate\":\"继续工作和合租，与安念关系友好未成恋人；家庭状态仍疏远。\",\"refs\":[\"c131\",\"c143\",\"c149\",\"c150\",\"c151\",\"c152\",\"c173\",\"c174\",\"c177\",\"c191\",\"c223\",\"c225\",\"c226\"],\"layer\":\"main\"},{\"scope\":\"正文 c241—c360\",\"arc\":\"职业能力日渐得到肯定，身份秘密却让她无法直接以女性形象工作。与安念从游戏协作、语音到生日蛋糕逐步产生暧昧，她把被记得的生日看得很重，这与幼年生母不要她、父亲和继母相继疏离的家事呼应。她在合租屋持续承担母亲式照护，也提醒张尊重来客边界。存款达到三万元后，她决定不再等机会，计划辞职安排手术，却仍不向父母与安坦白原因。\",\"segmentFate\":\"截至c360报告已写、辞职和手术未展示实施；仍在公司工作，和安未正式确立恋爱。\",\"refs\":[\"c241\",\"c242\",\"c260\",\"c285\",\"c325\",\"c331\",\"c332\",\"c346\",\"c358\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"她为手术退出稳定工作，真实坦白后获安念接纳，形成与阿牛隐瞒支线的对照。公益行动让她看见外界偏见，阿牛之死则打破共同住所的安全感。她回到武汉附近旧家，既是求职选择，也是离开伤心小城的需要。独处后她学习直接向安念表达寂寞，并找到武汉市内新工作，友情与爱情改以远距离维系。\",\"segmentFate\":\"截至c480住武汉附近城中村旧家，已开始武汉工作；去势已完成，后续转变未完成；与安念六月见面尚未来临。\",\"refs\":[\"c382\",\"c389\",\"c394\",\"c397\",\"c398\",\"c401\",\"c414\",\"c415\",\"c426\",\"c448\",\"c450\",\"c452\",\"c453\",\"c457\",\"c469\"],\"layer\":\"main\"},{\"scope\":\"正文 c481—c600\",\"arc\":\"六月赴杭州庆生确认现实恋情，长期旧友杨的存在使她与安讨论依赖与边界。八月两人移居宁波，她以男装学奶茶，终于在自家店按更合心意的呈现工作。公交性骚扰、身体不适及车祸纠纷让她反复体验弱势，安的保护强化信任。春节回武汉仍称伴侣为女友隐藏身份，却从表哥热情中获得温暖。\",\"segmentFate\":\"截至本段与安恋爱及共同经营关系持续，春节分别回家后续尚未详写。\",\"refs\":[\"c507\",\"c511\",\"c517\",\"c538\",\"c550\",\"c562\",\"c578\"],\"layer\":\"main\"},{\"scope\":\"c601—c665；x001—x079（全部补充篇）\",\"arc\":\"在海宁她先获得恋人、店铺和好友构成的生活，也试着不再与父亲彻底断联。对橘子，她既追查失真记忆，又拒绝成为姜琳替代者；轮到自己的爱情，却把退让和不要求当作爱。安念父母的排斥、他的回避与相亲令她陷入危机。橘子及时救回她后，她终于明确结束与安念的联系，故事没有再给她安排已经成立的新恋情。\",\"segmentFate\":\"方莜莜篇：自杀未遂获救，存活，与安念彻底分离；未确认与橘子恋爱。IF：与安念共同婚礼，选择不接受手术。元叙述：所谓素材仍与安念异地恋，后段同居与分离明确为作者模拟。正文末段雨晴打其电话已停机，不能靠外传推出死亡。\",\"refs\":[\"c649\",\"x002\",\"x027\",\"x028\",\"x030\",\"x031\",\"x034\",\"x035\",\"x043\",\"x065\",\"x078\"],\"layer\":\"fang\"}],\"refs\":[\"c100\",\"c101\",\"c102\",\"c104\",\"c105\",\"c106\",\"c107\",\"c108\",\"c120\",\"c131\",\"c143\",\"c149\",\"c150\",\"c151\",\"c152\",\"c173\",\"c174\",\"c177\",\"c191\",\"c223\",\"c225\",\"c226\",\"c241\",\"c242\",\"c260\",\"c285\",\"c325\",\"c331\",\"c332\",\"c346\",\"c358\",\"c382\",\"c389\",\"c394\",\"c397\",\"c398\",\"c401\",\"c414\",\"c415\",\"c426\",\"c448\",\"c450\",\"c452\",\"c453\",\"c457\",\"c469\",\"c507\",\"c511\",\"c517\",\"c538\",\"c550\",\"c562\",\"c578\",\"c649\",\"x002\",\"x027\",\"x028\",\"x030\",\"x031\",\"x034\",\"x035\",\"x043\",\"x065\",\"x078\"],\"group\":\"核心群像\",\"layer\":\"main\",\"core\":true},{\"id\":\"person-6\",\"name\":\"胡玉牛\",\"aliases\":[\"小玉\",\"老牛\",\"阿牛\",\"胡玉牛（小玉）\"],\"identity\":\"武艺传承家庭中的年轻人，常称阿牛、小玉，外形强健而有女性愿望。在超市工作，是合租伙伴，与柳韵相恋；身份秘密与复仇链交汇在他身上。\",\"traits\":[\"温和克制：进入院前询问、耐心讲植物\",\"强壮与细腻并存：制服混混、帮搬行李，却羡慕纤细身材\",\"重视自主：反问为什么无权选择，坚持女性愿望\",\"愿帮人且节省：救少年、替同伴提重物、午餐省钱\",\"勤劳\",\"原本温和\",\"强烈自卑\",\"责任感\",\"敏感易怒\",\"倔强\",\"渴望美丽\",\"温厚体贴：救人、做饭、接送并护便当\",\"责任与胆怯并存：怕伤柳而拒绝，后来又长期延后坦白\",\"自卑疏远：不愿同行、常不归家，最信任苏\",\"强大外表下脆弱：体力变化与恋爱依赖加深\",\"质朴勤劳、擅厨艺：为柳韵做土豆饼、红豆粥，也体贴分担餐桌食物。\",\"习惯独自承受并延迟说明：对父母、恋人隐瞒转变，对室友拒说危机。\",\"对关系非常依恋，面对误会易迁怒：认定柳韵合谋后不肯听解释。\",\"脆弱并非来自外形：平日壮硕沉默，独处时长期自卑、哭泣与孤独。\",\"曾保护伙伴：苏回忆其解围行动。\",\"渴望女性身份呈现，遭外貌与处境困扰。\",\"重责任：十三岁努力练剑，希望超越父亲\",\"愿回头承担：IF获救后向家人坦白、与柳韵和好并放下报复\",\"压力来源复杂：家族期待与性别道路冲突，不能简化为单一成因\"],\"portrait\":\"朴实、重情，有保护他人的勇气，也因家庭责任和外貌焦虑不断自我否定。他隐瞒关键事实，又在受伤时难以相信解释，使本可沟通的关系在压力中断裂。\",\"fate\":{\"name\":\"胡玉牛\",\"label\":\"抢救无效死亡\",\"tone\":\"red\",\"text\":\"秘密暴露后承受家庭拒绝、误会分手和职场羞辱。自伤后被发现仍有呼吸，但送医抢救无效。\",\"note\":\"柳韵曾决定放下报复，信在胡家被发现源于遗落；这不等于她主动把信交给胡父母。\",\"refs\":[\"c438\",\"c441\",\"c444\",\"c446\",\"c448\",\"c450\"]},\"status\":\"本段开始前已死亡；公墓是衣冠冢，骨灰另葬家乡村边。\",\"statusRefs\":[\"c481\",\"c487\",\"c575\",\"c588\",\"c599\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"初见时的声音和举止让苏感到反差，后经采药、救人显示可靠与善良。家族要求继承武艺和身体外形共同压迫其女性愿望。看见苏药盒后终于确认遇到同类，坦白不想做家主与男子汉。苏的劝阻引发关于选择权的争执，胡道歉却不放弃。之后参与四人合租、以劳动支撑生活，并接受“小玉”这个想要的称呼。体貌焦虑到段末仍持续。\",\"segmentFate\":\"截至c120在白兔小区合住、大润发装卸工作，已坚持走性别转变道路；没有手术或稳定效果的事实，本段未给具体年龄。\",\"refs\":[\"c054\",\"c055\",\"c060\",\"c085\",\"c086\",\"c097\",\"c098\",\"c108\",\"c109\",\"c112\",\"c117\",\"c120\"],\"layer\":\"main\"},{\"scope\":\"正文 c121—c240\",\"arc\":\"他会做精致饭食、搬重物并照顾雨晴，习武形成的强健体格却成为最痛苦的身份阻碍。与美丽室友同处时持续比较，获得女装肯定也无法抵消自我否定；私诊注射、激光除毛与限制进食显示急切，恢复吸烟、独自出门、锁门和短暂轻生念头显示恶化。台风游戏中他仍能挺身查看危险、参与玩笑、安定众人，说明关怀能力未消失，但结尾仍避开雨晴同行。\",\"segmentFate\":\"继续后仓工作并寻求身体改变；截至c240未做所议手术、未实施自杀，仍活着且与室友渐疏离。\",\"refs\":[\"c123\",\"c134\",\"c157\",\"c168\",\"c169\",\"c178\",\"c184\",\"c191\",\"c205\",\"c206\",\"c209\",\"c219\",\"c227\",\"c236\"],\"layer\":\"main\"},{\"scope\":\"正文 c241—c360\",\"arc\":\"柳的主动爱慕使他首次觉得被无条件需要，经历拒绝、救援、冷静期后终于说爱。但柳珍爱的男性力量与他想改变的身体重叠，让幸福同时成为束缚。他返家面对父母照顾与家族武馆衰落，也不敢说真相。药物经历有继续、注射、短暂停用等变化，均未解决内在选择。天语遥的重伤让他愧疚又生出被动获得改变的羡慕；旧仇公开后他暂离冲突，却已被追踪。\",\"segmentFate\":\"截至c360仍与柳相爱但隐瞒女性愿望，约定未来杭州和过年；天及旧部已找他，实际报复未发生。\",\"refs\":[\"c245\",\"c248\",\"c250\",\"c280\",\"c283\",\"c291\",\"c292\",\"c307\",\"c327\",\"c334\",\"c349\",\"c354\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"在家庭传承压力、转变愿望与爱恋之间，他始终希望可以同时维持一切，未形成坦诚协商。天语遥搜集证据并公开他的隐私后，父母反对、恋情误会与职场排斥接连发生。他把柳韵意外遗落信件误认成合谋，拒绝同伴帮助，最终在心理危机中严重自伤，虽被发现时仍活着，送医抢救无效。原文多次用逃避归责，分析应同时呈现隐私伤害、污名压力和失去支持。\",\"segmentFate\":\"正文c450抢救无效死亡，c451火化，c452葬礼；这是本段已明确的死亡，不是梦或IF情节。\",\"refs\":[\"c379\",\"c383\",\"c429\",\"c432\",\"c433\",\"c438\",\"c442\",\"c443\",\"c444\",\"c446\",\"c447\",\"c448\",\"c449\",\"c450\",\"c451\",\"c452\"],\"layer\":\"main\"},{\"scope\":\"正文 c481—c600\",\"arc\":\"他的死亡持续推动天的愧疚、柳的报复和苏对群体互相关照不足的反思。苏送别林后祭其公墓衣冠冢，莫空后来以庙烛谈及一条未实现的幸福可能，柳则以冷硬言辞掩饰哀伤。莫空对秋讲“写文很好”的故事是明说的编造。\",\"segmentFate\":\"本段开始前已死亡；公墓是衣冠冢，骨灰另葬家乡村边。\",\"refs\":[\"c481\",\"c487\",\"c575\",\"c588\",\"c599\"],\"layer\":\"main\"},{\"scope\":\"c601—c665；x001—x079（全部补充篇）\",\"arc\":\"前传把英雄般的父亲和家族重担放在一起，母亲温柔照顾又担忧儿子的未来。IF从及时救援改写死亡分岔，使他有机会重新选择身体道路、对恋人家人负责，并愿面对与天语遥的冲突。后来的武馆经营和大学社团资金显示生活能够继续；正文死亡仍应保留，不由这个分支覆盖。\",\"segmentFate\":\"正文此前已死亡（本段通过IF和元叙述对照）；IF：获救、停止转变，与柳韵和好并计划结婚，武馆发展。元叙述：作者称素材是仍生活工作的司机，另一层。\",\"refs\":[\"x036\",\"x041\",\"x043\",\"x063\",\"x077\"],\"layer\":\"if\"}],\"refs\":[\"c054\",\"c055\",\"c060\",\"c085\",\"c086\",\"c097\",\"c098\",\"c108\",\"c109\",\"c112\",\"c117\",\"c120\",\"c123\",\"c134\",\"c157\",\"c168\",\"c169\",\"c178\",\"c184\",\"c191\",\"c205\",\"c206\",\"c209\",\"c219\",\"c227\",\"c236\",\"c245\",\"c248\",\"c250\",\"c280\",\"c283\",\"c291\",\"c292\",\"c307\",\"c327\",\"c334\",\"c349\",\"c354\",\"c379\",\"c383\",\"c429\",\"c432\",\"c433\",\"c438\",\"c442\",\"c443\",\"c444\",\"c446\",\"c447\",\"c448\",\"c449\",\"c450\",\"c451\",\"c452\",\"c481\",\"c487\",\"c575\",\"c588\",\"c599\",\"x036\",\"x041\",\"x043\",\"x063\",\"x077\"],\"group\":\"核心群像\",\"layer\":\"main\",\"core\":true},{\"id\":\"person-7\",\"name\":\"天语遥\",\"aliases\":[\"天冲云\",\"小天\",\"小遥\",\"软陶\",\"冲哥\",\"云兄\",\"冲云\",\"阿天\",\"天语遥（天冲云）\"],\"identity\":\"原名天冲云，曾是混混头目。重伤后被父母强迫走向女性化生活并改名；父亲后来愿意退让时，她又亲口选择称小遥、做女儿。此后的认同仍伴随持续痛苦、复仇、幻觉与严重创伤，恋人为夏归月。\",\"traits\":[\"暴躁重面子：早期否认眼泪、虚报身高、拒承认妆好看\",\"有手艺与耐心：自学软陶精做骰子、大黑像\",\"关爱动物：专喂大黑、研究照顾饼干\",\"认知矛盾：想被尊重却难理解主动改变者，仍保留对女性的工具观\",\"旧义气与复仇：被兄弟接纳打动，同时部署报复\",\"倔强维护尊严：受辱仍反击，讨厌他人怜悯。\",\"能长期筹谋且伤害性强：伪装和解、入住搜证，设计两渠道曝光。\",\"对爱人温柔却替对方决定：爱归月仍擅自断联，拒绝共同承担。\",\"失去目标后深度空虚：反复把幻想的归月当陪伴，现实感逐渐混乱。\",\"强烈渴望被爱：梦中反复与夏相守。\",\"逃避、自责与创造并存：依赖感官麻痹痛苦，又以陶人帮助他人。\",\"意识碎裂：理想化回忆与现实创伤交缠。\",\"早期机灵求异：课堂与人生愿望反复强调领导别人\",\"强硬控制与保护并存：救夏归月时也主动经营英雄形象\",\"末段状态不能当作性格选择：需要他人持续照护\"],\"portrait\":\"既曾主动伤害别人，也是后续强迫与暴力的受害者。她的倔强、控制欲、羞耻与被爱渴望交织；理解她的痛苦并不等于替其最初侵害和后来的报复开脱。\",\"fate\":{\"name\":\"天语遥\",\"label\":\"存活，长期需照护\",\"text\":\"经历强迫、复仇、自伤与严重侵害，获救后长期无法独立生活。末次回访由父母与夏归月照顾，只有短暂回应和好转希望。\",\"note\":\"她最初的女性化并非自愿；后续的复杂选择与依恋也应保留。原著的精神医学说法只作文本记录。\",\"refs\":[\"c296\",\"c302\",\"c487\",\"c490\",\"c499\",\"c649\",\"c650\"]},\"status\":\"正文末段存活但严重失能，只短暂回应，未确认康复。IF：放弃复仇和自伤，和夏归月到外地上大学。元叙述另有素材移植，不能混为正文事实。\",\"statusRefs\":[\"c649\",\"c650\",\"x037\",\"x069\",\"x070\",\"x076\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"起初作为侵害柳的反派，重伤和父母替其定人生后承受身份断裂；自伤获救促父母反思，她清醒选择作为小遥生活，却并未因此不再痛苦。软陶与兔子给她新支点，亲子关系逐渐柔化，论坛与合租屋来访又打开对性别的认识和自我外观可能。她始终隐瞒被动经历，天生应怎样才算女性的错误观念仍在。重遇胡令创伤复燃并短暂失忆，老三的接纳消息恢复记忆，最后她重返帮派以复仇支撑生存。\",\"segmentFate\":\"截至c360获旧部热烈迎回，已布置寻找胡但未报复；仍有自毁念头、失控恐惧与身份冲突，新朋友不知旧仇。\",\"refs\":[\"c295\",\"c296\",\"c301\",\"c302\",\"c314\",\"c324\",\"c337\",\"c349\",\"c350\",\"c355\",\"c358\",\"c359\",\"c360\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"被老六羞辱后自伤获救，真实重逢夏归月带来短暂安慰，却未消除复仇。她以谅解获取阿牛与室友信任，私下搜证、制造关系与舆论打击；亲见阿牛葬礼后换号斩断过去，随之失去目标。她尝试女性生活、陶艺与游戏，却不断沉溺虚构重逢。归月真正找来时仍被她推开，随后雨晴偶遇其危机并叫母亲接回。她的受创不能抵消报复造成的伤害。\",\"segmentFate\":\"截至c480活着，由母亲接回；报复已导致严重后果，未表示悔意，心理危机未解决，与归月没有恢复稳定关系。\",\"refs\":[\"c361\",\"c363\",\"c365\",\"c373\",\"c376\",\"c380\",\"c387\",\"c399\",\"c431\",\"c434\",\"c445\",\"c458\",\"c463\",\"c464\",\"c467\",\"c468\",\"c472\",\"c477\",\"c479\",\"c480\"],\"layer\":\"main\"},{\"scope\":\"正文 c481—c600\",\"arc\":\"她试图以蓝色陪伴填补空缺，却被控制并落入柳韵报复。夏与黄枸救出后生命稳定，长久昏迷中创造理想世界，尝试掌握命运，帮助小蓝和叶雯。醒来后严重精神失序，无法回到旧生活；现实夏始终守候，与梦中另有男友的夏不可混淆。\",\"segmentFate\":\"截至c600仍被提及严重精神错乱，存活；没有恢复完整认知或死亡的后续描写。\",\"refs\":[\"c481\",\"c488\",\"c490\",\"c493\",\"c497\",\"c498\",\"c499\",\"c589\",\"c599\"],\"layer\":\"main\"},{\"scope\":\"c601—c665；x001—x079（全部补充篇）\",\"arc\":\"前传从野心和帮派生活解释早年控制欲，也揭示初救夏归月是无意闯入老六设局。正文末段，她已不能自理，由伴侣和父母守护；见莫空后叫出小黑，又短暂唤夏归月月月，给照料者希望，但并未完全醒转。IF另写夏归月及时劝阻报复，使她主动重新期待学习与日常，构成不同命运。\",\"segmentFate\":\"正文末段存活但严重失能，只短暂回应，未确认康复。IF：放弃复仇和自伤，和夏归月到外地上大学。元叙述另有素材移植，不能混为正文事实。\",\"refs\":[\"c649\",\"c650\",\"x037\",\"x069\",\"x070\",\"x076\"],\"layer\":\"main\"}],\"refs\":[\"c295\",\"c296\",\"c301\",\"c302\",\"c314\",\"c324\",\"c337\",\"c349\",\"c350\",\"c355\",\"c358\",\"c359\",\"c360\",\"c361\",\"c363\",\"c365\",\"c373\",\"c376\",\"c380\",\"c387\",\"c399\",\"c431\",\"c434\",\"c445\",\"c458\",\"c463\",\"c464\",\"c467\",\"c468\",\"c472\",\"c477\",\"c479\",\"c480\",\"c481\",\"c488\",\"c490\",\"c493\",\"c497\",\"c498\",\"c499\",\"c589\",\"c599\",\"c649\",\"c650\",\"x037\",\"x069\",\"x070\",\"x076\"],\"group\":\"核心群像\",\"layer\":\"main\",\"core\":true},{\"id\":\"person-8\",\"name\":\"夏归月\",\"aliases\":[\"月月\",\"小月\"],\"identity\":\"天冲云、后来的天语遥的恋人，多次寻找对方，并在其长期失去生活能力后继续陪伴照顾。\",\"traits\":[\"温柔而有主见：得知天遭遇后重新选择相恋。\",\"细心照料：改火锅锅底、陪爬山、扶她休息。\",\"尊重关系共同承担：真正找到人后坚持困难应一起面对。\",\"信息与经验不足：长时间误以为失联只是情绪或忙碌。\",\"坚定有行动：确认愿意留下、拿地址赶赴危险现场。\",\"耐心温柔：床边做作业、聊天、握手，描绘共同旅行。\",\"坚韧守信：即使伴侣失能也与父母轮换照护\",\"珍惜关系：持续缴电话费保留失联朋友再联系的可能\",\"劝解细致：IF用具体生活愿景帮助伴侣放弃报复\"],\"portrait\":\"乐观、坚韧，重视具体的人而愿意重新理解身份变化。她的坚持并非作者已经保证“必然治好”的承诺，而是在没有确定回报时仍然选择当下的陪伴。\",\"fate\":{\"name\":\"夏归月\",\"label\":\"继续陪伴天语遥\",\"text\":\"多次寻找失联的天语遥，获知其病况后仍选择陪伴。雨晴后来回城时，她仍在照护对方。\",\"note\":\"早前有几段幻觉中的相聚，但c479重逢及c650照护属于真实正文。\",\"refs\":[\"c376\",\"c463\",\"c468\",\"c479\",\"c499\",\"c650\"]},\"status\":\"正文终局前最后明确状态为持续照料天语遥，未来是否康复未交代。IF与天语遥共同上大学并参加婚礼。\",\"statusRefs\":[\"c649\",\"c650\",\"x037\",\"x041\",\"x043\",\"x070\"],\"segments\":[{\"scope\":\"正文 c361—c480\",\"arc\":\"她从当年性格不合和平分手，到偶遇虚弱的天语遥后重新选择爱情，享受对方不再强控的亲密。她期待未来婚姻，不知道天语遥一面爱她一面计划报复和离别。近一个月后确认断联，主动缴费、逃课寻找，在被黄枸隐瞒后终于借莫空指路找到人。面对对方幻觉，她把责问转成关心，仍无法阻止再次逃离。\",\"segmentFate\":\"截至c480还活着；c479真实重逢以天逃离、她哭泣结束，未成为梦中妻子，没有儿女或实际婚礼。\",\"refs\":[\"c375\",\"c376\",\"c377\",\"c378\",\"c392\",\"c393\",\"c422\",\"c428\",\"c458\",\"c463\",\"c478\",\"c479\"],\"layer\":\"main\"},{\"scope\":\"正文 c481—c600\",\"arc\":\"面对天过去的伤害和分离，她依旧想救回彼此的关系。莫空的询问迫使她确认自己的决心；救援后，她没有因父母疑虑或医生悲观判断离开。昏迷梦中的夏形象承载天的愿望与恐惧，不能替代现实夏的选择。\",\"segmentFate\":\"截至本段末次实质描写，仍陪伴精神状态严重受损的天。\",\"refs\":[\"c489\",\"c490\",\"c491\",\"c492\",\"c499\"],\"layer\":\"main\"},{\"scope\":\"c601—c665；x001—x079（全部补充篇）\",\"arc\":\"前传相遇时她有礼而谨慎，被救后接受联系方式却拒绝无必要的护送。正文末段她面对长期病况仍守在天语遥身边，雨晴来访时平静解释艰辛，把短暂叫出月月视为珍贵希望。IF中她的陪伴提前生效，阻断仇恨链并与天语遥共同走向校园。\",\"segmentFate\":\"正文终局前最后明确状态为持续照料天语遥，未来是否康复未交代。IF与天语遥共同上大学并参加婚礼。\",\"refs\":[\"c649\",\"c650\",\"x037\",\"x041\",\"x043\",\"x070\"],\"layer\":\"main\"}],\"refs\":[\"c375\",\"c376\",\"c377\",\"c378\",\"c392\",\"c393\",\"c422\",\"c428\",\"c458\",\"c463\",\"c478\",\"c479\",\"c489\",\"c490\",\"c491\",\"c492\",\"c499\",\"c649\",\"c650\",\"x037\",\"x041\",\"x043\",\"x070\"],\"group\":\"亲密关系\",\"layer\":\"main\",\"core\":true},{\"id\":\"person-9\",\"name\":\"柳韵\",\"aliases\":[\"音音\",\"柳姐\",\"柳韵（音音）\"],\"identity\":\"常用名音音，与胡玉牛相恋，既受过他的保护，也在他死后将仇恨转向天语遥。\",\"traits\":[\"主动坦率：先告白、给冷静期、说不喜欢便不强求\",\"依恋又体贴：不愿胡受伤，分享饭食、替他充话费\",\"少女气与吃醋：撒娇、逗弄、对合租女孩警惕\",\"浪漫想象：山居、爱情锁、杭州与跨年约定\",\"外柔内强且表现随情境变化：恋人面前娇俏，班级里强势。\",\"有身份偏见也能反省：匿名信后想报复，真见胡家却于心不忍。\",\"实际危机中果断：看短信后赶到公寓，坚持开门抢救。\",\"珍惜真情但保留自己的生活：解释失败后分手，死亡后悲伤仍继续人生。\",\"哀伤与攻击性相缠：把对胡的爱转为报复天。\",\"善于操纵：利用照片、男性欲望推动暴力。\",\"冷硬外表下难掩痛苦：墓前狠话后落泪。\"],\"portrait\":\"她有真实的爱，也有偏见和冲动。得知秘密后曾主动放下报复，并愿意解释意外遗信；失去爱人后却转向严重的报复性伤害，不能用其中一面抹掉另一面。\",\"fate\":{\"name\":\"柳韵\",\"label\":\"复仇后个人去向未明\",\"text\":\"失去胡玉牛后策动对天语遥的报复，后来仍到胡玉牛衣冠冢前悼念。她本人是否被司法追责、此后去向均未交代。\",\"note\":\"第499章未具名的主谋、从犯判决不能直接对应到柳韵；第588章仍写她亲自前往墓园悼念。\",\"refs\":[\"c444\",\"c450\",\"c487\",\"c499\",\"c588\"]},\"status\":\"截至本段仍存活、曾来祭胡；是否因策动天案被追责未写。\",\"statusRefs\":[\"c487\",\"c488\",\"c588\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"三次超市帮助令她爱上胡的可靠与力量，拒绝后因误认狐女大衣继续追求，险遭侵害后又被胡救出。她买狮子信物、保留白熊、写满爱语，把胡视为重要伴侣；共同做面和接送转成稳定日常。她尚不知胡的愿望及合租者身份，生日来访的吃醋正反映误认。面对天控诉，她清楚指出当初侵害事实，却也在其哭泣时起恻隐之心。未来约定仍只停留在期待。\",\"segmentFate\":\"截至c360仍与胡恋爱，核心秘密未知，面临天旧部敌意；未购爱情锁，未实现毕业杭州计划。\",\"refs\":[\"c245\",\"c249\",\"c250\",\"c290\",\"c291\",\"c305\",\"c308\",\"c318\",\"c333\",\"c349\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"最初阿牛以为自己了解她，实际上她的强势、情感经历与害怕受伤都未被充分理解。得知秘密时她被恶意信引向报复，却在重见恋人与其父母后改变主意；信件意外遗落仍造成曝光。她试图坦白并愿帮忙，阿牛把意外当阴谋，关系终告破裂。危机短信使她赶去求救，随后向父母与室友说明所知，但当时并不知超市全部舆论压力。\",\"segmentFate\":\"截至c480活着，已与阿牛分手并参加其葬礼；将这段爱情放入记忆，后续生活未在本段展开。\",\"refs\":[\"c379\",\"c419\",\"c432\",\"c433\",\"c436\",\"c437\",\"c438\",\"c439\",\"c440\",\"c442\",\"c444\",\"c449\",\"c450\",\"c451\",\"c452\"],\"layer\":\"main\"},{\"scope\":\"正文 c481—c600\",\"arc\":\"她以胡为唯一深爱的人，失去后在新的关系网中认出天，主动放大他人对天的侵害，以为报复能够回应悲伤。后来到衣冠冢说不再来，眼泪却显示旧情并未结束。她的受伤感不取消其策划侵害的责任。\",\"segmentFate\":\"截至本段仍存活、曾来祭胡；是否因策动天案被追责未写。\",\"refs\":[\"c487\",\"c488\",\"c588\"],\"layer\":\"main\"}],\"refs\":[\"c245\",\"c249\",\"c250\",\"c290\",\"c291\",\"c305\",\"c308\",\"c318\",\"c333\",\"c349\",\"c379\",\"c419\",\"c432\",\"c433\",\"c436\",\"c437\",\"c438\",\"c439\",\"c440\",\"c442\",\"c444\",\"c449\",\"c450\",\"c451\",\"c452\",\"c487\",\"c488\",\"c588\"],\"group\":\"亲密关系\",\"layer\":\"main\",\"core\":true},{\"id\":\"person-10\",\"name\":\"安念\",\"aliases\":[\"有条色狼\",\"狼神大人\",\"有只银娘\"],\"identity\":\"《传奇》中名有条色狼，另用女号有只银娘，与方莜莜相恋并同居开店。家庭婚育期待在正式外传中成为关系的重要压力。\",\"traits\":[\"主动援助\",\"谈得来\",\"分享资源\",\"游戏投入\",\"幽默机灵：善用玩笑和带地图制造共同体验\",\"游戏中机会主义：抢稀有装备甚至杀救助者角色引围攻\",\"关心细致：记资料卡生日、送真实蛋糕\",\"亲近但尚不知真相：以为方是顺性别女孩\",\"接纳：听完莜莜身份与手术坦白仍明确愿意交往。\",\"直率而不善猜暗示：把莜莜说不寂寞、去睡觉当字面意思。\",\"日常关心稳定：记得新工作第一天发早安提醒。\",\"风趣纯情：与母亲斗嘴、受夸害羞，明确说爱情会深化。\",\"肯付出且务实：搬重货攒钱、争取保安亭、主动分担店务。\",\"冲突中容易升级：保护方时两度殴打对方，不能只写完美英雄。\",\"关心伴侣却难作决定：承诺不负莜莜，仍答应父母相亲\",\"回避公开冲突：瞒恋爱同居，把莜莜介绍为朋友\",\"失去后才清楚代价：急奔医院、试图再联系，最终只能接受分离\"],\"portrait\":\"\",\"fate\":{\"name\":\"安念\",\"label\":\"与莜莜分离\",\"text\":\"在家庭压力下参加与苏凝的相亲；莜莜获救后退出他的生活。苏凝继续陪伴，他逐渐接受分离，仍无法忘记莜莜。\",\"note\":\"正式外传没有写他已经与苏凝结婚；与莜莜的现实婚礼只在幸福IF中出现；正文另有《传奇》游戏婚礼。\",\"refs\":[\"c382\",\"x033\",\"x034\",\"x035\",\"x042\",\"x043\"]},\"status\":\"截至本段奶茶店生意改善，与方仍相爱，春节回杭州见父母。\",\"statusRefs\":[\"c543\",\"c550\",\"c552\",\"c562\",\"c565\",\"c578\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"莜莜以新角色优子玩传奇，被怪物围困时获他的治疗与保护，又受赠工具一起进入矿区，第一次在游戏里结识愿意带自己的朋友。他虽用顽皮网名，实际在本段表现为耐心相伴。两人发现相隔不远，继续聊天并交换姓名与QQ，参与建立春宫阁。莜莜愿意提及这个新朋友，但在台风聊天时明确否认已是男朋友。\",\"segmentFate\":\"与莜莜保持游戏与QQ联系，尚未线下相见或确定恋爱。\",\"refs\":[\"c151\",\"c152\",\"c173\",\"c174\",\"c226\"],\"layer\":\"main\"},{\"scope\":\"正文 c241—c360\",\"arc\":\"与方合作抢戒指后因语音听见女声，两人开始更亲密交流，他承诺共享收益，也不断逗她开心。以暂放物品为由获得代收地址，随后按生日资料订蛋糕及发祝福，把线上关系转化为现实可触的关心。方决定辞职时他也询问原因，双方隐约盼靠近，却仍无正式表白。他不知道方的性别经历及辞职真因，后续接受与否不可提前补写。\",\"segmentFate\":\"截至c360仍与方暧昧往来，生日礼物已送，实际见面和正式恋爱未发生。\",\"refs\":[\"c284\",\"c285\",\"c326\",\"c331\",\"c344\",\"c346\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"他起初通过网络和游戏与莜莜相恋，为婚礼切换女性角色，构成虚拟世界可自由分配身份的片段。莜莜真实坦白时，他以自己童年的性别愿望帮助理解，维持感情。独居后两人的沟通仍需学习，尤其她的反话与他的直线思维常错位；明确说出需要后，他愿意回应。\",\"segmentFate\":\"截至c480与莜莜维持网恋，计划2005年六月生日见面；尚未现实相会或结婚。\",\"refs\":[\"c382\",\"c401\",\"c407\",\"c457\",\"c469\"],\"layer\":\"main\"},{\"scope\":\"正文 c481—c600\",\"arc\":\"他从网络恋人走入现实家庭和生活，虽介意杨的介入仍尝试尊重方，雨中坦白感情。宁波劳动使体型和能力变化，创业从幻想变成小店。许愿树、奇鱼和裙子寄托相伴、减重与女装体验愿望；公共侵害与纠纷时将方置于生意之前，但会以激烈方式回应挑衅。\",\"segmentFate\":\"截至本段奶茶店生意改善，与方仍相爱，春节回杭州见父母。\",\"refs\":[\"c507\",\"c517\",\"c538\",\"c543\",\"c550\",\"c552\",\"c562\",\"c565\",\"c578\"],\"layer\":\"main\"},{\"scope\":\"c601—c665；x001—x079（全部补充篇）\",\"arc\":\"他对莜莜的感情是真实的，海宁日常也有相互照料；问题在于无法把私人承诺落实到家庭面前。返乡后他享受父母团聚，却让莜莜独自住宾馆并陪自己相亲。危机发生后，他与父母、朋友才一起看见伤害，但救援并不恢复关系。苏凝的陪伴使他逐渐回到生活，文本保留难以忘怀而未确认婚姻。\",\"segmentFate\":\"方莜莜篇：与莜莜分离，被橘子绝交，后在苏凝陪伴下恢复生活但未忘旧爱。IF：父母车祸死亡后与莜莜结婚。元叙述：仍异地交往，未来未定。\",\"refs\":[\"x002\",\"x029\",\"x030\",\"x033\",\"x035\",\"x042\",\"x043\",\"x078\"],\"layer\":\"fang\"}],\"refs\":[\"c151\",\"c152\",\"c173\",\"c174\",\"c226\",\"c284\",\"c285\",\"c326\",\"c331\",\"c344\",\"c346\",\"c382\",\"c401\",\"c407\",\"c457\",\"c469\",\"c507\",\"c517\",\"c538\",\"c543\",\"c550\",\"c552\",\"c562\",\"c565\",\"c578\",\"x002\",\"x029\",\"x030\",\"x033\",\"x035\",\"x042\",\"x043\",\"x078\"],\"group\":\"亲密关系\",\"layer\":\"main\",\"core\":true},{\"id\":\"person-11\",\"name\":\"曲奇\",\"aliases\":[\"黑猫\"],\"identity\":\"陪伴苏雨晴的蓝眼黑猫，由流浪伙伴成为家人，与鼠咖啡关系亲近，后随雨晴迁台。早期称母猫，后期与前传又称公猫，原书性别设定前后不一致。\",\"traits\":[\"自主警觉：初见不让摸，按自己意愿来去\",\"聪明亲人：敲窗、叫醒苏、陪伴与关灯\",\"能自理：游泳捕鱼\",\"护弱与分享：不吃幼鼠而收为伙伴，护咖啡不被别猫捕食\",\"机灵\",\"体贴\",\"贪吃\",\"顽皮\",\"护伴\",\"拟人化\",\"温顺安全感强：家中放松、忍朱雀抢食\",\"跨物种照护：养大咖啡、舔病中朱雀\",\"亲近人：陪苏、病痛时舔手安慰\",\"机灵：能感受人的情绪，照料似地拍雨晴额头。\",\"强势又能接纳：制服挑衅宠物狗，与狗王、乡间犬群相处。\",\"会影响叙事信息：爪下压着夕晨外出纸条，移爪后雨晴才看见。\",\"通人性并护主：重阳扑蛇、在苏丧失生活能力时觅食与安慰。\",\"独立且珍惜行动能力：抗拒剪爪，自由夜访莫空。\",\"照料者气质：从养父母处获得保护，再照顾咖啡与雨晴\",\"重情且会回报：为莫空捕鱼，对去世的家人难以释怀\",\"聪明勇敢：为病母觅食，危机时承担保护\"],\"portrait\":\"\",\"fate\":{\"name\":\"曲奇\",\"label\":\"守墓三天后死亡\",\"tone\":\"red\",\"text\":\"陪伴雨晴多年的黑猫。雨晴安葬后反复回墓前、拒绝食物，三天后死亡，被莫空葬在雨晴旁。\",\"note\":\"早期称母猫、后期及前传称公猫，原文前后不一致。台湾段与白猫糯米相伴，后文提及后代。\",\"refs\":[\"c024\",\"c643\",\"c662\",\"c665\"]},\"status\":\"正文：咖啡之后仍陪雨晴多年，雨晴安葬三天后去世，葬在她旁边。IF：与咖啡一同活到结尾婚礼、参与送花。\",\"statusRefs\":[\"c665\",\"x053\",\"x056\",\"x058\",\"x062\",\"x043\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"曲奇最初在河堤与苏相遇，主动进入她房间后获得名字，却没有立刻成为固定家宠。它送活鼠让苏惊惧，随后却将幼鼠养成朋友，与苏形成跨越物种的温暖家庭。猫鼠跟随两次搬家，接受纸箱窝、洗护与喂食，仍保有野外能力。它对莫空早显熟悉但来由未解释，现实行为富有人性是叙事手法，不能当真实动物知识。\",\"segmentFate\":\"截至c120随苏住白兔小区，咖啡仍为伙伴；本段没有死亡或离散。\",\"refs\":[\"c021\",\"c024\",\"c029\",\"c030\",\"c045\",\"c046\",\"c053\",\"c079\",\"c082\",\"c095\",\"c113\"],\"layer\":\"main\"},{\"scope\":\"正文 c121—c240\",\"arc\":\"曲奇在这段远超装饰性宠物：它雨夜迎接晚归雨晴，森林逃散时不离开，带她找栖身树，停电时用叫声与尾巴避障；这些行动不断在她恐惧被世界抛弃时提供陪伴。它也会偷开昂贵猫粮、抓烤鱼、弄灰床铺并在游戏中被传递。雨晴之外最亲夕晨，接受其手工玩具、怀抱与夜间陪玩，还舔去她落泪的脸，连接两个难表达的人。\",\"segmentFate\":\"仍与雨晴、夕晨同住并和咖啡形影不离，本段无死亡或走失结局。\",\"refs\":[\"c137\",\"c155\",\"c159\",\"c171\",\"c188\",\"c195\",\"c196\",\"c220\",\"c226\",\"c230\",\"c237\",\"c239\"],\"layer\":\"main\"},{\"scope\":\"正文 c241—c360\",\"arc\":\"它把合租屋也当作安全家庭，和咖啡一起参与郊游、等生日和安葬朱雀。刚开始被小鸡抢食会委屈求苏，随后已把食物让给它，展现关系增长。苏通过它想象未来失去和母父衰老；它又每夜来陪莫，连接两处居所。不能把拟人描述当动物学普遍规律。\",\"segmentFate\":\"截至c360仍活着随合租者生活，朱雀死亡后与咖啡陪苏回家。\",\"refs\":[\"c265\",\"c266\",\"c271\",\"c316\",\"c319\",\"c328\",\"c338\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"它从共同居所的小插曲、晴夕相处的旁观者，到死亡阴影后的日常安慰者，持续联结几个生活阶段。回集装箱房时被乡间群狗簇拥，给失去同伴的三人带回欢笑。它对夕晨扭曲画面的反应也参与暗示情绪，但不构成能解释秘密的真实证人。\",\"segmentFate\":\"截至c480与雨晴等住集装箱房，仍活着。\",\"refs\":[\"c367\",\"c368\",\"c384\",\"c388\",\"c417\",\"c420\",\"c449\",\"c452\",\"c454\",\"c470\"],\"layer\":\"main\"},{\"scope\":\"正文 c481—c600\",\"arc\":\"随着集装箱搬家适应海景房，在苏与林生活中是持续陪伴。林死后它带咖啡觅食并带鱼给苏，促使苏意识到责任与牵挂。进入宠物店后仍与鼠和平相处，还引苏解大白项圈，显示其自由倾向；夜访莫空加深动物与神秘线的联系。\",\"segmentFate\":\"截至c600随苏生活及上班，健康活跃，未死。\",\"refs\":[\"c531\",\"c532\",\"c553\",\"c579\",\"c590\",\"c591\",\"c595\",\"c598\"],\"layer\":\"main\"},{\"scope\":\"c601—c665；x001—x079（全部补充篇）\",\"arc\":\"前传补足它先被遗弃、再被跨物种家庭抚养，经历清拆和失亲后受莫空救助的历史，因而它对咖啡的接纳是受惠后的善意传递。正文台风时它察觉咖啡死亡并叫醒雨晴，也希望莫空能陪伴主人。迁台后它与糯米组成家庭并有后代，仍在衰老时参加婚礼。最终它在雨晴墓前拒食守候，三天后去世。\",\"segmentFate\":\"正文：咖啡之后仍陪雨晴多年，雨晴安葬三天后去世，葬在她旁边。IF：与咖啡一同活到结尾婚礼、参与送花。\",\"refs\":[\"c603\",\"c609\",\"c617\",\"c643\",\"c662\",\"c665\",\"x053\",\"x056\",\"x058\",\"x062\",\"x043\"],\"layer\":\"main\"}],\"refs\":[\"c021\",\"c024\",\"c029\",\"c030\",\"c045\",\"c046\",\"c053\",\"c079\",\"c082\",\"c095\",\"c113\",\"c137\",\"c155\",\"c159\",\"c171\",\"c188\",\"c195\",\"c196\",\"c220\",\"c226\",\"c230\",\"c237\",\"c239\",\"c265\",\"c266\",\"c271\",\"c316\",\"c319\",\"c328\",\"c338\",\"c367\",\"c368\",\"c384\",\"c388\",\"c417\",\"c420\",\"c449\",\"c452\",\"c454\",\"c470\",\"c531\",\"c532\",\"c553\",\"c579\",\"c590\",\"c591\",\"c595\",\"c598\",\"c603\",\"c609\",\"c617\",\"c643\",\"c662\",\"c665\",\"x053\",\"x056\",\"x058\",\"x062\",\"x043\"],\"group\":\"动物伙伴\",\"layer\":\"main\",\"core\":true},{\"id\":\"person-12\",\"name\":\"苏榕槐\",\"aliases\":[\"苏父\",\"苏先生\",\"苏雨晴父亲\",\"雨晴父亲\",\"爸爸\",\"苏雨晴的父亲\",\"苏雨晴父亲（苏榕槐）\",\"苏雨晴的父亲（苏榕槐）\"],\"identity\":\"苏雨晴父亲，苏家产业经营者。开篇拒绝并伤害女儿，后来参与暗中保护、公开接纳，带全家脱离宗族、迁台经营。\",\"traits\":[\"强硬控制：殴打、强制剪发并烧衣药\",\"也牵挂孩子：刊寻人启事并亲赴小城市\",\"对外较冷静：在面馆询问住处时控制焦虑\",\"威严\",\"重培养\",\"有社会关系\",\"期待传统人生\",\"有压抑的温情：少年宫接送时比答应的数量多买游戏币\",\"从家族责任转向保护孩子：当面斥退羞辱女儿者，主动放弃继承\",\"承担实际照料：奔走手术、证件、复学、收养，并愿捐肾\"],\"portrait\":\"\",\"fate\":{\"name\":\"苏榕槐\",\"label\":\"支持女儿，迁台经营\",\"text\":\"从开篇暴力拒绝到后期公开接纳，脱离宗族并带全家迁台，支持女儿复学、成家，也在她病重时尽力救治。\",\"note\":\"脱离苏家仍保有一千万及台湾公司，并非破产；后来的弥补不抹去开篇伤害。\",\"refs\":[\"c001\",\"c621\",\"c622\",\"c633\",\"c659\",\"c665\"]},\"status\":\"正文终局存活，承受女儿病逝；台湾公司仍在莫空参与经营下发展。\",\"statusRefs\":[\"c632\",\"c633\",\"c657\",\"c665\",\"x045\",\"x064\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"开篇把孩子的女性愿望当作必须纠正的问题，以暴力和剥夺使冲突无法调和。孩子出走后，他并非毫不在意，而是与妻子持续寻找；但本段没有出现他改变性别立场的证据。苏只能从过去判断返家的风险，父爱与控制的并存形成故事持续的痛点。\",\"segmentFate\":\"截至c120最后明确活动是c079在无名面馆等待苏；是否看过第二张纸条、是否离开小城、是否接受身份均未交代。\",\"refs\":[\"c001\",\"c007\",\"c059\",\"c078\",\"c079\"],\"layer\":\"main\"},{\"scope\":\"正文 c121—c240\",\"arc\":\"雨晴对父亲的记忆较多是威严、礼仪、学习与家族生活，他和母亲希望孩子进入体面的社会角色，也曾为成绩下降安排留级。富裕的物质和上层宴会经历并未给她可自由选择身份的感觉；反而外婆家的表哥、同桌的帮助成为罕见亲近。她仍想有天父母接受自己、与爱人相守，说明离家并未等同切断情感。\",\"segmentFate\":\"本段未出场与女儿重逢，是否接受身份未有答案。\",\"refs\":[\"c125\",\"c133\",\"c139\",\"c177\",\"c235\"],\"layer\":\"main\"},{\"scope\":\"c601—c665；x001—x079（全部补充篇）\",\"arc\":\"前传呈现他的父爱一直存在，却与男子气概、宗族继承和阶层观念纠缠。正文归家后他不再让女儿承担这种冲突，以补办手续、陪护手术和公开对抗苏家完成行动上的转变。他辞交家族产业仍争取足够资源安置全家，后来把公司责任交给莫空。婚礼上的伴郎与临终前的捐肾意愿，把父亲从旧日障碍改写为坚定支持者。\",\"segmentFate\":\"正文终局存活，承受女儿病逝；台湾公司仍在莫空参与经营下发展。\",\"refs\":[\"c620\",\"c621\",\"c622\",\"c625\",\"c632\",\"c633\",\"c657\",\"c665\",\"x045\",\"x064\"],\"layer\":\"main\"}],\"refs\":[\"c001\",\"c007\",\"c059\",\"c078\",\"c079\",\"c125\",\"c133\",\"c139\",\"c177\",\"c235\",\"c620\",\"c621\",\"c622\",\"c625\",\"c632\",\"c633\",\"c657\",\"c665\",\"x045\",\"x064\"],\"group\":\"家庭与亲属\",\"layer\":\"main\",\"core\":true},{\"id\":\"person-13\",\"name\":\"苏雨晴的母亲\",\"aliases\":[\"苏母\",\"苏雨晴母亲\",\"雨晴母亲\",\"妈妈\",\"圆圆\",\"母亲（圆圆）\",\"苏雨晴的母亲（圆圆）\"],\"identity\":\"亲属称圆圆，苏雨晴与苏冬凌的母亲，来自台湾苏家村一支。与丈夫经历从拒绝到理解的转变，归家时公开称雨晴为女儿。\",\"traits\":[\"照护细致：苏回忆母亲洗衣、保养头发和日常生活\",\"同样参与性别规范：未能真正支持苏的愿望\",\"寻人焦虑明显：憔悴、白发、急切确认照片\",\"细心照料\",\"保护过度\",\"重成绩规矩\",\"难与孩子身份协调\",\"关怀细密：准备营养、衣物、房间与术后陪护\",\"早期性别规训与后期接纳并存：童年要求男子汉，归家后主动称女儿\",\"愿意维护家庭联系：离家期间借兄长暗中保护孩子\"],\"portrait\":\"\",\"fate\":{\"name\":\"苏雨晴的母亲\",\"label\":\"支持女儿，经历丧女\",\"text\":\"由最初不能接受到暗中关注、公开团圆，参与女儿的迁居、手术与婚礼。雨晴病重时奔走照顾，最终经历丧女。\",\"note\":\"“圆圆”为亲属称呼；按母亲身份统一，不凭空扩展实名。\",\"refs\":[\"c303\",\"c620\",\"c625\",\"c661\",\"c665\",\"x064\"]},\"status\":\"正文终局存活，与丈夫尝试救治女儿未果，承受丧女之痛。\",\"statusRefs\":[\"c625\",\"c636\",\"c637\",\"c665\",\"x044\",\"x064\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"她既是苏渴望回到的怀抱，也是无法提供身份接纳的家庭的一部分。父女冲突时有所缓和，却没有阻止核心管束。出走两个月后，她随丈夫寻来，憔悴使躲在远处的苏强烈心疼；这一幕显示亲情真实存在，却不足以自动解开返家与自主的矛盾。\",\"segmentFate\":\"本段末未与苏现实重逢；多次梦中的接纳不能算她已改变立场。\",\"refs\":[\"c001\",\"c018\",\"c037\",\"c066\",\"c078\",\"c079\"],\"layer\":\"main\"},{\"scope\":\"正文 c121—c240\",\"arc\":\"她在本段主要通过女儿记忆和病中呼唤出现。雨晴早产、多病且有先天心脏病，母亲曾请假昼夜照料，限制冰食、运动等令女儿后来懂得保护的心意；她也督促成绩、要求作文按范本，规定应像男孩般坚强。这使母爱既是雨晴安全感源头，也是自由追求时最深负疚。高烧梦中“妈妈不要离开”的哭喊，最终由夕晨的握手安抚。\",\"segmentFate\":\"现实未与雨晴见面或通话；女儿愈加想念，但本段未得知家中最新状态。\",\"refs\":[\"c132\",\"c149\",\"c187\",\"c218\",\"c223\",\"c235\"],\"layer\":\"main\"},{\"scope\":\"c601—c665；x001—x079（全部补充篇）\",\"arc\":\"她在前传里既是雨晴担忧违逆的性别规范传递者，也是不停牵挂孩子的母亲。x064披露她知道女儿的处境并与兄长商量保护；归家时，她拥抱雨晴、解释冬凌并非替代，准备与被烧旧裙相同的白裙。随后陪女儿赴美恢复、迁台和办婚礼，以具体行动弥补旧伤。亲属称谓在原文混用，圆圆这个称呼由兄长口中出现。\",\"segmentFate\":\"正文终局存活，与丈夫尝试救治女儿未果，承受丧女之痛。\",\"refs\":[\"c620\",\"c621\",\"c622\",\"c625\",\"c636\",\"c637\",\"c665\",\"x044\",\"x064\"],\"layer\":\"main\"}],\"refs\":[\"c001\",\"c018\",\"c037\",\"c066\",\"c078\",\"c079\",\"c132\",\"c149\",\"c187\",\"c218\",\"c223\",\"c235\",\"c620\",\"c621\",\"c622\",\"c625\",\"c636\",\"c637\",\"c665\",\"x044\",\"x064\"],\"group\":\"家庭与亲属\",\"layer\":\"main\",\"core\":true},{\"id\":\"person-14\",\"name\":\"莫语默\",\"aliases\":[\"林清云\",\"清云\"],\"identity\":\"原名林清云，林清雾的双胞胎妹妹。由莫空和苏雨晴领养后改名，随家庭到台湾生活。\",\"traits\":[\"重亲情：坚决不愿与哥哥分离，获得零食也想着寄给哥哥\",\"敏感需要安全感：害怕新父母嫌弃和遗弃\",\"活泼好奇：逐渐大胆游玩、参加婚礼做花童\"],\"portrait\":\"\",\"fate\":{\"name\":\"莫语默\",\"label\":\"存活，由莫空继续照顾\",\"text\":\"原名林清云，林清雾的双胞胎妹妹，被雨晴和莫空收养后迁台生活。母亲死后由莫空继续抚养。\",\"note\":\"是领养女儿；IF中的亲生女儿叫苏慕夕，不能互换。\",\"refs\":[\"c653\",\"c656\",\"c657\",\"c665\",\"x043\"]},\"status\":\"正文终局存活，由莫空继续抚养；与林清雾的兄妹关系保留。她不是IF亲生女儿苏慕夕，也不是死后外传叶洛夜。\",\"statusRefs\":[\"c655\",\"c656\",\"c657\",\"c658\",\"c662\",\"c665\"],\"segments\":[{\"scope\":\"c601—c665；x001—x079（全部补充篇）\",\"arc\":\"作为林清云时，她与哥哥相互让出被收养的机会，体现福利院生活中的依存。雨晴因她的孤独想到自己，亲子愿望才真正落到一个具体孩子身上。她最终在未写明的说服过程后同意分离，改名赴台；适应新家庭并未抹去旧亲情。三年后已上小学，成为婚礼花童，随后又在年幼时失去养母。\",\"segmentFate\":\"正文终局存活，由莫空继续抚养；与林清雾的兄妹关系保留。她不是IF亲生女儿苏慕夕，也不是死后外传叶洛夜。\",\"refs\":[\"c652\",\"c653\",\"c655\",\"c656\",\"c657\",\"c658\",\"c662\",\"c665\"],\"layer\":\"main\"}],\"refs\":[\"c652\",\"c653\",\"c655\",\"c656\",\"c657\",\"c658\",\"c662\",\"c665\"],\"group\":\"家庭与亲属\",\"layer\":\"main\",\"core\":true},{\"id\":\"person-15\",\"name\":\"橘子\",\"aliases\":[\"橘子\",\"橘子姐（人物沿用的称呼）\",\"田桔\",\"橘子（田桔）\"],\"identity\":\"本名田桔，跨性别男性，方莜莜正式外传的重要人物。过去经历创伤与记忆改写，后来帮助并救下莜莜。\",\"traits\":[\"外在爽利、内里受创：用玩笑和饮酒遮掩痛苦\",\"对亲密有替代投射：把莜莜当姜琳，曾越过朋友边界\",\"行动上珍视朋友：为二人看店，察觉危机跨城赶来救人\"],\"portrait\":\"\",\"fate\":{\"name\":\"橘子\",\"label\":\"救援后存活\",\"text\":\"本名田桔，跨性别男性。受创记忆在外传被澄清；后来救下莜莜，两人一同获救出院。他与安念绝交并继续保护莜莜。\",\"note\":\"张诚是学长，姜琳活着转学；此前的神怪故事含记忆改写。\",\"refs\":[\"x028\",\"x034\",\"x035\"]},\"status\":\"方莜莜篇终局存活，救援后住院数日恢复；继续支持莜莜，未明确成为其恋人，长期健康及治疗状态未交代。\",\"statusRefs\":[\"x014\",\"x021\",\"x027\",\"x028\",\"x029\",\"x035\"],\"segments\":[{\"scope\":\"c601—c665；x001—x079（全部补充篇）\",\"arc\":\"他讲出的校园爱情和神怪冒险在x028被推翻：真实姜琳拒绝感情，学长张诚为救他死于塌陷。原有妄想困扰与创伤促成记忆改写，近期又放任幻想把莜莜当作替代。莜莜的追问帮助他承认现实，但这并不等于病况完全治愈，也不使越界亲密合理化。终局他及时发现朋友的自杀危机并救援，随后维护她的分离决定，与安念绝交。\",\"segmentFate\":\"方莜莜篇终局存活，救援后住院数日恢复；继续支持莜莜，未明确成为其恋人，长期健康及治疗状态未交代。\",\"refs\":[\"x002\",\"x004\",\"x014\",\"x021\",\"x027\",\"x028\",\"x029\",\"x035\"],\"layer\":\"fang\"}],\"refs\":[\"x002\",\"x004\",\"x014\",\"x021\",\"x027\",\"x028\",\"x029\",\"x035\"],\"group\":\"外传人物\",\"layer\":\"fang\",\"core\":true},{\"id\":\"person-16\",\"name\":\"车站与街头善意路人\",\"aliases\":[\"杭州站清洁工\",\"中心广场环卫阿姨\",\"嵌糕店老板娘\",\"夜班公交司机\"],\"identity\":\"数位不同未具名人物，分别在出走、见网友与救援返程提供小帮助。\",\"traits\":[\"普通善意：指路、售食、平常招呼，不追问或加害\"],\"portrait\":\"\",\"fate\":null,\"status\":\"各场景完成后未交代进一步生活。\",\"statusRefs\":[\"c002\",\"c003\",\"c034\",\"c072\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"出走初始的清洁工和食物摊主使陌生城市并非全然冷漠；中心广场环卫阿姨帮助苏克服问路羞怯；夜班司机则在莫空独自冒雨返程时自然招呼。这些人物应保持为不同路人，合并登记只为压缩索引，不表示是同一人。其善意不以成为主角的朋友为前提。\",\"segmentFate\":\"各场景完成后未交代进一步生活。\",\"refs\":[\"c002\",\"c003\",\"c034\",\"c072\"],\"layer\":\"main\"}],\"refs\":[\"c002\",\"c003\",\"c034\",\"c072\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-17\",\"name\":\"中介与普通交易者\",\"aliases\":[\"首日工作中介老板\",\"后期工作中介老板\",\"杂货店老板\",\"床品店老板\",\"夜市摊主\"],\"identity\":\"不同未具名生存场景人物；前后中介是否同一人未明，不应合并身份。\",\"traits\":[\"首日中介在苏丢钱包后粗暴驱赶\",\"其他交易主要体现价格、讲价、筛选工作的日常压力\"],\"portrait\":\"\",\"fate\":null,\"status\":\"仅交易场景人物，本段没有独立终局。\",\"statusRefs\":[\"c004\",\"c006\",\"c009\",\"c077\",\"c107\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"苏在陌生城市必须通过商贩和中介换取住处、工作与用品。首日中介的拒绝使失钱后的无助加重；后来三人共同求职时则能比较岗位和费用，显示支持网络带来的实际能力变化。夜市和床品交易呈现苏由富家孩子转为谨慎预算者的过程。\",\"segmentFate\":\"仅交易场景人物，本段没有独立终局。\",\"refs\":[\"c004\",\"c006\",\"c009\",\"c077\",\"c107\"],\"layer\":\"main\"}],\"refs\":[\"c004\",\"c006\",\"c009\",\"c077\",\"c107\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-18\",\"name\":\"张阿姨\",\"aliases\":[\"面馆老板娘\",\"张老板娘\",\"面馆老板娘（张阿姨）\",\"张阿姨（面馆老板娘）\",\"张阿姨（张姨）\",\"张姨\"],\"identity\":\"白石路无名面馆老板娘，李叔叔之妻、李天明之母。\",\"traits\":[\"热心实际：录用、谈租、预支工资、送食物药品\",\"接纳有局限：知道出生性别仍常以男性称呼，未全懂家庭冲突\",\"愿修复伤害：儿子骂人后登门道歉\",\"重视保护：父母出示户口本也不立即泄露苏住址\"],\"portrait\":\"\",\"fate\":null,\"status\":\"c079接待苏父母后未再明确出场；苏不告而别后的看法和面馆经营情况未交代。\",\"statusRefs\":[\"c013\",\"c033\",\"c064\",\"c066\",\"c076\",\"c079\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"她从雇主逐步成为苏的照护长辈，提供的不是抽象同情，而是房租、早餐、休息、刺绣与日常亲近。她有传统性别观念，也曾劝苏感恩父母，但面对儿子羞辱时站在维护苏尊严的一边，事后主动修复。苏离开前，她坚持保护孩子住址，成为两次出走之间少有的稳定善意。\",\"segmentFate\":\"c079接待苏父母后未再明确出场；苏不告而别后的看法和面馆经营情况未交代。\",\"refs\":[\"c006\",\"c008\",\"c010\",\"c013\",\"c033\",\"c064\",\"c066\",\"c076\",\"c079\"],\"layer\":\"main\"}],\"refs\":[\"c006\",\"c008\",\"c010\",\"c013\",\"c033\",\"c064\",\"c066\",\"c076\",\"c079\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-19\",\"name\":\"老虎\",\"aliases\":[\"房东老虎\",\"女房东\",\"老虎房东\",\"女房东（老虎）\",\"老虎（房东）\",\"老板娘（老虎）\"],\"identity\":\"白石路附近农民房女房东，租给苏三楼小单间。\",\"traits\":[\"外表粗豪、爱打麻将\",\"讲价精明：经张阿姨协商降租\",\"在外貌上有传统评语：嫌苏头发长\"],\"portrait\":\"\",\"fate\":null,\"status\":\"苏搬走后的房屋再出租及遗留物处理未交代。\",\"statusRefs\":[\"c007\",\"c008\",\"c047\",\"c048\",\"c079\",\"c099\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"她提供了苏第一次独立住所，租金经熟人协商才在预算内。其行为主要围绕议租和收水电费，突然登门曾让穿女装的苏紧张。她不是收留苏的亲密同伴，也未在本段主动欺辱其身份；苏离去后猜想她会处理遗留物，但那仍只是猜想。\",\"segmentFate\":\"苏搬走后的房屋再出租及遗留物处理未交代。\",\"refs\":[\"c007\",\"c008\",\"c047\",\"c048\",\"c079\",\"c099\"],\"layer\":\"main\"}],\"refs\":[\"c007\",\"c008\",\"c047\",\"c048\",\"c079\",\"c099\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-20\",\"name\":\"苏雨晴祖爷爷\",\"aliases\":[\"祖爷爷\"],\"identity\":\"家族长者，在苏出生前于家族仪式中定下“苏雨晴”之名并记入族谱。\",\"traits\":[\"重视家族礼制：名字经仪式确认便不允许更改\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段仅在家族回忆中被提及，现实下落未交代。\",\"statusRefs\":[\"c007\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"名字原按女婴预期而定，却因祖爷爷与族谱权威在出生性别不同后仍保留。苏由此拥有始终喜欢的名字，而家族对名字的坚持与对实际女性身份的拒绝形成文学上的反差。有关百岁高龄与礼制均是小说叙述，不能引申为外部史实。\",\"segmentFate\":\"本段仅在家族回忆中被提及，现实下落未交代。\",\"refs\":[\"c007\"],\"layer\":\"main\"}],\"refs\":[\"c007\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-21\",\"name\":\"李叔\",\"aliases\":[\"李老板\",\"面馆老板\",\"李叔叔\",\"面馆老板（李叔）\",\"李叔（面馆老板）\"],\"identity\":\"无名面馆老板，张阿姨丈夫、李天明父亲。\",\"traits\":[\"务实温厚：做加料饭、教苏煮面\",\"维护雇员：反对儿子性别辱骂并责罚\",\"肯定劳动：工资之外给五十元改善饮食\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段最后明确为4月29日发薪；苏离开后是否重新招工未交代。\",\"statusRefs\":[\"c010\",\"c013\",\"c033\",\"c061\",\"c062\",\"c076\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"他对苏的关系从提供一份工作，发展为把孩子当家中晚辈看待。厨房里的特别饭食、愿意教煮面与发额外补贴体现照顾；他同样没有完整理解苏的性别处境，但在儿子造成伤害时明确认为辱骂不对。其家庭温暖与家庭成员偏见之间的裂缝并未因此完全消失。\",\"segmentFate\":\"本段最后明确为4月29日发薪；苏离开后是否重新招工未交代。\",\"refs\":[\"c010\",\"c013\",\"c033\",\"c061\",\"c062\",\"c076\"],\"layer\":\"main\"}],\"refs\":[\"c010\",\"c013\",\"c033\",\"c061\",\"c062\",\"c076\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-22\",\"name\":\"面馆普通熟客与高汤厂家\",\"aliases\":[\"老王\",\"熟客群体\",\"高汤佐料推销员\"],\"identity\":\"老王及其他食客、高汤厂家工作人员为不同人物，共同构成面馆社会环境。\",\"traits\":[\"部分熟客拿外貌婚配打趣，令苏羞怯\",\"厂家看中苏的吸引力提出临时宣传工作\"],\"portrait\":\"\",\"fate\":null,\"status\":\"各自日常继续，本段未给单独结局。\",\"statusRefs\":[\"c010\",\"c016\",\"c017\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"面馆熟客的玩笑使苏学习应对陌生评价，也常提醒她被当女孩时仍害怕秘密。高汤宣传给她第一次额外报酬，让水壶与帘子成为可负担的物件。除老王称呼外，多数人无姓名；他们不同于莫空、张思凡和孙昊等重要来客。该群体不能混成单一个人。\",\"segmentFate\":\"各自日常继续，本段未给单独结局。\",\"refs\":[\"c010\",\"c016\",\"c017\"],\"layer\":\"main\"}],\"refs\":[\"c010\",\"c016\",\"c017\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-23\",\"name\":\"梦中男孩\",\"aliases\":[\"荒园男孩\",\"秋千男孩\"],\"identity\":\"苏反复梦境中的男孩，与童年苏相似；不是已证实的现实人物。\",\"traits\":[\"执着追寻：吃石头与糖果，只求内心不痛\",\"逐次受伤与反抗：梦中暴力、自伤映出恐惧\",\"身份含混：苏对其是自身潜意识或外在梦魇摇摆\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段最后重要出现c090仍在梦中；真相与后续回收须后文。\",\"statusRefs\":[\"c025\",\"c030\",\"c048\",\"c050\",\"c065\",\"c090\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"男孩从请求离开荒园，到承担石糖带来的身体痛苦，再到受欺凌、杀戮与拒绝看见世界，逐步加深苏对内在黑暗的恐惧。苏曾把他理解为童年自己、压抑负面情绪的载体，后来又不愿承认这种解释。所有这些都在梦中发生，本段未证明其独立存在，也没有支持任何临床诊断。\",\"segmentFate\":\"本段最后重要出现c090仍在梦中；真相与后续回收须后文。\",\"refs\":[\"c012\",\"c014\",\"c025\",\"c030\",\"c048\",\"c050\",\"c065\",\"c090\"],\"layer\":\"main\"}],\"refs\":[\"c012\",\"c014\",\"c025\",\"c030\",\"c048\",\"c050\",\"c065\",\"c090\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-24\",\"name\":\"冉空城\",\"aliases\":[\"苏雨晴原同桌\",\"同桌\"],\"identity\":\"苏初中同桌，本段只称同桌；姓名在后文c124回收为冉空城（由全书统稿核验）。\",\"traits\":[\"会保护人：替受排斥的苏说话\",\"有玩笑也知解释道歉：赠发卡后澄清善意\",\"友善\",\"维护弱者\",\"幽默\",\"体贴\",\"不随众欺凌\",\"坚定护友：与孔荀冲突而被扔垃圾桶仍不退\",\"主动温暖：持续短信关怀、邀见及未来同大学\",\"有幽默也有普通少年好感：善意逗苏，见漂亮金晶会心动\",\"友善照顾：来访、送发卡、谈旧同学。\",\"接受有限：口头保持友谊，但明确无恋爱感觉，后来联系减少。\",\"自然体贴：让出靠窗座位，午休带巧克力派且坚持分半\",\"关心却未许诺爱情：旧同桌友谊成为雨晴珍贵的支持\"],\"portrait\":\"\",\"fate\":{\"name\":\"冉空城\",\"label\":\"退为普通朋友，另有女友\",\"text\":\"初中时保护雨晴，是发卡与电话号码的来源。后来探访并重逢，至雨晴归家后告知已有女友；雨晴也认清旧日好感。\",\"note\":\"不是雨晴最终伴侣；没有死亡或失踪结局。\",\"refs\":[\"c113\",\"c124\",\"c525\",\"c529\",\"c630\"]},\"status\":\"正文c630已有女友，与雨晴是普通朋友；独立终局未交代。\",\"statusRefs\":[\"c630\",\"x046\",\"x074\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"学校生活大多使苏低头回避，同桌却以保护、玩笑与礼物留下被同龄人关心的少数记忆。苏曾误以为星期发卡是秘密被发现后的讽刺，看到真诚道歉才接受。她一直珍藏，在新工作第一天真正戴上，也承认可能喜欢过他；但秘密并未向他完全开放。\",\"segmentFate\":\"截至c120仅在苏的回忆中出现；c124回收姓名，本段未写其与出走后的苏重联。\",\"refs\":[\"c026\",\"c089\",\"c112\",\"c113\",\"c124\"],\"layer\":\"main\"},{\"scope\":\"正文 c121—c240\",\"arc\":\"他在回忆里用平常友谊保护被同学排斥的雨晴，曾问换号码、让她帮课堂问题，并当面反对同学嘲笑她的性别表现。雨晴留级后又与他同桌，文本以成绩和眨眼暗示他可能主动陪伴，但未亲口承认。旧生日礼物中保留的电话号码成为她离家后的联系，她哭着挂断，没有说明姓名；之后的缺席更显出被她深藏的思念。\",\"segmentFate\":\"本段现实只接过一次未确认身份的电话；未与雨晴重逢、未明确恋爱或得知其现状。\",\"refs\":[\"c121\",\"c124\",\"c125\",\"c149\",\"c203\",\"c204\"],\"layer\":\"main\"},{\"scope\":\"正文 c241—c360\",\"arc\":\"他的现实出场主要经短信和苏回忆，却推动苏对过去不断重估。从误拨电话后认出朋友，到开学催回、节日问候和告知金晶转往别城，他始终愿维持联系。苏因自我隔离始终不给回应，频率因此逐渐减少。两年同桌的保护与善意亲昵令苏猜测爱情，但本段未出现冉向苏正式表白，他是否仅兄长式关爱仍未明。\",\"segmentFate\":\"截至c360仍为苏发过节日问候，未得到正常回应；个人去向和情感定性待后文。\",\"refs\":[\"c258\",\"c262\",\"c279\",\"c339\",\"c340\"],\"layer\":\"main\"},{\"scope\":\"正文 c481—c600\",\"arc\":\"探访使苏幻想中的旧友与现实里的男生重新相遇。他对她变化有惊讶甚至瞬间吸引，得知身份后却确认只愿做朋友。苏看见自己曾混淆依赖与爱，后来逐渐失去频繁联系；原因是学业还是身份隔阂并非完全由冉亲口说明。\",\"segmentFate\":\"截至本段与苏联系明显减少，生活与感情去向未交代。\",\"refs\":[\"c502\",\"c525\",\"c526\",\"c527\",\"c528\",\"c529\",\"c573\",\"c593\"],\"layer\":\"main\"},{\"scope\":\"c601—c665；x001—x079（全部补充篇）\",\"arc\":\"前传展现少量食物与被记挂对孤立少女的分量：他随口的善意使雨晴暗自欢喜，也害怕身份暴露后失去唯一朋友。正文c630收到他已有女友的短信后，雨晴坦然辨认过去更多是一种好感，说明她终于不必把每一份温暖都理解为唯一归宿。元叙述另写所谓素材人物的性取向，不能套到正文。\",\"segmentFate\":\"正文c630已有女友，与雨晴是普通朋友；独立终局未交代。\",\"refs\":[\"c630\",\"x046\",\"x074\"],\"layer\":\"main\"}],\"refs\":[\"c026\",\"c089\",\"c112\",\"c113\",\"c124\",\"c121\",\"c125\",\"c149\",\"c203\",\"c204\",\"c258\",\"c262\",\"c279\",\"c339\",\"c340\",\"c502\",\"c525\",\"c526\",\"c527\",\"c528\",\"c529\",\"c573\",\"c593\",\"c630\",\"x046\",\"x074\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-25\",\"name\":\"咖啡\",\"aliases\":[\"灰鼠\",\"紫色小鼠\",\"幼鼠\"],\"identity\":\"曲奇带回的幼鼠，初为灰毛，随换毛逐渐转为紫毛，晚年失去光泽并出现白毛。它与猫和雨晴长期相伴，有独立生命线，不能当作饮料“咖啡”混入物品。\",\"traits\":[\"好奇爱动：常站在猫头上观察、独自探索\",\"与猫互助：分享鱼与饼干、跟随洗澡\",\"带拟人特征：似思考、似帮菜苗施肥\",\"常显慵懒\",\"聪明\",\"偏爱素食\",\"爱看绘画\",\"拟人化\",\"活泼贪食并储粮：秋天把谷物藏家中\",\"关心伙伴：替朱雀咬碎饼干、病时递瓜子仁\",\"依恋共同生活：与曲奇形影相伴\",\"活泼、会自行布置窝：以纸杯和棉絮作夜间住处。\",\"与猫狗共同生活，带来细小日常趣味。\",\"亲人依赖：随曲奇同行，温柔触苏发丝安慰。\",\"贪吃好奇：尝食、在草丛探路，与大白相处。\",\"早年亲近信赖：幼鼠面对曲奇没有逃离，唤起其养育记忆\",\"衰老时依赖家人：食欲与精神下降，曲奇格外珍惜陪伴\"],\"portrait\":\"\",\"fate\":{\"name\":\"咖啡\",\"label\":\"台风夜死亡\",\"tone\":\"red\",\"text\":\"原本被曲奇带回的幼鼠，灰毛随换毛逐渐转紫，后来成为长期伙伴。2006年台风夜老去死亡；雨晴送医途中其遗体被排水冲走。\",\"note\":\"未找到遗体，不写成与雨晴或曲奇一同埋葬。\",\"refs\":[\"c046\",\"c603\",\"c604\"]},\"status\":\"正文：2006年台风夜自然死亡，遗体在暴雨中遗失。IF：存活到结尾婚礼并和曲奇送花。\",\"statusRefs\":[\"c602\",\"c603\",\"c604\",\"c609\",\"x062\",\"x043\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"本来可能是曲奇送给苏的食物，苏拒绝杀生后，猫叼走它；一月后仍活着且与曲奇亲密，苏才真正接纳并命名。咖啡不再只象征被捕食的脆弱，而成为可参与家庭日常的伙伴。毛色和行为的特别在本段没有科学解释，苏曾猜它是宠物鼠或特殊品种，均不可作为已确认分类。\",\"segmentFate\":\"截至c120与曲奇共同住白兔小区，健康存活；物种或异常毛色原因未交代。\",\"refs\":[\"c029\",\"c030\",\"c045\",\"c046\",\"c080\",\"c082\",\"c091\",\"c099\",\"c113\"],\"layer\":\"main\"},{\"scope\":\"正文 c121—c240\",\"arc\":\"咖啡常像紫色毛球任曲奇摆弄，看似嗜睡，却也会在清晨活跃、翻雨晴摘抄本。它尤其爱看夕晨画画，可在肩头坐一整天，被画入房间剖面图时表现兴奋，成为让夕晨露出少见笑容的观众。外出吃饭时藏在曲奇身下，受喂香菜等食物；吃完会把壳扔进垃圾桶，还给曲奇送猫粮。动物层面的交流比人的语言更自然地接住孤独。\",\"segmentFate\":\"仍存活，与曲奇及夕晨亲密；本段的嗜睡没有被确认为疾病或衰老。\",\"refs\":[\"c137\",\"c191\",\"c220\",\"c232\",\"c237\",\"c238\"],\"layer\":\"main\"},{\"scope\":\"正文 c241—c360\",\"arc\":\"它的觅食、藏粮和与猫的反常友谊构成温暖日常，与苏独处恐惧形成对照。和曲奇一起坐大龟渡水、夜访莫、玩爆生日气球、守护并送葬朱雀，既是喜剧来源也成为失去意识的载体。文本对动物认知有拟人夸张，图鉴可作为叙事形象记录。\",\"segmentFate\":\"截至本段仍活着居于合租屋。\",\"refs\":[\"c246\",\"c266\",\"c319\",\"c325\",\"c328\",\"c330\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"与曲奇相比，它更常以吃瓜子、窝纸杯等小动作出现，为复杂人物情绪提供平静对照。毛色变化是作品的宠物奇趣设定，不能依据常识硬修；阿牛葬礼时猫鼠避开烟火，回乡居后继续与三人一起生活。\",\"segmentFate\":\"截至c480仍活着，跟随雨晴等住集装箱房。\",\"refs\":[\"c368\",\"c384\",\"c417\",\"c421\",\"c449\",\"c452\",\"c469\"],\"layer\":\"main\"},{\"scope\":\"正文 c481—c600\",\"arc\":\"林曾担忧咖啡年长、紫毛间有白色且不如幼时灵动，但它随搬家适应新窝，在宠物店丰富食物中又胖起来。大难后的苏得到它与曲奇共同陪伴；品种只属风音推测，不宜据紫色自行定义超自然起源。\",\"segmentFate\":\"截至c600存活，随苏上班，早先衰老描写无死亡回收。\",\"refs\":[\"c531\",\"c532\",\"c553\",\"c579\",\"c591\",\"c595\",\"c597\"],\"layer\":\"main\"},{\"scope\":\"c601—c665；x001—x079（全部补充篇）\",\"arc\":\"前传将它从猎物变成家人的过程写得轻柔：幼鼠无知的亲近触发曲奇曾被狗养育的回忆，照料因此跨越物种。正文末段它已自然衰老，台风夜停止呼吸。雨晴试图抱它去宠物店挽救，遗体却被水冲走无法安葬，使她再次面对无法补救的告别。\",\"segmentFate\":\"正文：2006年台风夜自然死亡，遗体在暴雨中遗失。IF：存活到结尾婚礼并和曲奇送花。\",\"refs\":[\"c601\",\"c602\",\"c603\",\"c604\",\"c609\",\"x062\",\"x043\"],\"layer\":\"main\"}],\"refs\":[\"c029\",\"c030\",\"c045\",\"c046\",\"c080\",\"c082\",\"c091\",\"c099\",\"c113\",\"c137\",\"c191\",\"c220\",\"c232\",\"c237\",\"c238\",\"c246\",\"c266\",\"c319\",\"c325\",\"c328\",\"c330\",\"c368\",\"c384\",\"c417\",\"c421\",\"c449\",\"c452\",\"c469\",\"c531\",\"c532\",\"c553\",\"c579\",\"c591\",\"c595\",\"c597\",\"c601\",\"c602\",\"c603\",\"c604\",\"c609\",\"x062\",\"x043\"],\"group\":\"动物伙伴\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-26\",\"name\":\"张思凡父母\",\"aliases\":[\"思思的父母\",\"思思父母\",\"思凡母亲\",\"思凡父亲\",\"思凡父母\"],\"identity\":\"异地为在校张思凡提供生活费的父母，本段未正面出场。\",\"traits\":[\"提供物质支撑\",\"其对子女性别身份的实际态度尚未揭示\",\"重婚育传承\",\"关心但不知实情\",\"传统期待\",\"母亲会偏袒来客，但背后有难言筹款考虑。\",\"持续惦记孩子：思凡负气离去后打电话问冷暖，主动化解冲突。\",\"对子女未来上心：原拟借十万元创业款，冲突后只获三万元。\",\"以孩子大学毕业为荣，愿让其自行决定创业方向。\",\"拿积蓄并借款资助，返家后热情接纳。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段与张团聚，继续准备创业及婚恋支持。\",\"statusRefs\":[\"c558\",\"c561\",\"c580\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"张的焦虑大多围绕如果父母发现会怎样，不能据此断言他们已拒绝或施暴。每月汇来的生活费支持集装箱、衣物和读书，但张的冲动消费令预算常紧。后来家里经济紧张、生活费削减推动她求兼职，说明家庭关系以依赖与未坦白的秘密连接。\",\"segmentFate\":\"本段结束仍不知张的性别身份；未来发现后的反应未交代。\",\"refs\":[\"c036\",\"c043\",\"c075\",\"c092\",\"c099\"],\"layer\":\"main\"},{\"scope\":\"正文 c121—c240\",\"arc\":\"他们在思思实习期间仍提供生活费，使她的开销比独自挣钱的莜莜宽裕，却也频繁关心找女友、相亲与家族延续。思思争执时说漏对女孩没有兴趣，意识到他们可能起疑，担心身份暴露后被逐与恋人失去支持，才在深夜向孙昊哭诉。原文没有写家长已全面得知或正式断绝关系，压力主要通过思思的预期与恐惧展开。\",\"segmentFate\":\"仍有联系和经济支持，真实出柜未发生。\",\"refs\":[\"c189\",\"c223\",\"c229\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"孩子眼中母亲把重要收藏当无所谓的玩具，亲子冲突因重视的东西不同而爆发；叙述给读者补充父母正向表舅借款，思凡却不知。母亲之后不再追究争执，通过平常叮嘱修补关系。父母的爱没有消除隐瞒身份问题，反而使思凡更怕让他们失望。\",\"segmentFate\":\"截至c480亲子春节冲突已缓和，身份与手术计划仍未向父母坦白；开店借款计划尚未实行成店。\",\"refs\":[\"c424\",\"c425\",\"c435\"],\"layer\":\"main\"},{\"scope\":\"正文 c481—c600\",\"arc\":\"外界谈论大学生前途时，两人相信孩子有见识、能做出事业。张受情伤返乡没有被逼解释全部经历，得到久违的家庭安定，父母已备十几万资金，春节又安排相亲。对孩子过去想做女人的经历并不知情。\",\"segmentFate\":\"本段与张团聚，继续准备创业及婚恋支持。\",\"refs\":[\"c558\",\"c561\",\"c580\"],\"layer\":\"main\"}],\"refs\":[\"c036\",\"c043\",\"c075\",\"c092\",\"c099\",\"c189\",\"c223\",\"c229\",\"c424\",\"c425\",\"c435\",\"c558\",\"c561\",\"c580\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-27\",\"name\":\"台湾表亲群体\",\"aliases\":[\"大表哥\",\"表兄弟姐妹\"],\"identity\":\"苏在台湾外婆家认识的母系同辈亲属。\",\"traits\":[\"相对包容：苏回忆与其相处比父系家族自在\"],\"portrait\":\"\",\"fate\":null,\"status\":\"只见于回忆，后续行动未交代。\",\"statusRefs\":[\"c037\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"这些表亲在苏讲述过去时提供了另一种亲属经验：同辈相处不全是欺凌和规训，也可以有玩耍、照顾与被接纳。大表哥被提到较强壮，但本段没有更多具体姓名和单独支线，不能把集体记忆拆成未经确认的人物传记。具体个人行踪均未写明。\",\"segmentFate\":\"只见于回忆，后续行动未交代。\",\"refs\":[\"c037\"],\"layer\":\"main\"}],\"refs\":[\"c037\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-28\",\"name\":\"苏雨晴外婆\",\"aliases\":[\"台湾外婆\"],\"identity\":\"苏雨晴母系外婆，住在台湾，是苏童年温暖家庭经验的重要来源。\",\"traits\":[\"慈爱且会手艺：教苏刺绣\",\"所在家庭氛围在苏记忆中较包容\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段只在回忆中出现，未与出走后的苏取得联系。\",\"statusRefs\":[\"c037\",\"c066\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"苏提起台湾亲属时，比谈父系家族更轻松；外婆与表亲构成她对家可以温暖、包容的记忆。后来张阿姨教十字绣，唤醒的也是外婆曾经握着她教手艺的感受。她并未在本段出场解救苏，意义主要来自回忆及情绪照护的对照。她对当下剧情的影响来自记忆。\",\"segmentFate\":\"本段只在回忆中出现，未与出走后的苏取得联系。\",\"refs\":[\"c037\",\"c066\"],\"layer\":\"main\"}],\"refs\":[\"c037\",\"c066\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-29\",\"name\":\"巷中混混团伙\",\"aliases\":[\"绿毛\",\"绿子\",\"老绿\",\"白狗\",\"狗白\",\"白毛\",\"二黄\",\"黄毛\"],\"identity\":\"最初三名、后报复场景共五名混混；主要以发色和绰号辨识。\",\"traits\":[\"暴力且轻视他人：把苏作为赌局目标并侵害\",\"报复性强：围殴叫保安的少年\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段末被打伤，胡让其自行叫救护车；未描写死亡、逮捕或判决。\",\"statusRefs\":[\"c048\",\"c049\",\"c059\",\"c060\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"他们先在巷中赌牌，随后围堵苏、无视拒绝实施侵害，因少年叫来保安而被迫停止。后来找少年报复时被胡玉牛击败，苏险被被抛来的人撞中、莫空挡开。现有叙述无司法追责结果，也不能把酒吧二十七号客人自动当作同一群人。\",\"segmentFate\":\"本段末被打伤，胡让其自行叫救护车；未描写死亡、逮捕或判决。\",\"refs\":[\"c048\",\"c049\",\"c059\",\"c060\"],\"layer\":\"main\"}],\"refs\":[\"c048\",\"c049\",\"c059\",\"c060\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-30\",\"name\":\"保安与酒吧执行人员\",\"aliases\":[\"巷中保安\",\"酒吧保安\",\"赵老板保镖\"],\"identity\":\"不同场合的未具名人员，不能混为同一队伍。\",\"traits\":[\"巷中保安受求助及时制止侵害\",\"酒吧保安起初追人，后服从阿雷叫停\",\"赵保镖玩忽职守后遭其怒骂\"],\"portrait\":\"\",\"fate\":null,\"status\":\"巷中侵害被止，酒吧追赶停止；没有后续处分信息。\",\"statusRefs\":[\"c049\",\"c071\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"这些群体体现求助是否有效取决于情境：巷中少年能找到保安迅速止害；酒吧保安却先维护顾客权势追赶救援者，只有阿雷介入才停止。赵的私人保镖此前不在现场、救援后受骂。应按事件分别标注行为，不能笼统说保安全都救了苏。\",\"segmentFate\":\"巷中侵害被止，酒吧追赶停止；没有后续处分信息。\",\"refs\":[\"c049\",\"c071\"],\"layer\":\"main\"}],\"refs\":[\"c049\",\"c071\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-31\",\"name\":\"巷中求援少年\",\"aliases\":[\"未具名少年\",\"叫保安的少年\"],\"identity\":\"约十五六岁的路人，见苏受袭后去找保安，后遭混混报复。\",\"traits\":[\"害怕而仍行动：未硬拼，及时找能制止的人\",\"不求留名：两次事后都未说姓名\",\"受伤后倔强：拒绝去医院\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至c120本段最后c060受伤后自行离开，未留名；不能与阿雷或老管之子擅自合并。\",\"statusRefs\":[\"c049\",\"c059\",\"c060\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"苏最初误以为少年的转身是冷漠逃跑，保安赶到后才明白求援的勇敢。他的行动使侵害被及时阻止，后来混混为报复围殴他，胡玉牛与莫空出现解围。这条支线让勇敢与害怕不再对立，也使帮助他人的后果不被浪漫化。同样重要的是他事后不愿留名。\",\"segmentFate\":\"截至c120本段最后c060受伤后自行离开，未留名；不能与阿雷或老管之子擅自合并。\",\"refs\":[\"c049\",\"c059\",\"c060\"],\"layer\":\"main\"}],\"refs\":[\"c049\",\"c059\",\"c060\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-32\",\"name\":\"孙昊\",\"aliases\":[\"昊昊\"],\"identity\":\"与张思凡网络相识的变身小说作者，在外地读书，张的男友。\",\"traits\":[\"会表达体贴：跨城探望、购物、亲密中留意对方\",\"有占有和控制倾向：询问与他人聊天，对安排不容置疑\",\"作出远期承诺：娶张、赚钱移民，本段未兑现\",\"善说情话\",\"欲望导向\",\"在意外界眼光\",\"承诺轻易\",\"对外表有条件的接纳\",\"包容亲密：陪同郊外休息并畅想共同生活\",\"好玩及顺从：被室友拿女装后参与短暂嬉闹\",\"对群体态度有差异：表面接纳但对胡存轻蔑\",\"能作甜蜜承诺：寄机械八音盒，答应毕业后接思凡去他的城市。\",\"存在占有欲：对思凡不愿谈过去感到不快。\",\"欲望与接纳之间有裂痕：c469她睡后对外貌的男性化特征真实流露排斥。\",\"擅长话术：用礼物和浪漫语言解释香水，重复同样说辞对不同对象。\",\"回避责任：拒绝同居、反复推脱见面。\",\"工具化伴侣：承认只为猎奇并在分手时性别羞辱。\"],\"portrait\":\"\",\"fate\":{\"name\":\"孙昊\",\"label\":\"与张思凡决裂\",\"text\":\"背着思凡与他人交往，遭撞破后承认浅薄动机并羞辱对方。思凡离开，二人关系结束。\",\"note\":\"后续人生未给完整交代；没有凭原文写出悔悟、死亡或复合。\",\"refs\":[\"c469\",\"c546\",\"c559\",\"c560\",\"c561\"]},\"status\":\"截至本段最后实质出场，已与张决裂；学业、莉莉关系及其他去向未进一步交代。\",\"statusRefs\":[\"c537\",\"c545\",\"c546\",\"c552\",\"c559\",\"c560\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"从初次到面馆露面开始，孙昊在张眼中是知道身份仍愿爱她的人，在苏眼中却带来难以言明的不安。张在疑虑与期待间接受他的爱情，第二次来访后亲密关系加深，日常电话更频繁。本段确有令张愉快的相处，也有占有欲征兆；不能因后续未知而提前宣布骗爱，亦不能把移民婚姻承诺当已实现。\",\"segmentFate\":\"截至c120已回外地，与张保持恋爱及频繁电话联系；承诺仍未兑现。\",\"refs\":[\"c052\",\"c055\",\"c056\",\"c091\",\"c094\",\"c098\",\"c099\"],\"layer\":\"main\"},{\"scope\":\"正文 c121—c240\",\"arc\":\"他每天频繁来电、许诺永不离开，在思思受家庭压力时提供依靠，但叙述反复展示温柔的条件：她用本声哭诉时被喝止，男装接站时令他冷淡，换女装又立即热情。他嘲阿牛、盯看夕晨，对新室友只称思思是朋友；承认曾有十几个女友。肯德基中他也承受旁人目光，却把思思的身份处境说得简单，引发耳光与相互道歉，爱情的裂缝未被热烈抹去。\",\"segmentFate\":\"短住尚未结束，与思思仍是恋人；有窥视室友与淡化名分行为，未写实际另交新恋人。\",\"refs\":[\"c140\",\"c189\",\"c190\",\"c208\",\"c209\",\"c210\",\"c211\",\"c212\",\"c223\",\"c240\"],\"layer\":\"main\"},{\"scope\":\"正文 c241—c360\",\"arc\":\"本段前期常与张相伴，也进入合租屋生活；苏对他潜意识没有好感。开学前张送他离城，随后她精心考虑生日礼物、选择模型枪邮寄。两人的山居想象显示关系期待，但未来是否共同生活尚未确定。室友把他视为已知并表面接纳群体的人，与柳未经说明来访的隐私风险不同；这不代表他对每位成员都同样尊重。\",\"segmentFate\":\"截至本段已返校离城，张寄出生日礼物；收件反应与长期结局未交代。\",\"refs\":[\"c243\",\"c244\",\"c265\",\"c284\",\"c312\",\"c313\",\"c333\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"在思凡眼中他是未来生活的希望，礼物、探访和亲密使她相信能相守。雨晴此前只从细节担忧他猎奇，思凡返城火车上的背叛场景也只是噩梦，不能提前当事实。但c469终于从他的视角写出外貌排斥，与口头答应思凡投奔形成明确裂缝。此时他并未被写成实际出轨或分手。\",\"segmentFate\":\"截至c480已结束这次小城探访返程，与思凡仍交往，毕业相聚约定未实施；最终结局需后文。\",\"refs\":[\"c381\",\"c407\",\"c425\",\"c466\",\"c469\",\"c471\"],\"layer\":\"main\"},{\"scope\":\"正文 c481—c600\",\"arc\":\"孙起初以关心和熟练的亲密表演维系张的信任，实际却多线交往。小说读者群中的调情、对男装的强烈反应及谎称朋友出事都是线索。c546读者看到他转赴莉莉家，c559张亲自撞破，c560他不再掩饰，拒绝修复，宣布厌倦。\",\"segmentFate\":\"截至本段最后实质出场，已与张决裂；学业、莉莉关系及其他去向未进一步交代。\",\"refs\":[\"c537\",\"c545\",\"c546\",\"c552\",\"c559\",\"c560\"],\"layer\":\"main\"}],\"refs\":[\"c052\",\"c055\",\"c056\",\"c091\",\"c094\",\"c098\",\"c099\",\"c140\",\"c189\",\"c190\",\"c208\",\"c209\",\"c210\",\"c211\",\"c212\",\"c223\",\"c240\",\"c243\",\"c244\",\"c265\",\"c284\",\"c312\",\"c313\",\"c333\",\"c381\",\"c407\",\"c425\",\"c466\",\"c469\",\"c471\",\"c537\",\"c545\",\"c546\",\"c552\",\"c559\",\"c560\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-33\",\"name\":\"李天明\",\"aliases\":[\"面馆夫妻的儿子\",\"面馆老板之子\"],\"identity\":\"张阿姨与李叔叔的儿子，初三学生。\",\"traits\":[\"先以外貌热情搭讪，后因出生性别转而辱骂\",\"拒绝当场道歉，暴露强烈偏见\",\"排斥／伤害性语言（本段仅回忆）\"],\"portrait\":\"\",\"fate\":null,\"status\":\"未在本段实际出现；是否改变态度未知。\",\"statusRefs\":[\"c214\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"在父母疼爱的生日之后，他来到店里，把苏当漂亮女孩主动亲近。苏坦白出生性别后，他从好感骤转为羞辱，令苏觉得连安全的工作地点也无法容身。他的父母反对并道歉，但本段没有他本人认错的行动；不可把母亲登门视为他的和解。\",\"segmentFate\":\"本段最后明确在面馆遭父母管教；未向苏亲自道歉。\",\"refs\":[\"c059\",\"c061\",\"c062\",\"c064\"],\"layer\":\"main\"},{\"scope\":\"正文 c121—c240\",\"arc\":\"雨晴回到无名面馆附近时，想起被夫妻儿子用刻薄语言辱骂的经历，过去好几天都难以恢复。如今她仍感激其父母，却怕对方在店内，也怕穿裙身份被看见，最后只从门外经过。该人物在本段没有新行动，但先前伤害持续限制雨晴与旧恩人的联系，构成事件结束后仍留在人心里的后果。\",\"segmentFate\":\"未在本段实际出现；是否改变态度未知。\",\"refs\":[\"c214\"],\"layer\":\"main\"}],\"refs\":[\"c059\",\"c061\",\"c062\",\"c064\",\"c214\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-34\",\"name\":\"万董\",\"aliases\":[\"酒吧老板\",\"万董事长\"],\"identity\":\"酒吧控制者，阿雷之父。\",\"traits\":[\"注意年龄与管理：面试质疑未成年、查顾总账目\",\"对苏等安排轻松工作却未保证执行\",\"支持儿子制止追赶，也对权势有判断\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段最后在办公室支持阿雷决定，酒吧后续管理与责任未展开。\",\"statusRefs\":[\"c068\",\"c071\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"万董在面试时询问证件与家庭，看到张的谎言仍准许上岗，安排轻松工作。实际服务环节发生侵害，说明其口头保护与场内执行存在缺口。儿子得知受害者后命令停止追赶，他明确支持这一决定；本段呈现复杂管理者，不能只写成全然善意救星。\",\"segmentFate\":\"本段最后在办公室支持阿雷决定，酒吧后续管理与责任未展开。\",\"refs\":[\"c068\",\"c071\"],\"layer\":\"main\"}],\"refs\":[\"c068\",\"c071\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-35\",\"name\":\"王主任\",\"aliases\":[\"王妈\"],\"identity\":\"酒吧服务员工协调者，约三十多岁女性，负责安排工作与工资。\",\"traits\":[\"把陪酒风险轻描淡写：将张派到女客包厢并默认男性不会吃亏\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段最后在派工阶段，后续责任未交代。\",\"statusRefs\":[\"c068\",\"c069\",\"c070\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"在顾总转交后，她成为实际派工者，给张安排陪女客、给苏安排送酒。她知道二人是万董交代的来客，却没有把“轻松工作”转为清晰安全边界。随后两人受害，本段未写她现场协助或事后反应，不能把她当救援角色。她与吧台女领班是不同层级人物。\",\"segmentFate\":\"本段最后在派工阶段，后续责任未交代。\",\"refs\":[\"c068\",\"c069\",\"c070\"],\"layer\":\"main\"}],\"refs\":[\"c068\",\"c069\",\"c070\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-36\",\"name\":\"顾总\",\"aliases\":[\"酒吧经理\"],\"identity\":\"万董下属、负责酒吧事务的年轻经理。\",\"traits\":[\"上恭下倨：面对万董顺从，对应聘者苛刻\",\"账目受查：小说暗示账面问题\"],\"portrait\":\"\",\"fate\":null,\"status\":\"最后明确离开办公室，后续未交代。\",\"statusRefs\":[\"c068\",\"c071\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"他在万董监督下接待两名求职者，并把换制服和实际排岗交给王主任。其上下不同态度体现雇佣体系的层级，苏因此更拘谨。后来救援时办公室已不见他，本段没有提供他是否处理侵害或承担后果的事实。他的账目问题也未在本段得到处理结果。\",\"segmentFate\":\"最后明确离开办公室，后续未交代。\",\"refs\":[\"c068\",\"c071\"],\"layer\":\"main\"}],\"refs\":[\"c068\",\"c071\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-37\",\"name\":\"二十七号包厢三名客人\",\"aliases\":[],\"identity\":\"酒吧中要求苏陪饮的未具名男性客人，与巷中团伙不应直接合并。\",\"traits\":[\"以客人身份施压劝酒\",\"顾忌店规而止于当场陪饮要求\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段后续未交代，未证明参与对赵老板的救援追赶。\",\"statusRefs\":[\"c069\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"苏首次送酒时受到这三人的身体接近和饮酒压力，因缺少拒绝经验喝酒。他们后来谈到可能跟踪，但叙述没有写实际跟踪行为；他们另有争夺街头地位的计划，也没有在本段完成。应区别于后续实际实施侵害的赵老板及巷中混混。\",\"segmentFate\":\"本段后续未交代，未证明参与对赵老板的救援追赶。\",\"refs\":[\"c069\"],\"layer\":\"main\"}],\"refs\":[\"c069\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-38\",\"name\":\"酒吧女领班\",\"aliases\":[\"吧台领班\"],\"identity\":\"酒吧执行送酒安排的未具名女领班。\",\"traits\":[\"以任务效率为主，对苏紧张醉态未充分关照\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段仅在工作派单中出现，救援后未交代。\",\"statusRefs\":[\"c069\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"她在苏疲于送酒并已饮下不少酒后，继续安排其去贵宾十四号送鸡尾酒。其角色连接普通服务工作与危险贵宾场景，本段没有深入家庭或性格叙述。研究应保留其排单作用，不把她与王主任或万董合并。她在情节上承担把新人送往贵宾区的连接作用。\",\"segmentFate\":\"本段仅在工作派单中出现，救援后未交代。\",\"refs\":[\"c069\"],\"layer\":\"main\"}],\"refs\":[\"c069\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-39\",\"name\":\"十五号包厢三名女客\",\"aliases\":[],\"identity\":\"张思凡酒吧兼职所面对的未具名女客。\",\"traits\":[\"以性别刻板印象正当化骚扰\",\"无视拒绝并进行性别羞辱\"],\"portrait\":\"\",\"fate\":null,\"status\":\"张挣脱后未交代三人的后续。\",\"statusRefs\":[\"c070\",\"c072\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"她们在陪酒工作中对张强迫触碰、嘲弄身体与性别。张明确认为工作仅限陪酒，终于挣脱决定离职，随后看到苏受害。该段揭示受害者性别与施害者性别不能决定是否侵害，不应把其写作轻松玩闹。这些互动明确违背张的意愿。\",\"segmentFate\":\"张挣脱后未交代三人的后续。\",\"refs\":[\"c070\",\"c072\"],\"layer\":\"main\"}],\"refs\":[\"c070\",\"c072\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-40\",\"name\":\"赵老板\",\"aliases\":[\"赵老头\"],\"identity\":\"酒吧贵宾客，财力显著，身边有保镖。\",\"traits\":[\"利用权势金钱胁迫：以小费使未成年苏饮酒\",\"趁失去意识实施侵害，事后恼怒追责\"],\"portrait\":\"\",\"fate\":null,\"status\":\"c071救援后被莫空打伤、怒骂保镖；后续追责和权势变化未交代。\",\"statusRefs\":[\"c070\",\"c071\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"他出现于贵宾赌局和陪酒情境，六百元小费对急需钱的苏极有诱惑。苏醉倒后遭他侵害，莫空闯入打退阻拦并带走苏。阿雷叫停追赶，万董透露赵不会一直得势，但只是人物预告式判断，本段未交代实际商业或司法结局。他的身份也没有完整姓名。\",\"segmentFate\":\"c071救援后被莫空打伤、怒骂保镖；后续追责和权势变化未交代。\",\"refs\":[\"c070\",\"c071\"],\"layer\":\"main\"}],\"refs\":[\"c070\",\"c071\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-41\",\"name\":\"万剑雷\",\"aliases\":[\"万少爷\",\"万董的儿子\",\"阿雷\",\"雷哥\",\"浪人发型少年\"],\"identity\":\"约十五六岁的万董之子，本段仅称阿雷或万少爷。\",\"traits\":[\"有是非感：听明女服务员受欺负便叫停追赶\",\"与父亲亲近：向父亲说明处理并获支持\",\"爱开玩笑\",\"会害羞\",\"体贴\",\"与好友默契\",\"对雨晴有好感\"],\"portrait\":\"\",\"fate\":null,\"status\":\"与雨晴互知姓名，本段未交换电话、约会或确立恋情；高中尚未正式入学。\",\"statusRefs\":[\"c147\",\"c148\",\"c215\",\"c216\",\"c217\",\"c218\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"阿雷并未亲自进入包厢救苏，而是在逃离过程中听说起因，以身份命令保安不再追人。这一干预消除了莫空等人的后续追击危险。他还谈到朋友老管的儿子当天失联，但两人关系和后者身份在本段没有补全，不能据此猜认。全名只能等待后文回收。\",\"segmentFate\":\"本段最后仍在父亲酒吧，未与苏正式相识；全名待后文确认。\",\"refs\":[\"c071\"],\"layer\":\"main\"},{\"scope\":\"正文 c121—c240\",\"arc\":\"游乐园时他和洛胖、管鹏看到雨晴为娃娃伤心，出手抓取并听她唱歌；再会河堤正式自报姓名，对其笑容与忧伤都很在意。和管鹏互损却配合自然，狂风中主动扶起她。雨后他忽然决定离开，具体原因未明，只留下不想打扰的思绪。两次交集为雨晴打开同龄男性善意，却未发展成稳定联系。\",\"segmentFate\":\"与雨晴互知姓名，本段未交换电话、约会或确立恋情；高中尚未正式入学。\",\"refs\":[\"c146\",\"c147\",\"c148\",\"c215\",\"c216\",\"c217\",\"c218\"],\"layer\":\"main\"}],\"refs\":[\"c071\",\"c146\",\"c147\",\"c148\",\"c215\",\"c216\",\"c217\",\"c218\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-42\",\"name\":\"老管的儿子\",\"aliases\":[],\"identity\":\"阿雷提及的常一起玩耍的朋友，本段没有姓名或实际出场确认。\",\"traits\":[\"性格未交代\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段去向不明，须后文核验。\",\"statusRefs\":[\"c071\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"阿雷说当天找不到这位朋友，万董此前也询问为何不一起玩。这只是一段人物关系线索，可以在后文作为认人依据，不能独凭同一日的时间接近把他认成巷中求援少年。正文当前尚无足够证据说明其家庭、学校或卷入事件。一切更细身份仍待回收。\",\"segmentFate\":\"本段去向不明，须后文核验。\",\"refs\":[\"c071\"],\"layer\":\"main\"}],\"refs\":[\"c071\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-43\",\"name\":\"曾虐待张思凡的富人\",\"aliases\":[\"张思凡旧事中的有钱人\",\"富商（张思凡前传）\"],\"identity\":\"张思凡回忆中的剥削者，以高额报酬吸引她，希望赚取手术费。\",\"traits\":[\"利用弱势需求作出经济承诺\",\"严重虐待且未支付承诺报酬\",\"操纵与暴力：先以宽松待遇和报酬降低警惕，再剥夺自主\",\"把人作为工具：以羞辱和控制磨损受害者意志\"],\"portrait\":\"\",\"fate\":null,\"status\":\"仅回忆出现，身份与后果均未揭示。\",\"statusRefs\":[\"c072\",\"c098\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"张曾以为忍受富人的要求就能累积手术资金，却遭长期伤害，最后无法承受而逃离，钱也没有拿到。她到酒吧事件后才向醉睡的苏倾诉，此经历解释了对被尊重的爱与安全的渴求。原著叙述包含露骨内容，资料只保留虐待与经济剥削的情节事实。\",\"segmentFate\":\"仅回忆出现，身份与后果均未揭示。\",\"refs\":[\"c072\",\"c098\"],\"layer\":\"main\"},{\"scope\":\"c601—c665；x001—x079（全部补充篇）\",\"arc\":\"张思凡本想用一个月交易筹手术费，但第四天后情境转为强迫侵害，不能因最初答应交易便视为对以后暴力的同意。富商外出给了她逃生空隙，故事随后集中在受害者夺回自由，没有提供他被报案、逮捕或惩罚的结果。应保留事件严重性而不重现施害细节。\",\"segmentFate\":\"张思凡成功逃离；富商是否被追责未交代。\",\"refs\":[\"x059\",\"x060\",\"x061\"],\"layer\":\"prequel\"}],\"refs\":[\"c072\",\"c098\",\"x059\",\"x060\",\"x061\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-44\",\"name\":\"胡玉牛父亲与祖父\",\"aliases\":[\"胡父\",\"胡家祖父\"],\"identity\":\"武艺卖艺家族长辈，将胡玉牛视作最后男丁和下一代传承者。\",\"traits\":[\"重技艺传承：从小训练胡并赞赏其天赋\",\"以家族继承设定人生道路\"],\"portrait\":\"\",\"fate\":null,\"status\":\"仅在胡的回忆和讲述中出现，本段未正面处理出柜冲突。\",\"statusRefs\":[\"c086\",\"c097\",\"c098\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"他们所继承的是民间卖艺与跌打药方，并非玄幻武功。对胡的能力寄望很高，却未看见孩子不想成为男性家主的愿望。胡在倾诉中说明这种期待与内心的冲突；本段未直接描写两位长辈得知女性身份后的反应，不可把苏父的暴力套用到胡家。\",\"segmentFate\":\"仅在胡的回忆和讲述中出现，本段未正面处理出柜冲突。\",\"refs\":[\"c086\",\"c097\",\"c098\"],\"layer\":\"main\"}],\"refs\":[\"c086\",\"c097\",\"c098\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-45\",\"name\":\"手机店老板\",\"aliases\":[\"年轻手机商\"],\"identity\":\"文澜学院旁步行街手机店老板，大学毕业不久，与张是旧识顾客关系。\",\"traits\":[\"善于推销但可协商：报价后接受张讨价\",\"愿提供选项并展示电视功能\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段售出手机与电话卡后未再出场。\",\"statusRefs\":[\"c087\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"苏第一次拿劳动积蓄买手机，老板向两人展示不同型号与价格。张利用熟客关系和直接谈价争取到三百六十元机价，再争取低月费电话卡。老板的主要叙事作用是帮助建立个人通信工具与展现张在现实交往上的熟练，不足据其自称赚十元判断实际利润。\",\"segmentFate\":\"本段售出手机与电话卡后未再出场。\",\"refs\":[\"c087\"],\"layer\":\"main\"}],\"refs\":[\"c087\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-46\",\"name\":\"文学社社长\",\"aliases\":[\"络腮胡社长\"],\"identity\":\"蓝阳大学文学社社长，未具名，外表显老。\",\"traits\":[\"不拘礼节：茶话会大吃泡面\",\"幽默懒散：只按押韵乱接诗句、采购清单常相同\",\"会组织收尾：招呼社员整理\"],\"portrait\":\"\",\"fate\":null,\"status\":\"茶话会后继续组织社团，本段未再展开个人支线。\",\"statusRefs\":[\"c088\",\"c089\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"看似与文学气氛不符的社长，用错接古诗把茶话会变成欢笑场景，间接帮助苏释放平日克制的笑声。他误认苏为小学生，其他社员随之玩笑，但没有类似李天明的性别羞辱。人物功能在于提供轻松群体经验与校园向往。姓名未在该场活动中公布。\",\"segmentFate\":\"茶话会后继续组织社团，本段未再展开个人支线。\",\"refs\":[\"c088\",\"c089\"],\"layer\":\"main\"}],\"refs\":[\"c088\",\"c089\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-47\",\"name\":\"雯雯\",\"aliases\":[\"步行街美貌少女\",\"文澜初中少女\",\"别墅少女\",\"大小姐\",\"漂亮女孩\",\"雯雯\",\"海边别墅大小姐\",\"海边大小姐\",\"病弱大小姐\"],\"identity\":\"穿文澜初中校服的未具名少女，c088在步行街寻找什么。\",\"traits\":[\"本段仅外貌印象，没有足够行为判断性格\",\"温柔\",\"有主见\",\"神秘\",\"忧伤\",\"知晓不同时间的自己\",\"沉静大方：募捐摊避雨后捐出较大金额。\",\"虚弱忧伤：担心离去，留恋女仆及生活\",\"温柔珍惜：要求水水称名字并嘱托照顾未来自己\",\"转变后困惑：暴雨醒后不识情境、惊讶时间和身体\",\"温柔不摆身份：耐心听苏推销，买咖啡鼓励。\",\"在苏眼中代表羡慕与遥远的美好生活。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段在小城市日常生活，无单独结局。\",\"statusRefs\":[\"c501\",\"c539\",\"c570\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"张与苏被她的美丽吸引，并由此比较自己的呈现与外貌。该段更多揭示主角们的女性审美与自我评价，少女本人仅短暂路过、没有与她们说话。她寻找的对象和真实身份都未揭开，应待后文确认再与其他角色合并。也不能用美貌替代性格分析。\",\"segmentFate\":\"本段仅在步行街露面，无确定姓名或结局。\",\"refs\":[\"c088\",\"c113\"],\"layer\":\"main\"},{\"scope\":\"正文 c121—c240\",\"arc\":\"她先在超市寻找同行少年、后于别墅被四人认出；面对保镖要逐客，她自主请她们入内，又拒交换姓名，只询问是否应追回放弃选择的爱人。雨晴愿意见面确认爱的回答让她振作，独处又道那人失忆。台风中她让水水称自己雯雯，谈未来不同阶段的自己、预知小女仆成熟，并嘱照料那个茫然的我，显出与世界线相关的悬念。\",\"segmentFate\":\"仍在海边别墅，未写死亡或换魂已发生；爱情对象与完整身份尚不明。\",\"refs\":[\"c122\",\"c137\",\"c202\",\"c224\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"雨晴认出她而怕暴露身份，起初把主仆靠近理解为潜在羞辱；实际大小姐并未如此，默默捐出约一两千元。之后她在超市又被雨晴远远看见，成为漂亮外表与普通消费生活的观察对象。本段需要和前段明确姓名对应，不能凭本段猜名。\",\"segmentFate\":\"本段仍正常生活，未交代独立结局。\",\"refs\":[\"c224\",\"c277\",\"c412\",\"c413\",\"c476\"],\"layer\":\"main\"},{\"scope\":\"正文 c241—c360\",\"arc\":\"c277她对莫诉说写信会被历史修正抹去，听取留信物建议并像告别般叮嘱水水。教师节她独坐步行街等待，短眠后举止显著变化，前后情绪从哀伤变茫然。苏只是旁观，读者虽见前后呼应，仍无法仅凭此段确认全部时间机制、两个意识身份及当前自己是否真正死亡。随后相似年轻女人抱她携熊乘跑车离开。\",\"segmentFate\":\"截至c312已被相似年轻女人带走，疑似发生接替；后续身份和生死机制待后文。\",\"refs\":[\"c276\",\"c277\",\"c311\",\"c312\"],\"layer\":\"main\"},{\"scope\":\"正文 c481—c600\",\"arc\":\"她先作为卖书少年珍藏陶人形象和苏的旧日记忆出现，随后到超市买酸奶时接受苏第一次主动推销。她爽快购买大盒咖啡，使苏获得社交信心；对其丰富背景本段不展开。\",\"segmentFate\":\"截至本段在小城市日常生活，无单独结局。\",\"refs\":[\"c501\",\"c539\",\"c570\"],\"layer\":\"main\"}],\"refs\":[\"c088\",\"c113\",\"c122\",\"c137\",\"c202\",\"c224\",\"c277\",\"c412\",\"c413\",\"c476\",\"c276\",\"c311\",\"c312\",\"c501\",\"c539\",\"c570\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-48\",\"name\":\"张思凡的文学社好友\",\"aliases\":[\"清秀男生\",\"学校里的唯一知情好友\"],\"identity\":\"蓝阳大学文学社成员，约一米七五，张在校唯一知晓其身份的朋友，尚未具名。\",\"traits\":[\"与张熟稔可互相调侃\",\"性别及取向仍在探索，相关信息由张转述\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段仅茶话会出场；姓名、性别认同与后续关系待后文。\",\"statusRefs\":[\"c089\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"他在茶话会露面并与张开玩笑，张称两人是兄弟，又不愿孙昊知道这位亲近朋友。张进一步说他有相似性别倾向、可能只喜欢她们这一类人且仍摇摆。这里既没有本人完整自我认同，也没有两人恋爱的证据，应保留转述与未定性。\",\"segmentFate\":\"本段仅茶话会出场；姓名、性别认同与后续关系待后文。\",\"refs\":[\"c089\"],\"layer\":\"main\"}],\"refs\":[\"c089\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-49\",\"name\":\"方莜莜父母\",\"aliases\":[],\"identity\":\"方莜莜的父母，原城市亲属背景，本段未正面出场。\",\"traits\":[\"实际态度与性格未足够描写\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段未正面出场，是否知道方的女性身份与是否接受均未明确。\",\"statusRefs\":[\"c100\",\"c102\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"方说在家生活疲惫、熟人环境让她不舒服，离开时告诉父母去外地工作。叙述只说明关系有压力，未像苏家那样给出具体殴打、剪发或明确反对的场景。研究时应保留这种信息空白，不以同类人物的一般经历代替他们的行为。这些空白需要后文回答。\",\"segmentFate\":\"本段未正面出场，是否知道方的女性身份与是否接受均未明确。\",\"refs\":[\"c100\",\"c102\"],\"layer\":\"main\"}],\"refs\":[\"c100\",\"c102\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-50\",\"name\":\"姚玲\",\"aliases\":[\"员工指导\",\"92员工指导\"],\"identity\":\"大润发员工指导，约二十七八岁、微胖女性。\",\"traits\":[\"自来熟热情：先夸苏可爱\",\"交代快：信息过多令新人吃力\",\"迅速转交具体指导给促销员\",\"干练\",\"重细节\",\"愿意教人\",\"有晋升心\",\"强调任务完成，对促销员返家需要缺少体谅。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段仍在工作，后续未交代。\",\"statusRefs\":[\"c416\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"她承接张燕的新人教学，介绍干货区范围和分货原则，但很快因其他事务把苏交给百事促销员。苏觉得像层层往下推，实际后续教学由百事完成。资料保留热情与转交工作这两面，不把苏的腹诽直接变成已证实的失职判断。她的真实姓名在此已给出。\",\"segmentFate\":\"本段只在初入职培训中出现，后续未展开。\",\"refs\":[\"c114\"],\"layer\":\"main\"},{\"scope\":\"正文 c121—c240\",\"arc\":\"姚玲负责比主管更琐碎且需走动的日常事务，教雨晴如何核条码、写清单处理退货，夸她字娟秀却提醒应写大些。雨晴首次在收银岗位忙过下班时刻，她又接手使其能离开；雨晴迟到时也区分特殊情况与考勤规则。其位置说明女性基层管理者既有权力，也承担大量实际劳动，和后来翁锡芽为相同职级。\",\"segmentFate\":\"继续在超市任员工指导；与雨晴因调部门减少直接共事。\",\"refs\":[\"c129\",\"c153\",\"c164\",\"c181\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"除夕前最后工作日的管理态度构成对照，雨晴也由此看见不同管理者对人的处理方式。此段没有展示她独立的家庭或私人生活，不能把岗位态度扩写为完整人格判断。\",\"segmentFate\":\"截至本段仍在工作，后续未交代。\",\"refs\":[\"c416\"],\"layer\":\"main\"}],\"refs\":[\"c114\",\"c129\",\"c153\",\"c164\",\"c181\",\"c416\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-51\",\"name\":\"张燕\",\"aliases\":[\"大润发干货区主管\",\"92主管\"],\"identity\":\"苏雨晴在大润发二楼干货区的直属主管，三十多岁近四十的女性。\",\"traits\":[\"按流程分派工作：指派指导员、价签任务\",\"在表情刻薄印象外有和气一面\",\"教学简洁：演示终端扫码打印\",\"重考勤\",\"有管理权\",\"较少亲自重活\",\"分配辛苦工作：常让年长夏伯处理脏累差事\",\"对促销任务要求强硬：节前仍要求促销员留下。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段仍在超市任职，后续未交代。\",\"statusRefs\":[\"c416\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"苏初入职时，张燕给出部门归属并把培训交给姚玲；之后让苏寻找同事帮忙、换价签、学习核价。她没有因苏走神立即责难，逐步交给其可独立操作的任务。到c120，扫码工作适合苏的细心，让最初的慌乱转为暂时自在，主管关系仍在开端。\",\"segmentFate\":\"截至c120仍负责指导苏工作，没有冲突或处分结局。\",\"refs\":[\"c114\",\"c115\",\"c117\",\"c120\"],\"layer\":\"main\"},{\"scope\":\"正文 c121—c240\",\"arc\":\"她在早期工作段落中代表排班与考勤制度，雨晴疲倦时须面对是否按时打卡的问题，夏伯伯会替其解释已做过工作。与员工指导姚玲相比，张燕更多坐在后仓办公区处理文书，日常行走、教新人及补缺则落在下级身上。这种区分帮助读者看清超市并非只有一位上司，也说明雨晴获得的宽容往往来自同事的具体斡旋。\",\"segmentFate\":\"雨晴调往01/96部门后，她不再直接管理该工作线；本段未写她离职。\",\"refs\":[\"c126\",\"c127\",\"c129\"],\"layer\":\"main\"},{\"scope\":\"正文 c241—c360\",\"arc\":\"本段主要经夏的劳动处境被提及，没有足够材料补全个人性格。她的作用在于显出部门劳动不均及老人处境，与苏获得王保护形成对比；不可与张思凡因同姓混为一人。\",\"segmentFate\":\"仍为干货部主管，个人后续未写。\",\"refs\":[\"c274\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"与姚玲等人的节前安排相比，王海峰愿意体谅下属及促销人员的实际困难。张燕承担工作环境中缺乏弹性的一面，推动读者理解王海峰的失望，而非全书单独展开的反派。\",\"segmentFate\":\"本段仍在超市任职，后续未交代。\",\"refs\":[\"c416\"],\"layer\":\"main\"}],\"refs\":[\"c114\",\"c115\",\"c117\",\"c120\",\"c126\",\"c127\",\"c129\",\"c274\",\"c416\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-52\",\"name\":\"百事促销员\",\"aliases\":[\"百事\"],\"identity\":\"大润发未具名中年女长期促销员，以负责品牌为称呼。\",\"traits\":[\"耐心讲解：详细教条码与规格\",\"善意而不深究：识破年龄可能仍不戳穿\",\"熟悉工作制度：解释长促短促区别\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段仍在超市做长期促销，无单独结局。\",\"statusRefs\":[\"c114\",\"c115\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"她在姚玲安排下带苏补货，一边做一边解释，让读书基础较好的苏很快理解核对标签。她知道商场工作有不合理之处，也以经验口吻劝苏以后会懂，使苏略感被当小孩。她是新职场的实用引导者，真实姓名与品牌关系之外的经历未给出。\",\"segmentFate\":\"截至本段仍在超市做长期促销，无单独结局。\",\"refs\":[\"c114\",\"c115\"],\"layer\":\"main\"}],\"refs\":[\"c114\",\"c115\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-53\",\"name\":\"夏仕尼\",\"aliases\":[\"夏老伯\",\"夏伯伯\",\"大伯伯\",\"夏叔\",\"夏伯\",\"夏仕尼（夏伯伯）\"],\"identity\":\"大润发白发男员工，原给大老板开车，公司破产后换工作，称还有两年退休。\",\"traits\":[\"和气宽容：不介意名字谐音玩笑\",\"细心耐心：替苏搬重物、答顾客问题、教购员工餐\",\"勤劳有礼：一整天持续补货，停下认真听人说话\",\"和善\",\"勤恳\",\"体谅晚辈\",\"不争计较\",\"任劳任怨且乐观：常干脏累报损活\",\"愿关怀他人：主动帮苏，提醒胡睡过头\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段仍在超市任职。\",\"statusRefs\":[\"c274\",\"c304\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"苏在不知道如何求助的第一天主动帮他搬米，他没有嫌她力气小，反而让她慢慢做、留下轻活。两人从安静协作到互报姓名，老伯带苏买饭、解释付款和通道，成为新工作中的安全感。他误以为苏与胡恋爱，苏澄清后并未披露胡的秘密；其关心仍建立在有限信息上。\",\"segmentFate\":\"截至c120继续超市工作，退休只是未来打算，未已退休。\",\"refs\":[\"c115\",\"c116\",\"c117\",\"c120\"],\"layer\":\"main\"},{\"scope\":\"正文 c121—c240\",\"arc\":\"他初见疲惫雨晴便拿孙女作亲切比照，后来挡住油箱、替她搬重物、掩护她午休，还在主管问起时替她说好话。雨晴调部门后与他午饭重逢，第一次听见全名夏仕尼；他照旧接受别人不愿处理的脏污破损货。雨晴替他不平，他却以总要有人做的平和态度应对，并建议她寻找更轻松工作，形成劳动环境中稳定而不张扬的善意。\",\"segmentFate\":\"仍在超市工作，尚未退休；没有离职、病亡或其他结局。\",\"refs\":[\"c121\",\"c126\",\"c127\",\"c207\"],\"layer\":\"main\"},{\"scope\":\"正文 c241—c360\",\"arc\":\"同处破包处理时，他使苏看到另一位比她更常被分派劳动的人；主管张燕把困难差事交给他，他仍宽厚。后来他提醒沉睡后仓的胡已晚，直接帮助接柳支线继续。只因其年纪或低岗位，不能抹去在行动中表现的可靠。\",\"segmentFate\":\"截至本段仍在超市任职。\",\"refs\":[\"c274\",\"c304\"],\"layer\":\"main\"}],\"refs\":[\"c115\",\"c116\",\"c117\",\"c120\",\"c121\",\"c126\",\"c127\",\"c207\",\"c274\",\"c304\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-54\",\"name\":\"王海峰\",\"aliases\":[\"一米六男员工\",\"矮个子男人\",\"矮个酒柜男员工\",\"老王\"],\"identity\":\"大润发二楼酒柜附近男员工，约二十多岁、一米六，未具名。\",\"traits\":[\"说话爱调侃，苏觉得带戏弄意味\",\"办事实际：提醒付款与小票\",\"外表年轻\",\"爱互损\",\"能干\",\"亲自干活\",\"好麻将\",\"关照下属\",\"有灰色妥协\",\"有担当：错价风波宁担责也不无休争辩\",\"熟悉人情事务：巧妙协调职业索赔\",\"特别照顾苏：安排轻活、挡调前台、调休避重班\",\"直接幽默：和陈拌嘴、与苏像兄妹互损\",\"体谅员工：安排轻松岗位、准雨晴参加公益、病中同伴愿替其分担。\",\"有专业能力：处理厂家与商品事务，能流畅英语协助顾客。\",\"并非完美：接受厂家小额好处，显示职场中的妥协。\",\"忍耐有界限：结石病中遭责骂后认为恩情已还，执意辞职。\",\"善待部属、善于玩笑，离职后仍介绍岗位。\",\"不满上层管理，不愿长期受其摆布。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段辞职返乡，后来具体职业未交代。\",\"statusRefs\":[\"c500\",\"c502\",\"c503\"],\"segments\":[{\"scope\":\"正文c001—c120\",\"arc\":\"他把薯片箱掉到苏头上后询问并道歉，但苏怀疑笑意并不真诚。中午在酒柜收银再见，他用揶揄口气提醒反应迟缓的苏付款，又提醒带上通道需要的小票。此时只有让苏烦躁的初印象，是否故意砸人、后续性格与姓名都未定，不宜直接定义反派。\",\"segmentFate\":\"截至c120仍是新职场未熟悉同事，尚未给姓名。\",\"refs\":[\"c115\",\"c116\"],\"layer\":\"main\"},{\"scope\":\"正文 c121—c240\",\"arc\":\"他初以粗声、玩笑和曾砸箱的印象令雨晴紧张，实际主动搬货、教工作、请饭、调排班，逐渐成为她感到像同学与表哥的主管。贫寒出身、资助大学后留超市的经历与其能力形成落差；麻将通宵和部门灰色促销利益又使他并不理想化。与陈淑艳互损亲近而引他人不满，贵酒成交和半年总结展现工作琐碎，灾后替雨晴带食物则直接托住她的心情。\",\"segmentFate\":\"仍任主管，龙年茅台售出获奖金；与陈淑艳关系亲近但非明确恋人。\",\"refs\":[\"c164\",\"c165\",\"c166\",\"c179\",\"c180\",\"c181\",\"c182\",\"c185\",\"c186\",\"c234\",\"c235\"],\"layer\":\"main\"},{\"scope\":\"正文 c241—c360\",\"arc\":\"他让职场不只是一片压迫：一面遭上级无理追责，一面维护下属的体力与工作空间；处理红酒索赔后又补上保质期检查，体现经验与执行力。对苏的照顾让她能不怕冒犯地抗议排班；他解释因培训缺人调休，才让她懂得保护的用意。前台年轻职员对他显好感，他对苏则明确是关心年幼伙伴而非追求。\",\"segmentFate\":\"截至本段仍为主管，偶尔休假时苏工作更吃力；错价赔偿是否实际免除未有细账。\",\"refs\":[\"c252\",\"c253\",\"c254\",\"c255\",\"c256\",\"c263\",\"c278\",\"c327\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"他的人情味支撑了雨晴在超市的安全感，也凝聚周超、陈淑艳等同事。上级把责任和压力推给他，病中仍勒令返工，使长期积累的不满转为离职决定。申请最终获批，回乡继续做主管或开店尚在考虑。员工的挽留混有真实感情与对保护伞消失的担忧。\",\"segmentFate\":\"截至c480辞职已批准，等待下月发薪离职；去向未定，小超市只是构想。\",\"refs\":[\"c366\",\"c369\",\"c371\",\"c372\",\"c395\",\"c402\",\"c410\",\"c412\",\"c416\",\"c430\",\"c455\",\"c465\",\"c476\"],\"layer\":\"main\"},{\"scope\":\"正文 c481—c600\",\"arc\":\"他以告别聚餐和同事游戏结束超市工作，计划返乡寻新出路。对无证件的苏没有冷眼，联系朋友为她提供加油站机会，提醒若被欺负可联系，成为苏离职转型的桥梁。\",\"segmentFate\":\"本段辞职返乡，后来具体职业未交代。\",\"refs\":[\"c500\",\"c502\",\"c503\"],\"layer\":\"main\"}],\"refs\":[\"c115\",\"c116\",\"c164\",\"c165\",\"c166\",\"c179\",\"c180\",\"c181\",\"c182\",\"c185\",\"c186\",\"c234\",\"c235\",\"c252\",\"c253\",\"c254\",\"c255\",\"c256\",\"c263\",\"c278\",\"c327\",\"c366\",\"c369\",\"c371\",\"c372\",\"c395\",\"c402\",\"c410\",\"c412\",\"c416\",\"c430\",\"c455\",\"c465\",\"c476\",\"c500\",\"c502\",\"c503\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-55\",\"name\":\"街头小贩与普通服务者\",\"aliases\":[],\"identity\":\"包括三楼收银员、西瓜摊主、手工摊主、奶茶老板及公交司机等无名小人物\",\"traits\":[\"日常善意\",\"维生辛劳\",\"也有偏见与随口判断\"],\"portrait\":\"\",\"fate\":null,\"status\":\"各自继续工作，本段无完整个别结局；不把无名角色强行合为同一人。\",\"statusRefs\":[\"c128\",\"c187\",\"c188\",\"c203\",\"c204\",\"c214\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"三楼收银员把雨晴当害羞少女正常接待，西瓜摊主与她聊孩子功课，手工摊主额外赠蝴蝶挂件，构成小城生活可被安顿的部分。公交司机一路热情聊天，遭飙车欺凌后愤怒，言语又带片面仇富；其他促销员或顾客会使她承受委屈。这些角色没有独立长篇结局，却使相同身份在不同日常场合获得完全不同的待遇。\",\"segmentFate\":\"各自继续工作，本段无完整个别结局；不把无名角色强行合为同一人。\",\"refs\":[\"c128\",\"c187\",\"c188\",\"c203\",\"c204\",\"c214\"],\"layer\":\"main\"}],\"refs\":[\"c128\",\"c187\",\"c188\",\"c203\",\"c204\",\"c214\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-56\",\"name\":\"王经理\",\"aliases\":[],\"identity\":\"思思实习公司的经理，传奇同服玩家\",\"traits\":[\"看重能力\",\"好面子\",\"关系熟稔\",\"善用下属\"],\"portrait\":\"\",\"fate\":null,\"status\":\"仍是思思上司；未得知她完整性别生活和恋情。\",\"statusRefs\":[\"c130\",\"c140\",\"c208\",\"c240\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"思思在办公室评价他旧PPT欠佳一度尴尬，交出更好方案后获得隐约认可；在传奇里为他护送珍贵狗书与装备又拉近关系。后来思思可向他请假接孙昊，也能用玩笑说话。灾后任务越来越难，他说没完成不能吃午饭却又称随口一说，让思思认真加班至近一点。这种亲近同时含有上司话语对下属实际生活的支配。\",\"segmentFate\":\"仍是思思上司；未得知她完整性别生活和恋情。\",\"refs\":[\"c130\",\"c140\",\"c208\",\"c240\"],\"layer\":\"main\"}],\"refs\":[\"c130\",\"c140\",\"c208\",\"c240\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-57\",\"name\":\"朱志杰\",\"aliases\":[],\"identity\":\"十八岁初中毕业生，莜莜新部门下属\",\"traits\":[\"认真\",\"想学技能\",\"朴实\",\"愿意帮忙\",\"聪明好学：学习编程、修电脑\",\"体贴识趣：见方换装尴尬主动回避\",\"爱玩但尊敬上司：趁空游戏、称方老大\",\"有能力但缺自信：担心学历使自己不能任主管。\",\"愿学习、珍惜好上司。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"c397被推荐为临时主管，正式长期任命及后来表现未交代。\",\"statusRefs\":[\"c389\",\"c397\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"他入职原以为网络工程会做高深事务，先从电脑清灰、重装系统学起，在莜莜指导下表现努力。主管没有摆架子，写教程并承认指示不够清楚，改善了他的紧张。她身体不适时他帮扶，由触觉及外貌误猜她是女扮男装，这只是他的推断，和实际身份不同。这个小人物展示技术工作也能成为被信任与尊重的空间。\",\"segmentFate\":\"仍在莜莜部门学习工作，身份误会未解开。\",\"refs\":[\"c131\"],\"layer\":\"main\"},{\"scope\":\"正文 c241—c360\",\"arc\":\"他让方的职场能力通过具体教学呈现，也成为身体秘密可能被看见的近距离同事。送餐事故后他注意到变化却没追问，帮处理费用并让出换衣空间；后来维修软驱、和方自然玩笑，表现关系未破裂。是否实际知晓方的性别经历本段未证实，不能把看出女性化身体等同完全知情。\",\"segmentFate\":\"截至c331仍在公司任职并受方培养；未知方将辞职的真实原因。\",\"refs\":[\"c241\",\"c242\",\"c331\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"莜莜离职前看中他的实际能力，把工作方法逐步教给他，再向公司推荐担任临时主管。他既舍不得莜莜，又对接任犹疑，最后在鼓励中迈出一步。支线呈现学历与实际潜力的差异，也显示莜莜离开职业岗位时仍照顾团队后续。\",\"segmentFate\":\"c397被推荐为临时主管，正式长期任命及后来表现未交代。\",\"refs\":[\"c389\",\"c397\"],\"layer\":\"main\"}],\"refs\":[\"c131\",\"c241\",\"c242\",\"c331\",\"c389\",\"c397\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-58\",\"name\":\"莜莜公司的总经理\",\"aliases\":[],\"identity\":\"提拔莜莜成立网络工程部门的负责人\",\"traits\":[\"信任技术能力\",\"愿意授权\"],\"portrait\":\"\",\"fate\":null,\"status\":\"继续信任莜莜，未有撤职或项目结果的完整交代。\",\"statusRefs\":[\"c131\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"他让方宇悠负责新设网络工程部门，并交付公司网站相关任务，给她较少受旧同事掣肘的工作位置。原同事对她上升未必友善，朱志杰又是年轻初学者，因此这份来自最高负责人的信任是其能够独撑部门的重要条件。文本未给经理姓名，也没有更多个人生活，应保留为职务角色。\",\"segmentFate\":\"继续信任莜莜，未有撤职或项目结果的完整交代。\",\"refs\":[\"c131\"],\"layer\":\"main\"}],\"refs\":[\"c131\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-59\",\"name\":\"小天与奶奶\",\"aliases\":[],\"identity\":\"公园中三四岁的幼童及照料他的奶奶\",\"traits\":[\"孩子善意与好奇\",\"奶奶疼爱且有传统男性规范\"],\"portrait\":\"\",\"fate\":null,\"status\":\"小伤得到照料，公园小故事结束；姓名只小天，奶奶无姓氏。\",\"statusRefs\":[\"c132\",\"c133\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"小天被石头绊倒，奶奶关心伤口又说男子汉不该哭，买糖和创可贴安抚，使雨晴想起母亲从小相似要求。孩子后来拿竹篓清理路中石块，免得别人再跌，又被好看的鹅卵石吸引，装满后舍弃一部分。这个完整小插曲把规训、善意、好奇与取舍连接起来，成为雨晴思考实现愿望要放下什么的镜面。\",\"segmentFate\":\"小伤得到照料，公园小故事结束；姓名只小天，奶奶无姓氏。\",\"refs\":[\"c132\",\"c133\"],\"layer\":\"main\"}],\"refs\":[\"c132\",\"c133\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-60\",\"name\":\"二表哥与三表哥\",\"aliases\":[],\"identity\":\"分别比雨晴大五岁、四岁的台湾表亲，互非亲兄弟\",\"traits\":[\"二表哥爱笑\",\"三表哥爱逗弄\",\"亲近童年雨晴\"],\"portrait\":\"\",\"fate\":null,\"status\":\"仅回忆出场，近况未知。\",\"statusRefs\":[\"c133\",\"c199\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"三位表哥中，二表哥以爱笑、三表哥以喜欢逗她形成个性区分，都与大表哥一道带雨晴玩耍。雨晴想起他们时会把母系乡村的开放、游戏和被允许柔弱，同父系家族对不够阳刚的自己的排斥相对照。三表哥不擅游泳但会简单游几圈的记忆，还成为她惊讶夕晨完全不会游泳的参照。\",\"segmentFate\":\"仅回忆出场，近况未知。\",\"refs\":[\"c133\",\"c199\"],\"layer\":\"main\"}],\"refs\":[\"c133\",\"c199\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-61\",\"name\":\"外婆与三位表哥\",\"aliases\":[],\"identity\":\"雨晴台湾母系亲属，三个表哥彼此并非亲兄弟\",\"traits\":[\"亲切\",\"接纳童年雨晴\",\"提供自由感\"],\"portrait\":\"\",\"fate\":null,\"status\":\"都只以回忆出现；成年近况和对她身份的态度未知。\",\"statusRefs\":[\"c133\",\"c149\",\"c186\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"台湾外婆家有开阔花园和木板绳秋千，与杭州公园的铁制围栏形成自由与管束对照。三表哥比她分别大七、五、四岁：大表哥稳重温柔，二表哥爱笑，三表哥爱逗她，都愿带她玩。童年她说想做女孩、嫁大表哥，他以童言回应；这是孩子间安慰，不能当已约婚或成年恋情。多年未见，他们如今会否理解她未明。\",\"segmentFate\":\"都只以回忆出现；成年近况和对她身份的态度未知。\",\"refs\":[\"c133\",\"c149\",\"c186\"],\"layer\":\"main\"}],\"refs\":[\"c133\",\"c149\",\"c186\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-62\",\"name\":\"大表哥\",\"aliases\":[\"大哥\",\"大白菜\"],\"identity\":\"比雨晴大七岁、台湾母系表哥，三位表哥之一\",\"traits\":[\"沉稳\",\"温柔\",\"会安慰孩子\",\"外向爱闹：翘班迎接妹妹、年夜游戏虚张声势\",\"照顾与越界并存：帮助搬家，却擅翻卧室私人物品\",\"旧友式亲情：陪雨晴重访小吃街和游戏厅\"],\"portrait\":\"\",\"fate\":null,\"status\":\"正文末段仍与家人来往，职业等详细结局未交代。\",\"statusRefs\":[\"c639\",\"c640\",\"c641\",\"c644\",\"c664\",\"x064\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"他在雨晴童年回忆中最稳定，曾安慰哭着表示想做女孩的她，并以玩笑般许诺回应将来嫁他的童言。多年未见使其面容模糊，雨晴后来把王海峰的照顾感比作表哥，也觉得购买龙年茅台的中年顾客有些像他，但没有上前确认。其父在大陆任职、偶尔返台只是回忆背景，不能据此把买酒人直接认成亲属。\",\"segmentFate\":\"只在回忆和相似感中出现，未与雨晴正式重逢。\",\"refs\":[\"c133\",\"c186\",\"c235\"],\"layer\":\"main\"},{\"scope\":\"c601—c665；x001—x079（全部补充篇）\",\"arc\":\"在台湾重逢时他自然接受多一个妹妹，以熟悉的打趣消除陌生。童年对食物的分享与成年后的聚会使他成为亲族欢乐的重要来源，但未经允许进屋和翻看护理物品伤害隐私，需要明确界限。婚礼、新婚回访等日常持续显示亲属关系没有因雨晴身份变化而断裂。\",\"segmentFate\":\"正文末段仍与家人来往，职业等详细结局未交代。\",\"refs\":[\"c635\",\"c639\",\"c640\",\"c641\",\"c644\",\"c664\",\"x064\"],\"layer\":\"main\"}],\"refs\":[\"c133\",\"c186\",\"c235\",\"c635\",\"c639\",\"c640\",\"c641\",\"c644\",\"c664\",\"x064\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-63\",\"name\":\"胡玉牛父亲\",\"aliases\":[\"胡父\"],\"identity\":\"乡村家传武术的继承者，盼儿子壮大家族\",\"traits\":[\"执着\",\"传统\",\"对武术复兴近乎偏执\",\"规训严\",\"重视训练与担当：以自己为榜样督促儿子\",\"把男子气概等同承重：家族振兴寄托独子\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段只在回忆与梦中，未获知阿牛身份，不能写成已杀子或已自杀。\",\"statusRefs\":[\"c134\",\"c169\",\"c184\",\"c191\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"他从儿子幼年训练其体魄，结合药浴补药，把柔弱孩子塑成强健劳动者，也把振兴家族的使命压在其肩上。阿牛曾想用家中伤药手艺做生意，父亲却拒绝；儿子后来认清家传套路难合现实，却仍不愿完全责怪父亲。父亲会怎样回应女性身份并未真实揭晓，阿牛噩梦将其想象成毁灭父子的极端暴力，反映恐惧而非既成事实。\",\"segmentFate\":\"本段只在回忆与梦中，未获知阿牛身份，不能写成已杀子或已自杀。\",\"refs\":[\"c134\",\"c169\",\"c184\",\"c191\"],\"layer\":\"main\"},{\"scope\":\"c601—c665；x001—x079（全部补充篇）\",\"arc\":\"父亲热爱孩子，也将家族未完成的事业交给他。木剑训练、体能和对男子气概的强调共同构成少年胡玉牛的价值世界。这个背景解释责任为何难以卸下，却不能直接推出后来每一个选择的单一心理原因。\",\"segmentFate\":\"前传与IF中在世；完整正文结局由前文决定。\",\"refs\":[\"x063\",\"x036\"],\"layer\":\"prequel\"}],\"refs\":[\"c134\",\"c169\",\"c184\",\"c191\",\"x063\",\"x036\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-64\",\"name\":\"王果\",\"aliases\":[],\"identity\":\"拥有莫空所租整幢楼的年轻房东，父母给其房产\",\"traits\":[\"随和\",\"直率\",\"年轻\"],\"portrait\":\"\",\"fate\":null,\"status\":\"房屋供电恢复，继续作为莫空房东。\",\"statusRefs\":[\"c135\",\"c136\",\"c138\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"莫空在六月停电后与他交谈，王果不喜欢被拘谨地叫房东，让其直接叫名字。他说明是区域电力抢修，又在恢复供电后主动告诉租客。其身家与莫空依靠稿费、旧电脑度日形成不刻意的对照：同样年轻却已有整幢房屋，仍没有明显摆架子。关于是否刚毕业、具体年龄文本只留外观和猜测，不能填成确定学历。\",\"segmentFate\":\"房屋供电恢复，继续作为莫空房东。\",\"refs\":[\"c135\",\"c136\",\"c138\"],\"layer\":\"main\"}],\"refs\":[\"c135\",\"c136\",\"c138\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-65\",\"name\":\"女仆长与别墅保镖\",\"aliases\":[],\"identity\":\"海边别墅的服务与安保人员，非同一人\",\"traits\":[\"守规矩\",\"警惕\",\"履职\",\"保留关怀\"],\"portrait\":\"\",\"fate\":null,\"status\":\"各自继续履职；没有安保冲突升级或雇佣变化。\",\"statusRefs\":[\"c137\",\"c202\",\"c224\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"保镖们对陌生人接近别墅保持警惕，曾拒莫空进入，也要求四位女孩离开；雯雯开口后才放行，仍观察客人，说明财富空间的森严边界。女仆长则在水水跑下楼时称其小诗、责备不能奔跑，见其摔倒又担心地扶起。前者的军旅背景只是思思猜测，后者没有给出全名，应分别保留职务而不臆造人物。\",\"segmentFate\":\"各自继续履职；没有安保冲突升级或雇佣变化。\",\"refs\":[\"c137\",\"c202\",\"c224\"],\"layer\":\"main\"}],\"refs\":[\"c137\",\"c202\",\"c224\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-66\",\"name\":\"莫空父亲与莫家族人\",\"aliases\":[],\"identity\":\"莫空的家族来源，父亲已病逝、族人参与继任场面\",\"traits\":[\"父亲信息有限\",\"族人重辈分权位\",\"部分长者刁难\"],\"portrait\":\"\",\"fate\":null,\"status\":\"父亲确已去世，莫空已辞族位；家族后续领导未知。\",\"statusRefs\":[\"c138\",\"c139\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"莫空父亲在族长继任前一个月病逝，莫空因而坐上祠堂祖传紫檀椅，面对族人质疑年轻、暗含角力。他触到被虫蛀的木头，从家族庄严外观感到内部腐朽，最后宣布不做族长。这一回忆解释他为何放开家族资产和地位，只靠小说及零工自由行走；族长后来由谁接任、本段没有交代。\",\"segmentFate\":\"父亲确已去世，莫空已辞族位；家族后续领导未知。\",\"refs\":[\"c138\",\"c139\"],\"layer\":\"main\"}],\"refs\":[\"c138\",\"c139\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-67\",\"name\":\"张阿姨与李叔叔\",\"aliases\":[\"无名面馆老板娘\",\"无名面馆老板\",\"李老板\"],\"identity\":\"曾收留初到小城市的雨晴的面馆夫妻\",\"traits\":[\"有恩于雨晴\",\"价值观传统\",\"生活朴实\"],\"portrait\":\"\",\"fate\":null,\"status\":\"继续经营面馆，本段未与雨晴再见面。\",\"statusRefs\":[\"c139\",\"c213\",\"c214\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"老板娘告诉莫空雨晴父母找来、她留纸离开，并认为孩子不懂事，离开前又告知出生性别；莫空仍为她可能有苦衷说话。后来雨晴走回面馆门外，看老板读报吃早餐、老板娘伏桌睡，仍深深感激当年收留，把两人视为亲近的人，却担心女装引来异样目光而没有进门。恩情和不能放心做自己的距离在这里同时存在。\",\"segmentFate\":\"继续经营面馆，本段未与雨晴再见面。\",\"refs\":[\"c139\",\"c213\",\"c214\"],\"layer\":\"main\"}],\"refs\":[\"c139\",\"c213\",\"c214\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-68\",\"name\":\"洛胖\",\"aliases\":[],\"identity\":\"游乐园老板的侄子，胖少年，只给出绰号\",\"traits\":[\"慷慨\",\"爱玩\",\"友好\",\"嘴上逞强\"],\"portrait\":\"\",\"fate\":null,\"status\":\"游园帮助完成，后续河堤只有雷与管出现；无独立结局。\",\"statusRefs\":[\"c146\",\"c147\",\"c148\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"他把昂贵限量水冰月娃娃放入叔叔经营的游乐园娃娃机，间接触发雨晴反复失败后的落泪。朋友怂恿他弥补，他抓出一堆其他玩偶却错过目标，再由雷哥接手；让女孩唱歌作为交换更像照顾她不愿白拿的自尊。听完歌他与同伴感慨离开，却没要电话号码，这个善意插曲也因此保留偶然性。\",\"segmentFate\":\"游园帮助完成，后续河堤只有雷与管出现；无独立结局。\",\"refs\":[\"c146\",\"c147\",\"c148\"],\"layer\":\"main\"}],\"refs\":[\"c146\",\"c147\",\"c148\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-69\",\"name\":\"管鹏\",\"aliases\":[\"管月月\",\"小圆脸少年\"],\"identity\":\"万剑雷、洛胖的朋友，即将升文澜高中\",\"traits\":[\"活跃\",\"会起哄\",\"讲义气\",\"默契\",\"调皮\",\"体贴支持：理解父亲对工作环境的不满，不反对离职。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"送饭后未再展开个人支线。\",\"statusRefs\":[\"c364\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"游乐园中他参与三少年的互损与帮助雨晴，河堤再会时推动害羞的万剑雷去搭话，自己到关键处也变拘谨。拿朋友钱包扇风误掏出看似暧昧的维修卡，促成三人共同发笑；风来时知道好友会扶雨晴，便马上追伞。万剑雷要走时他虽不懂原因仍认真配合，呈现普通少年友谊中自然的信任。\",\"segmentFate\":\"同雨晴认识但本段无联系方式或后续约定；与万剑雷仍结伴。\",\"refs\":[\"c146\",\"c147\",\"c148\",\"c215\",\"c216\",\"c217\",\"c218\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"他在短暂父子对话中把管医生从单纯救人的职业角色还原为有家庭和压力的人。父亲忙于救治，他送来饭食，并认可父亲对未来工作的选择。其作用主要是展示善良工作者也需要被照顾，以及正直并不意味着必须承受一切。\",\"segmentFate\":\"送饭后未再展开个人支线。\",\"refs\":[\"c364\"],\"layer\":\"main\"}],\"refs\":[\"c146\",\"c147\",\"c148\",\"c215\",\"c216\",\"c217\",\"c218\",\"c364\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-70\",\"name\":\"方莜莜生母、继母与父亲\",\"aliases\":[],\"identity\":\"莜莜的原生家庭，生母与继母应区分\",\"traits\":[\"信息有限\",\"情感关系疏远\"],\"portrait\":\"\",\"fate\":null,\"status\":\"生母去向不明且失联，父亲与继母仍在家；本段无关系修复。\",\"statusRefs\":[\"c150\",\"c177\",\"c223\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"雨晴高烧喊母亲时，莜莜说自己不想妈妈，随后透露亲生母亲早已离开，究竟离婚还是其他原因她也不知道，只知没有再联系。现在家中是继母，待她还好，但她对继母没有太深情分，与父亲亦有芥蒂。这解释她虽盼未来伴侣家庭接纳，谈及眼前父母却比雨晴疏离；不能把她淡淡的话误读为生母已死或继母虐待。\",\"segmentFate\":\"生母去向不明且失联，父亲与继母仍在家；本段无关系修复。\",\"refs\":[\"c150\",\"c177\",\"c223\"],\"layer\":\"main\"}],\"refs\":[\"c150\",\"c177\",\"c223\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-71\",\"name\":\"年轻收银员与死亡顾客\",\"aliases\":[],\"identity\":\"大润发冲突中的无名员工及中年男性顾客，需区分双方\",\"traits\":[\"顾客蛮横先施暴\",\"员工在激怒后过度反击\"],\"portrait\":\"\",\"fate\":null,\"status\":\"顾客已死亡；员工在押调查，判决未明，不能填死刑。\",\"statusRefs\":[\"c153\",\"c154\",\"c155\",\"c158\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"顾客要求把五十元换新钞，年轻员工无多余新钞并请其去服务台，遭顾客先以玻璃瓶攻击。员工随即反击造成致命后果，警方与急救到场，晚间新闻确认顾客死亡、员工被带走调查。雨晴第一次近距看见这样的暴力而恶心惊惧，超市暂停营业三天。后文员工父母聘律师与严判传言出现，但司法结果未在本段公布。\",\"segmentFate\":\"顾客已死亡；员工在押调查，判决未明，不能填死刑。\",\"refs\":[\"c153\",\"c154\",\"c155\",\"c158\"],\"layer\":\"main\"}],\"refs\":[\"c153\",\"c154\",\"c155\",\"c158\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-72\",\"name\":\"陈淑艳\",\"aliases\":[],\"identity\":\"三十岁左右、已婚有子的01部门女员工\",\"traits\":[\"直率\",\"粗口多\",\"能干\",\"护短\",\"好胜\",\"爱开玩笑\",\"豪爽护小：把轻活留苏、脏活自己做\",\"不畏冲突：反击刻薄防损女员工\",\"精明也有瑕疵：借梅避迟到责难，偷吃商品并鼓动苏\",\"嘴快爽朗：经常与王斗嘴。\",\"护同事：不满王病中被责骂，想替被促销员推活的雨晴出头。\",\"现实而重情：劝王考虑开店、挽留雨晴又提醒工作难找。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至c480仍在超市，目送同事将离职，个人去向未变。\",\"statusRefs\":[\"c402\",\"c410\",\"c430\",\"c465\",\"c476\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"她以大胆粗话和王海峰互损，初使雨晴不适，后来主动教退货、护着新人、让主管替她带吃的，显示泼辣之外的实际关怀。她办文书较熟、与主管关系近，遭翁锡芽和徐嫂背后贬斥，自己也会用攻击性话语反击。半年总结把功劳写得夸张又拉雨晴代抄，芥末糖报复玩笑则表现孩子气；这些矛盾让她既不是单纯坏同事也不是完美姐姐。\",\"segmentFate\":\"继续上班、照顾家庭，与王海峰亲近仍未被证实是恋情。\",\"refs\":[\"c164\",\"c165\",\"c166\",\"c181\",\"c182\",\"c186\",\"c234\",\"c235\"],\"layer\":\"main\"},{\"scope\":\"正文 c241—c360\",\"arc\":\"她在苏的劳动生活中既像热心姐姐，也让苏看到好人并不等于每件事都正当。与翁和防损员工的对立造成盘点摩擦，却会实打实帮助苏扫码、搬货和应对官威。后来暗仓邀偷吃巧克力，认为低薪可补偿小便宜，苏因此质疑是否终会被社会同化。叙述补出她厌恶防损风气主动转岗，不能因此把她的所有行为合理化。\",\"segmentFate\":\"截至本段仍在超市工作，与苏友善，偷吃没有被查处的情节。\",\"refs\":[\"c273\",\"c298\",\"c299\",\"c303\",\"c327\",\"c352\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"她兼具职场粗粝语言与真切善意，既能让雨晴在工作里放松，也会因过度积极替人出头令害怕冲突的雨晴尴尬。王决定走时她劝他不要再承受相同压迫，雨晴想辞职时又愿意罩着她。与王的亲近是同事情谊，本段未写成爱情。\",\"segmentFate\":\"截至c480仍在超市，目送同事将离职，个人去向未变。\",\"refs\":[\"c402\",\"c410\",\"c430\",\"c465\",\"c476\"],\"layer\":\"main\"}],\"refs\":[\"c164\",\"c165\",\"c166\",\"c181\",\"c182\",\"c186\",\"c234\",\"c235\",\"c273\",\"c298\",\"c299\",\"c303\",\"c327\",\"c352\",\"c402\",\"c410\",\"c430\",\"c465\",\"c476\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-73\",\"name\":\"果冻业务员\",\"aliases\":[],\"identity\":\"向王海峰推介促销的供应商业务员\",\"traits\":[\"会经营关系\",\"逐利\",\"善于私谈\"],\"portrait\":\"\",\"fate\":null,\"status\":\"促销分成约定达成，实际结算未写。\",\"statusRefs\":[\"c166\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"业务员为果冻促销与主管接洽，先送烟未获接受，转而以介绍女友等话头引王海峰私谈，最终商定促销堆按销量给予分成。表面轻松聊天背后是上架和销售位置的利益往来，与雨晴学习退货文书同章并列，揭开普通超市工作中她尚不熟悉的隐性规则。其姓名、公司及后续执行收入没有交代。\",\"segmentFate\":\"促销分成约定达成，实际结算未写。\",\"refs\":[\"c166\"],\"layer\":\"main\"}],\"refs\":[\"c166\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-74\",\"name\":\"林夕晨母亲与三位姐姐\",\"aliases\":[],\"identity\":\"夕晨的农村原生家庭女性\",\"traits\":[\"受传统性别结构限制\",\"安慰孩子\",\"也会合理化父权\"],\"portrait\":\"\",\"fate\":null,\"status\":\"母亲与姐姐仍只在回忆；对夕晨离家后的生活不知情或未见说明。\",\"statusRefs\":[\"c178\",\"c228\",\"c239\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"三位姐姐在夕晨挨打后安慰她，却把父亲暴力解释为在乎，有人说若是女孩就不会这样挨打，成为她身份愿望的一个叙事触点。后来回忆又说明大姐想进城被父亲斥责，旋即嫁附近村人，其余姐姐最多去小县城工厂工作。母亲维持农务，也教夕晨鬼伤不了人，使她面对鬼故事镇定。她们的保护与自身处境都不完整，不能据此推定接受夕晨当下身份。\",\"segmentFate\":\"母亲与姐姐仍只在回忆；对夕晨离家后的生活不知情或未见说明。\",\"refs\":[\"c178\",\"c228\",\"c239\"],\"layer\":\"main\"}],\"refs\":[\"c178\",\"c228\",\"c239\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-75\",\"name\":\"林夕晨父亲\",\"aliases\":[\"林父\",\"夕晨父亲\"],\"identity\":\"农村父亲，三女之后终于有独子夕晨\",\"traits\":[\"重男轻女\",\"劳作辛苦\",\"对子有强烈期待\",\"有虐待行为\",\"叙述中亦显偏宠\",\"重男轻女：姐姐较早离学嫁人，夕晨受更多教育和偏爱。\",\"对被当作儿子的幼子也有亲情：曾留生日发糕与日常记忆。\",\"疾病使未归的孩子承担经济与情感压力。\",\"强烈重男轻女：只供唯一儿子求学，逼女儿辍学、早嫁。\",\"固执且控制：饮酒拒医、重病还下田，拒女婿帮助。\",\"曾真心疼林，但疼爱附有男性继嗣条件。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"c582被林杀害，未接受所计划的救父手术。\",\"statusRefs\":[\"c522\",\"c558\",\"c566\",\"c577\",\"c581\",\"c582\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"c178写他因成绩差公开羞辱殴打夕晨，使她寻求变成女孩和逃离，甚至在心底产生杀父念头；c239又写他农闲进城做苦工供学、珍惜孩子奖学金买的鞋、支持其创业离家，并只对独子温柔。两段存在衔接张力，须同时保留。名字本想取希望的早晨却写成夕晨，浓縮儿子承载父望的意义；辛劳与真实父爱不能抵消虐待和对子女性别的不平等。\",\"segmentFate\":\"仍在乡村，未知夕晨性别生活；未被伤害，父女未重逢。\",\"refs\":[\"c178\",\"c239\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"家书让夕晨得知他有肿瘤需赴城治疗，她回顾受到的偏爱与姐姐们的牺牲，约三年未归，怕身体变化带来拒绝。她仍汇五千元并为进一步治疗费发愁。检查结果令她设想终于能向父亲解释自己，但截至本段还没有实际重聚或得知他的反应。\",\"segmentFate\":\"截至c480患病后续治疗与生死未交代；夕晨打算回家，尚未见面。\",\"refs\":[\"c409\",\"c475\",\"c476\"],\"layer\":\"main\"},{\"scope\":\"正文 c481—c600\",\"arc\":\"林回忆其粗糙手掌、带车远游和求学奔波，现实却见他老病、不断消耗家中资助。他拒绝把林的身体检查和认同当回事，以殴打禁闭逼迫服从，令多年牺牲的意义崩塌。林在精神崩溃中将其杀害，家庭暴力与后果不可互相正当化。\",\"segmentFate\":\"c582被林杀害，未接受所计划的救父手术。\",\"refs\":[\"c522\",\"c558\",\"c566\",\"c577\",\"c581\",\"c582\"],\"layer\":\"main\"}],\"refs\":[\"c178\",\"c239\",\"c409\",\"c475\",\"c476\",\"c522\",\"c558\",\"c566\",\"c577\",\"c581\",\"c582\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-76\",\"name\":\"徐嫂\",\"aliases\":[],\"identity\":\"01部门和气外貌的中年员工，有即将升高三的儿子\",\"traits\":[\"外和内有立场\",\"关心孩子\",\"在意礼节\",\"从众议论\",\"分工依赖：让苏帮搬整理较重货箱\",\"说话直接：见陈偏袒苏便调侃没帮自己\",\"愿意为受不公对待的同事分担劳动。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"仍在超市，个人终局未交代。\",\"statusRefs\":[\"c402\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"她先以胖而和气的形象出现，谈儿子成绩普通、爱游戏动物，也能接受孩子按兴趣发展，带出另一种家长态度。但同场面对陈淑艳的粗话与和主管的亲近，她和翁锡芽共同表示厌恶，返程要求雨晴附和，并把退货文书托给新人。温和表面和现实的人际施压并存，与夏伯伯的无计较形成差别。\",\"segmentFate\":\"继续在超市工作；儿子升学尚未发生，不给出高考结果。\",\"refs\":[\"c181\",\"c182\"],\"layer\":\"main\"},{\"scope\":\"正文 c241—c360\",\"arc\":\"在大规模来货时与苏搭班，平常琐事使苏付出大量体力，也显示她少言、顺从的工作策略。后期与王、陈拌嘴场景中，她用一句为何没帮自己揭示照护并不平均。其人未被写成主要欺凌者，无须把日常使唤夸大为敌对关系。\",\"segmentFate\":\"截至本段仍在超市工作。\",\"refs\":[\"c253\",\"c327\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"她在王海峰病中返岗的章节与其他同事共同表达不满，参与部门默契互助。没有单独发展为主要支线，但她与其他普通员工的存在，让王的离职不是一个完全孤立的故事，也显出基层同僚对好主管的依赖。\",\"segmentFate\":\"仍在超市，个人终局未交代。\",\"refs\":[\"c402\"],\"layer\":\"main\"}],\"refs\":[\"c181\",\"c182\",\"c253\",\"c327\",\"c402\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-77\",\"name\":\"翁锡芽\",\"aliases\":[\"员工指导\"],\"identity\":\"01部门员工指导，年龄略长于陈淑艳\",\"traits\":[\"讲礼数\",\"在意职位\",\"不满偏爱\",\"背后议论\",\"按事务执行：派取软标、扫码盘点、调价\",\"也有体谅：替苏填表、劝不要为防损生气\",\"与陈不和：相互不满影响工作气氛\",\"熟悉管理流程，工作上长期协助王。\",\"务实趋避压力：不愿正式接任主管，只答应暂代。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"王离职后拟暂代，长期主管仍待超市另派。\",\"statusRefs\":[\"c402\",\"c465\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"她在集体午餐中出现，与陈淑艳为人作风形成鲜明差别。陈与主管亲密又说粗话，使翁锡芽和徐嫂表露反感，返程还拉新人雨晴认同她们的评价。她身处员工指导职位，本有管理身份，却面对主管更亲近陈的局面。此人物主要承载基层女性之间的权力、礼貌和嫉妒，不应只凭陈或雨晴视角断定她全然恶意。\",\"segmentFate\":\"仍在01部门，相关人际冲突未有裁决或调职结局。\",\"refs\":[\"c181\",\"c182\",\"c186\"],\"layer\":\"main\"},{\"scope\":\"正文 c241—c360\",\"arc\":\"她与王海峰的带班方式不同，更看重当日任务完成，会在没人手时调苏下楼或安排额外工作。原文并非只把她写成恶人，她会替苏整理表格与安慰受刁难的情绪。与陈的长期摩擦以及要求昏暗仓库当天盘完，使苏体会层级调配对具体劳动的压力；她和刻薄防损女员工不是同一个人。\",\"segmentFate\":\"截至本段仍任员工指导，主管休假时持续调度，未见离职或处罚。\",\"refs\":[\"c252\",\"c254\",\"c298\",\"c299\",\"c352\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"她对王海峰离职很不舍，既有多年共事的感情，也知道此前难题和责骂常由王承担。主管位置权力有限、责任却重，让她不愿长期担任。这种兼有情谊和自利的反应，帮助揭示超市管理层与基层之间的负担分配。\",\"segmentFate\":\"王离职后拟暂代，长期主管仍待超市另派。\",\"refs\":[\"c402\",\"c465\"],\"layer\":\"main\"}],\"refs\":[\"c181\",\"c182\",\"c186\",\"c252\",\"c254\",\"c298\",\"c299\",\"c352\",\"c402\",\"c465\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-78\",\"name\":\"后仓主管与经理\",\"aliases\":[\"大哥\",\"老大\"],\"identity\":\"阿牛后仓工作中的两级负责人，称呼须区分\",\"traits\":[\"以劳动组织为重\",\"认可阿牛体力\"],\"portrait\":\"\",\"fate\":null,\"status\":\"后仓日常继续；没有明确升降职或其他结果。\",\"statusRefs\":[\"c183\",\"c205\",\"c236\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"后仓员工把主管称大哥、经理称老大，叙述借这些称谓描绘比较男性化、讲兄弟口吻的劳动团队。搬货繁重时众人希望加餐和奖金，负责人安排工作、表达认可，阿牛却因身体改变恢复变慢而暗自焦虑。参加大夜班通常需熟悉半年商品的规则亦在这一工作线提出，后文阿牛实际参加而未解释年资衔接。\",\"segmentFate\":\"后仓日常继续；没有明确升降职或其他结果。\",\"refs\":[\"c183\",\"c205\",\"c236\"],\"layer\":\"main\"}],\"refs\":[\"c183\",\"c205\",\"c236\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-79\",\"name\":\"阿春\",\"aliases\":[],\"identity\":\"后仓留胡子的小伙，同阿牛搬货\",\"traits\":[\"会帮忙\",\"有兄弟式玩笑\",\"体力有限\"],\"portrait\":\"\",\"fate\":null,\"status\":\"仍为后仓同事，无独立结局。\",\"statusRefs\":[\"c183\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"在阿牛长时间搬米、体力比过去差却仍被众人当强者的场景中，阿春接手部分活计，很快也疲惫。其他同事拿他和老牛比较，用玩笑夸阿牛厉害。这段既证明阿牛仍可得到工作伙伴的认可，也显示这种认可全围绕他最想摆脱的阳刚力量，旁人未能察觉同一句夸奖对他的含义已经改变。\",\"segmentFate\":\"仍为后仓同事，无独立结局。\",\"refs\":[\"c183\"],\"layer\":\"main\"}],\"refs\":[\"c183\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-80\",\"name\":\"中年购酒客\",\"aliases\":[],\"identity\":\"购买龙年茅台的匿名顾客\",\"traits\":[\"衣着体面\",\"客气\",\"重礼物档次\",\"仔细验货\"],\"portrait\":\"\",\"fate\":null,\"status\":\"购酒完成并离开，身份仍未查明。\",\"statusRefs\":[\"c185\",\"c186\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"他在晚班酒柜寻找昂贵礼酒，嫌较普通的酒不够档次，王海峰遂取出陈放多年的龙年茅台。他借放大镜看细节、刷卡付款，促成稀有商品终于售出，也为主管带来奖金。雨晴觉得其像台湾大表哥但无法确认，同事猜官员或商人亦没有证据。以匿名顾客保留，能防止将气质、价格和相貌推断当成确切身份。\",\"segmentFate\":\"购酒完成并离开，身份仍未查明。\",\"refs\":[\"c185\",\"c186\"],\"layer\":\"main\"}],\"refs\":[\"c185\",\"c186\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-81\",\"name\":\"富商与中间人\",\"aliases\":[\"富客\"],\"identity\":\"思思旧创伤的施害者与引介者，未具名\",\"traits\":[\"利用金钱诱惑\",\"控制\",\"侵犯\",\"把人当物品\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段没有施害者受惩、案发处理或思思当年脱身经过的完整交代。\",\"statusRefs\":[\"c190\",\"c211\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"思思深夜梦魇重现其急需钱时受中间人诱导、以高额报酬赴别墅的经历。富商起初以优厚条件掩饰目的，随后用药物与囚禁控制、实施性侵虐待，拒绝她离开；c211另段叙述确认她曾受富商包养控制及伤害。这是受害者记忆对当下依恋的解释，不能因开始收钱便当作所有后续行为得到同意。\",\"segmentFate\":\"本段没有施害者受惩、案发处理或思思当年脱身经过的完整交代。\",\"refs\":[\"c190\",\"c211\"],\"layer\":\"main\"}],\"refs\":[\"c190\",\"c211\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-82\",\"name\":\"养熊猎人\",\"aliases\":[],\"identity\":\"住在海边森林附近村庄的猎人，莫空朋友\",\"traits\":[\"本段未直接展示性格\",\"会养熊\"],\"portrait\":\"\",\"fate\":null,\"status\":\"已回村，未与四人直接相识。\",\"statusRefs\":[\"c194\",\"c198\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"四人误以为野熊攻击而惊慌跑散，次日莫空说明那只熊其实是猎人朋友自小养大、随他出来狩猎的动物。主人尚未来得及喊停，女孩们已跑得不见影；等重聚时他也已经离开。此解释改变事件性质，却没有取消跑散和昏迷造成的真实危险。文本未给姓名，也未写他与四人道歉或见面的过程。\",\"segmentFate\":\"已回村，未与四人直接相识。\",\"refs\":[\"c194\",\"c198\"],\"layer\":\"main\"}],\"refs\":[\"c194\",\"c198\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-83\",\"name\":\"水水\",\"aliases\":[\"小诗\"],\"identity\":\"雯雯的小女仆，本段有两种昵称\",\"traits\":[\"活泼\",\"调皮\",\"亲近主人\",\"愿意照料\",\"忠心依恋：不肯先去睡，坚持照料发热大小姐\",\"体贴细致：在主人脆弱时陪伴并接受嘱托\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段仍服务海边别墅，接替机制和双名来历未由本段说明。\",\"statusRefs\":[\"c276\",\"c277\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"她先为来客端茶，被大小姐拉到身边一起坐，显示关系超越严格主仆礼节。台风天她替雯雯揉肩，乐观畅想成为大美女，却听不懂对方关于不同阶段灵魂的担忧；仍答应日后好好照顾她。学会叫花鸡后兴冲冲去做，跑下楼被女仆长责备并摔倒，这种稚气与雯雯所说一年后成熟的大姐姐形成鲜明时间反差。\",\"segmentFate\":\"仍为活泼小女仆，已接受照顾未来雯雯的嘱托；预言未在本段兑现。\",\"refs\":[\"c202\",\"c224\"],\"layer\":\"main\"},{\"scope\":\"正文 c241—c360\",\"arc\":\"她参与大小姐海边生活，面对雯雯突兀的告别和未来变稚嫩的说法不完全理解，仍努力承担照护。名字从主仆礼貌到直接唤雯雯，是大小姐要求更亲近的一步。她与落姨、厨师们共同应对发烧，未来是否履行照护接替者的承诺本段未完整展示。不可仅凭称呼和相貌将她与神秘失语少女合并。\",\"segmentFate\":\"截至本段仍服务海边别墅，接替机制和双名来历未由本段说明。\",\"refs\":[\"c276\",\"c277\"],\"layer\":\"main\"}],\"refs\":[\"c202\",\"c224\",\"c276\",\"c277\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-84\",\"name\":\"飙车男子与同伴\",\"aliases\":[],\"identity\":\"司机称以市长之子为首的小城富家飙车群体，具体姓名不明\",\"traits\":[\"炫耀\",\"蔑视风险\",\"仗势\",\"迁怒弱者\"],\"portrait\":\"\",\"fate\":null,\"status\":\"车队仍离去，未见事故追责；领头男子受小挫败但未改行径。\",\"statusRefs\":[\"c204\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"他们夜间高速行驶、转向戏弄公交，迫使司机两度急刹并最终减速避让。司机称领头者是市长儿子、可凭关系压事，这一身世信息主要来自旁观者。领先奔驰里的年轻男子炫耀赢局并乱扔香烟，被匿名胡子路人踢回后烫伤，找不到对方便向女伴泄愤。情节呈现权力保护下的任性，与主人公自我规训构成对照。\",\"segmentFate\":\"车队仍离去，未见事故追责；领头男子受小挫败但未改行径。\",\"refs\":[\"c204\"],\"layer\":\"main\"}],\"refs\":[\"c204\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-85\",\"name\":\"孔雀\",\"aliases\":[\"孔医生\",\"孔雀医生\",\"慈善基金会联系人\"],\"identity\":\"星辰诊所女医生，出生女性身份由她自己明确\",\"traits\":[\"慵懒\",\"宿醉困倦\",\"识人敏锐\",\"口吻直白\",\"逐利\",\"提供实际帮助：接诊同类、实施莜莜手术并给予费用优惠。\",\"对创伤不敏感：术后轻率展示组织，令天语遥强烈不适。\",\"边界松散：把阿牛用过的物品交给谎称收藏的天语遥，助成隐私证据链。\",\"对社群有帮助：群友回忆资助贫困者与免费手术。\",\"行为和资质存在严重问题：医疗边界不当、为未成年患者做不可逆手术。\"],\"portrait\":\"\",\"fate\":{\"name\":\"孔雀\",\"label\":\"被捕并判刑（书内情节）\",\"text\":\"星辰诊所相关人物，参与提供药物与手术。患者事件后被捕，后文叙述被判十年并承担赔偿。\",\"note\":\"只作原著案件结果，不把群聊对患者动机的猜测、书内法律解释当现实法理。\",\"refs\":[\"c205\",\"c398\",\"c576\",\"c583\"]},\"status\":\"c583明确被判十年并赔尽积蓄；未写刑满后状态。\",\"statusRefs\":[\"c556\",\"c557\",\"c576\",\"c583\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"阿牛依地址来就诊时，她宿醉、睡眼惺忪却能猜中他对自己和治疗的疑虑，表示不会因外貌嘲笑他。她为其注射后很快收钱继续休息，次日甚至记不清已过几天；询问进一步治疗时又推介昂贵药品和手术，并强调自己有经验、可给折扣。这个人物提供通路，也让阿牛的迫切和经济压力暴露在不充分保障的环境中。\",\"segmentFate\":\"阿牛已接受一次注射，后续昂贵药与手术未成交；医生资质与所述疗效未在本段核实。\",\"refs\":[\"c205\",\"c206\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"他把医疗、公益、同类社群联在一起，莜莜通过群里联系人才确认其基金会身份。手术在小说中成功，但他对他人创伤和物品用途缺少敏感，天语遥借此取得证据。应将他的治疗与药物话语仅作小说情节记录，不转作临床规范或建议。\",\"segmentFate\":\"截至c480仍经营诊所与基金会；莜莜手术已完成，阿牛证据从其诊所被取得。\",\"refs\":[\"c379\",\"c394\",\"c398\",\"c399\",\"c411\"],\"layer\":\"main\"},{\"scope\":\"正文 c481—c600\",\"arc\":\"她为苏实施自愿要求的去势手术，术前讲起另一位后悔患者，却未因此解决自身执业与同意程序问题。春节前因小云案被捕，群体争论与声援一时集中。后文明确十年刑期并赔尽积蓄，社群很快转回各自生活。不能以受助者感激或旁观者责骂取代对案件事实的区分。\",\"segmentFate\":\"c583明确被判十年并赔尽积蓄；未写刑满后状态。\",\"refs\":[\"c556\",\"c557\",\"c576\",\"c583\"],\"layer\":\"main\"}],\"refs\":[\"c205\",\"c206\",\"c379\",\"c394\",\"c398\",\"c399\",\"c411\",\"c556\",\"c557\",\"c576\",\"c583\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-86\",\"name\":\"拉面馆老板与斗殴双方\",\"aliases\":[],\"identity\":\"挂清真标识却供猪肉面的店主及两派争执者，虚构冲突角色\",\"traits\":[\"店主有备而来\",\"一方愤怒冲动\",\"具体动机未完全揭示\"],\"portrait\":\"\",\"fate\":null,\"status\":\"斗殴发生，警方、责任、损伤和店铺后续都未交代。\",\"statusRefs\":[\"c238\",\"c239\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"夕晨点牛肉面却收到猪肉面，先注意标识不符但未追究，随后年轻壮汉群体以宗教受辱来砸门，店外中年人一方像有准备，争论逐步演为扭打。她继续吃饭，付款后穿过自动让路的人群离开。文本含群体化偏见，阅读展示仅记录本次店内事件，不将其当成现实宗教、地域或族群的通性，也不补造幕后组织。\",\"segmentFate\":\"斗殴发生，警方、责任、损伤和店铺后续都未交代。\",\"refs\":[\"c238\",\"c239\"],\"layer\":\"main\"}],\"refs\":[\"c238\",\"c239\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-87\",\"name\":\"刷墙工\",\"aliases\":[],\"identity\":\"灾后修复缝纫厂围墙的匿名工人\",\"traits\":[\"辛勤\",\"悠闲自处\",\"有耐心\"],\"portrait\":\"\",\"fate\":null,\"status\":\"继续刷墙，无姓名和其他结局。\",\"statusRefs\":[\"c239\"],\"segments\":[{\"scope\":\"正文 c121—c240\",\"arc\":\"他在烈日下刷墙，穿布满白漆点的旧衣，喝大油壶里的凉水、抽廉价烟、哼歌，再继续工作。夕晨注意到这种艰辛中仍有自在的劳动，停在树荫中观看，并将其背影与苦工供学的父亲重合。工人没有同她说话，却触发本段最深入的家庭回忆和落泪，说明路人的普通生活也能成为人物内心转折的媒介。\",\"segmentFate\":\"继续刷墙，无姓名和其他结局。\",\"refs\":[\"c239\"],\"layer\":\"main\"}],\"refs\":[\"c239\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-88\",\"name\":\"方莜莜公司总经理与老板\",\"aliases\":[],\"identity\":\"雇用、信任并栽培方的公司负责人；本段称老板/总经理是否具体同一需全书归名。\",\"traits\":[\"识才：让方兼开发、外贸合同和带人工作\",\"工作要求多：项目赶工令方经常加班\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段尚未展示收到报告，方仍在岗。\",\"statusRefs\":[\"c241\",\"c331\",\"c346\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"作为方职业道路的支持者，他使辞职具有真实代价：方并非因被欺压才想走，而是需要身体手术的恢复时间。她担心辜负培养，又预想总经理会挽留，因此编写赴父母城市的辞职理由。实际谈话、审批和离职在本段未发生，不能提前写为准假或反对。\",\"segmentFate\":\"截至本段尚未展示收到报告，方仍在岗。\",\"refs\":[\"c241\",\"c331\",\"c346\"],\"layer\":\"main\"}],\"refs\":[\"c241\",\"c331\",\"c346\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-89\",\"name\":\"送餐女孩\",\"aliases\":[],\"identity\":\"给方所在办公室送饭的年轻女孩。\",\"traits\":[\"因失误慌张：弄翻汤饭后担心赔偿\",\"受到宽容：方没有借事故责难\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段事故处理后离开，无长期结局。\",\"statusRefs\":[\"c241\",\"c242\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"一次普通送餐事故使方不得不脱换裤子并请林送衣，把平常隐蔽的身体变化推到同事视野。女孩自身没有恶意，也未主动揭秘密；她的作用是触发职场身份焦虑，同时展示方对服务劳动者的温和。后续职业与生活未写。\",\"segmentFate\":\"本段事故处理后离开，无长期结局。\",\"refs\":[\"c241\",\"c242\"],\"layer\":\"main\"}],\"refs\":[\"c241\",\"c242\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-90\",\"name\":\"梦中男孩与梦中女孩\",\"aliases\":[],\"identity\":\"反复公园梦中的人物，苏有时与男孩身份交换。\",\"traits\":[\"哀伤困住：男孩悼念朋友、寻找公园出口\",\"身份不稳：苏变成他时思维也幼化\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段仍为梦境线索，身份和被悼朋友未解。\",\"statusRefs\":[\"c246\",\"c247\",\"c259\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"c246男孩哀悼未名朋友，无字墓后在血雨里露魁梧身影。c259他一度不在秋千，苏坐上后变幼小男孩，面对熟悉女孩重复寻找出路的话，再醒仍忘记。梦境可映射自我与未来，但单凭本段不能认定男孩是过去苏、已死人物或掌管时间者；女孩也不可直接与神秘现实角色归一。\",\"segmentFate\":\"截至本段仍为梦境线索，身份和被悼朋友未解。\",\"refs\":[\"c246\",\"c247\",\"c259\"],\"layer\":\"main\"}],\"refs\":[\"c246\",\"c247\",\"c259\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-91\",\"name\":\"神秘狐耳少女\",\"aliases\":[\"九尾狐少女\"],\"identity\":\"在柳失恋夜现实出现的神秘少女；与其他梦中/幻见人物是否同一未证实。\",\"traits\":[\"主动介入：为睡着柳披大衣\",\"超自然外观：狐耳九尾被叙述展示\"],\"portrait\":\"\",\"fate\":null,\"status\":\"现实披衣后离开，身份目的未解。\",\"statusRefs\":[\"c247\",\"c301\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"她没有与胡或柳对话，却用一件外套改变柳对胡心意的判断，从而间接推动爱情支线。c301天危机梦中也出现狐耳少女，引她离开黑暗；c271天台仙女、c272失语少女与狐狸木卡形成近似意象，但本段不证明全部同人或同一动机。只记录出现层级，避免把相似线索草率合并。\",\"segmentFate\":\"现实披衣后离开，身份目的未解。\",\"refs\":[\"c247\",\"c301\"],\"layer\":\"main\"}],\"refs\":[\"c247\",\"c301\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-92\",\"name\":\"天语遥旧部及反对换首者\",\"aliases\":[],\"identity\":\"原侵害柳团伙及其帮派成员，天缺席后由元老暂管，后来有人主张换首。\",\"traits\":[\"对外可侵害他人、对内重义气的矛盾\",\"部分真心愿接纳天，另一些因长期缺位想换头目\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至c360天归来但帮派危机未正式处理，追踪胡开始，复仇未实行。\",\"statusRefs\":[\"c249\",\"c300\",\"c348\",\"c354\",\"c359\",\"c360\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"他们曾一起围困柳而被胡击退，随后探病误把话题当慰藉，反而加重天痛苦。得知其身体受创后并未统一疏离，多名旧部想为她报复；但长期不回使组织涣散，公共区逐渐由黄占主导，也出现换头领声音。二十余人在c360迎接天，不能把这个热情群体免除其暴力责任。\",\"segmentFate\":\"截至c360天归来但帮派危机未正式处理，追踪胡开始，复仇未实行。\",\"refs\":[\"c248\",\"c249\",\"c300\",\"c348\",\"c354\",\"c359\",\"c360\"],\"layer\":\"main\"}],\"refs\":[\"c248\",\"c249\",\"c300\",\"c348\",\"c354\",\"c359\",\"c360\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-93\",\"name\":\"柳韵父母与奶奶\",\"aliases\":[],\"identity\":\"柳的家庭成员；父母在小城市工作，奶奶误读名字形成音音小名。\",\"traits\":[\"父亲亲近啰嗦：会抢女儿零食\",\"父母筹划生计：拟开电脑配件店、待女上大学后赴杭州\",\"奶奶亲缘称呼：把韵念成音形成小名\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段筹电脑配件生意、计划未来杭州，是否知胡柳恋情未明。\",\"statusRefs\":[\"c249\",\"c318\",\"c349\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"柳的家庭在她口中比胡家更轻松，父亲会像孩子般一起吃零食，她对父母晚归有自己的应对。父母筹店导致她多夜独处，间接为与胡共餐和过夜带来空间；这些行为未说明家长知道或同意恋爱。祖母命名只是短暂回忆，老家和外婆家都不在浙江，但具体省份未给。\",\"segmentFate\":\"截至本段筹电脑配件生意、计划未来杭州，是否知胡柳恋情未明。\",\"refs\":[\"c249\",\"c318\",\"c349\"],\"layer\":\"main\"}],\"refs\":[\"c249\",\"c318\",\"c349\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-94\",\"name\":\"日常商贩及偶遇者\",\"aliases\":[],\"identity\":\"白熊玩具店主、狮子编织摊主、染色鸡商、模型枪商、邮局员工、雨晶店主、游艺及宠物服装店主、沙县店主、校保安等。\",\"traits\":[\"以具体交易连起物件：信物、宠物、礼物、手作材料\",\"不同态度构成日常：热情推销、谨慎核件、随口关心均有\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段各交易已完成或争执已结束，个人去向未说明。\",\"statusRefs\":[\"c310\",\"c313\",\"c318\",\"c321\",\"c322\",\"c331\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"这些没有名字的角色承担事件接点，应在相关事件和物品页面保留：有人让温柔馈赠实现，有人贩售生命脆弱的宠物，有人核查方领取蛋糕或张寄模型枪。校保安把柳当妹妹促使胡临时撒谎，沙县刻薄女客则使柳与胡的应对差异显露。不要把所有商贩统一评为善或恶，也不为单次过场者编造结局。\",\"segmentFate\":\"本段各交易已完成或争执已结束，个人去向未说明。\",\"refs\":[\"c250\",\"c273\",\"c305\",\"c310\",\"c313\",\"c318\",\"c321\",\"c322\",\"c331\"],\"layer\":\"main\"}],\"refs\":[\"c250\",\"c273\",\"c305\",\"c310\",\"c313\",\"c318\",\"c321\",\"c322\",\"c331\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-95\",\"name\":\"苏雨晴父母\",\"aliases\":[\"圆圆（母亲）\"],\"identity\":\"苏离家前的父母，家庭原本优裕；母亲在c303真实对白被父称圆圆。\",\"traits\":[\"关心持续：童年身体照护、探看工作中的孩子\",\"父亲态度变化：决定不强带走而支持选择\",\"母亲主动准备接纳：提议送适合女孩的礼物\",\"早年教育与安排偏重学习及实用，给雨晴留下错过童年的感受。\",\"记忆中也有细心照护，雨晴反复担心母亲怕冷、父亲疲劳。\",\"对国家与移民看法与年少雨晴不同，构成家庭旧日对话。\",\"母亲思念且重照护，多次要接回女儿。\",\"父亲观念已转向支持身份，但仍坚持三年历练期限。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至c600尚未与苏现实团聚，态度变化她仍不完全知道。\",\"statusRefs\":[\"c548\",\"c558\",\"c573\",\"c574\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"在苏的记忆和梦中，父母代表童年安全，也代表她不敢面对的期待。她因离家、身份变化而认为可能被放弃，整个开学和中秋仍在自责。c303却以独立真实对白给出读者掌握而苏未知的信息：二人实际来过，父亲决定站在孩子一边帮助、等她愿意回家，母亲也接受为女孩准备礼物。梦中团聚的具体言词未现实发生，真正和解仍待见面。\",\"segmentFate\":\"截至本段已私下转向尊重支持，但苏未知，现实家庭团圆未发生。\",\"refs\":[\"c251\",\"c268\",\"c303\",\"c340\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"雨晴既坚持自我又思念父母，常把未寻找自己解释成被放弃。神秘包裹含童年口味、合身衣物与昂贵娃娃，使她强烈希望父母在默默接纳，但没有证据确认寄件者。本段对离家到底是被赶或主动离开的叙述带情绪与前后差异，不宜据单句裁定双亲态度。\",\"segmentFate\":\"截至c480未在现实重聚，未明确确认接纳，也未确认神秘包裹是二人寄出。\",\"refs\":[\"c395\",\"c396\",\"c426\",\"c430\",\"c451\",\"c452\"],\"layer\":\"main\"},{\"scope\":\"正文 c481—c600\",\"arc\":\"两人早知苏的工作和住所，请大舅照看，并非完全抛弃。父亲在2005年末表示若苏坚持，将提供专业手术帮助，却坚持到2006年三年期限才接回。重伤消息再次引发争论，母亲心疼，父亲仍不愿暴露已知情。家族婚姻旧史与苏早产体弱的抚养辛苦补足了他们复杂的爱与控制。\",\"segmentFate\":\"截至c600尚未与苏现实团聚，态度变化她仍不完全知道。\",\"refs\":[\"c548\",\"c558\",\"c573\",\"c574\"],\"layer\":\"main\"}],\"refs\":[\"c251\",\"c268\",\"c303\",\"c340\",\"c395\",\"c396\",\"c426\",\"c430\",\"c451\",\"c452\",\"c548\",\"c558\",\"c573\",\"c574\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-96\",\"name\":\"女部门经理\",\"aliases\":[],\"identity\":\"王海峰直接上级、超市女性部门经理。\",\"traits\":[\"官威与推责：把轮休说偷懒，错录酒价仍归咎王\",\"与基层距离大：未充分考虑搬货实际劳动\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段未见被处罚或态度转变。\",\"statusRefs\":[\"c252\",\"c253\",\"c255\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"她在大量货物与错价风波中重复质疑王，要求主管为数据部错误承担损失，使苏看见努力并不保证被公平对待。她在红酒索赔现场也出现，但最终解决靠王的人脉协调。姓名与其他家庭关系本段未给，不能与梅经理或刻薄防损女员工合并。\",\"segmentFate\":\"截至本段未见被处罚或态度转变。\",\"refs\":[\"c252\",\"c253\",\"c255\"],\"layer\":\"main\"}],\"refs\":[\"c252\",\"c253\",\"c255\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-97\",\"name\":\"梅经理\",\"aliases\":[\"老梅\",\"常务经理\"],\"identity\":\"超市常务经理，中国少数民族，口音被形容奇特。\",\"traits\":[\"讲理和气：愿帮王澄清错价\",\"平易近人：与员工半玩笑说工作\",\"愿识才：邀王去防损部\",\"有同理心：王海峰病中愿替其请假。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段未交代后续职务变化。\",\"statusRefs\":[\"c402\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"他与压责的女部门经理对照，说明超市上层并非一致冷酷。错价时愿支持王，后又参与索赔协调；陈也借和他早餐避免迟到训斥。c327明确不是外国人，只是口音特殊，图鉴应保留身份而不误读。调王防损的邀请被拒，未因拒绝报复。\",\"segmentFate\":\"截至本段仍任常务经理，与01部门关系较融洽。\",\"refs\":[\"c254\",\"c255\",\"c256\",\"c298\",\"c327\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"她的短暂出现显示管理职位并不天然意味着冷漠。王海峰结石就医后遭强令返工，梅经理愿意代为请假，与基层同事共同为他减轻负担。但个人关心没有改变总经理的权力或王长期受到的压力。\",\"segmentFate\":\"本段未交代后续职务变化。\",\"refs\":[\"c402\"],\"layer\":\"main\"}],\"refs\":[\"c254\",\"c255\",\"c256\",\"c298\",\"c327\",\"c402\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-98\",\"name\":\"红酒索赔者、老耀与本地人情链\",\"aliases\":[\"老耀\",\"万老板\",\"辉哥\"],\"identity\":\"无名索赔者及王认识的地方打假利益圈；老耀接替辉哥，隶属万老板。\",\"traits\":[\"索赔者利用标签缺失谋利\",\"王识破圈内关系后对方退让\",\"地盘逻辑影响本应按商品规则解决的投诉\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段此次投诉被压下，酒被接回；各人物后续未写。\",\"statusRefs\":[\"c254\",\"c255\",\"c256\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"一瓶199元红酒因缺厂家信息引投诉，王询问熟悉的圈内地盘并致电老耀，索赔者才接受退让，王以中华烟收尾。辉哥因事被捕只是话中背景；万老板、老耀未与苏建立直接关系。这是小说中的非正式处理过程，不能写成现实合法维权标准，更不能把所有索赔都称敲诈。\",\"segmentFate\":\"本段此次投诉被压下，酒被接回；各人物后续未写。\",\"refs\":[\"c254\",\"c255\",\"c256\"],\"layer\":\"main\"}],\"refs\":[\"c254\",\"c255\",\"c256\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-99\",\"name\":\"促销员们\",\"aliases\":[\"徽记促销员\",\"德芙促销员\",\"旺旺促销员\",\"酒柜促销员\",\"散称盘点促销员\"],\"identity\":\"超市不同品牌与区域促销人员，多数无名，角色不能互相混同。\",\"traits\":[\"徽记最初未分担保质期，王分工后开始配合\",\"旺旺示范吆喝帮助苏学习卖清仓品\",\"酒柜人员调停陈与防损冲突\",\"散称促销员打盹并偷吃商品\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段仍各自工作，没有统一结局。\",\"statusRefs\":[\"c256\",\"c261\",\"c263\",\"c299\",\"c352\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"这些劳动者并非单一群像：德芙让苏知道徽记应分担工作，旺旺用实际示范帮她跨出推销一步，酒柜促销员协调争执；后来的散称搭班者则在暗仓睡觉并吃未付商品。共同说明岗位标签无法决定品质，图鉴应按情节功能标识，不要给未名者造姓名。\",\"segmentFate\":\"截至本段仍各自工作，没有统一结局。\",\"refs\":[\"c256\",\"c261\",\"c263\",\"c299\",\"c352\"],\"layer\":\"main\"}],\"refs\":[\"c256\",\"c261\",\"c263\",\"c299\",\"c352\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-100\",\"name\":\"前台年轻女职员\",\"aliases\":[],\"identity\":\"超市前台无名年轻女性员工。\",\"traits\":[\"欣赏能力：王解决红酒纠纷后显好感\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段仅显好感，恋情未发展。\",\"statusRefs\":[\"c256\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"她的短暂反应为王的成熟协调能力增加侧面评价，也与防损周追苏的职场情感形成小对照。本段没有进一步约会、告白或明确互相回应，不能将好感上升为王的女友身份。\",\"segmentFate\":\"本段仅显好感，恋情未发展。\",\"refs\":[\"c256\"],\"layer\":\"main\"}],\"refs\":[\"c256\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-101\",\"name\":\"防损部员工指导及各部门主管\",\"aliases\":[],\"identity\":\"防损员工指导、前台主管、玩具部主管等超市管理配角。\",\"traits\":[\"熟人玩笑：起哄周追苏、在风波后争邀苏转部\",\"岗位权力影响日常：部门间协调或推活\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段仍在各部门任职。\",\"statusRefs\":[\"c256\",\"c278\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"他们呈现超市各部门网络。前台与玩具等人对苏有好感并想把她调来，防损员工指导的撮合又使苏尴尬，由王及时解围。多数未给姓名，不应从岗位相同就并入刻薄女员工或周超；也没有主管追求苏的明确事实。\",\"segmentFate\":\"截至本段仍在各部门任职。\",\"refs\":[\"c256\",\"c278\"],\"layer\":\"main\"}],\"refs\":[\"c256\",\"c278\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-102\",\"name\":\"阿旺与老伟\",\"aliases\":[\"阿旺\",\"老伟\"],\"identity\":\"冉空城在电话中猜测恶作剧来电时提到的熟人。\",\"traits\":[\"性格未展开：只能确认冉知道这些称呼\"],\"portrait\":\"\",\"fate\":null,\"status\":\"仅被提到，无本段结局。\",\"statusRefs\":[\"c258\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"苏误拨又不说话，冉依声音和熟悉程度猜可能是阿旺或老伟。这两名并未实际接听或参与事件，也没有足够证据确认二人的学校、家庭、性别或与苏关系。人物索引可列为仅被提及，避免因名字出现就编造个人支线。\",\"segmentFate\":\"仅被提到，无本段结局。\",\"refs\":[\"c258\"],\"layer\":\"main\"}],\"refs\":[\"c258\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-103\",\"name\":\"梳子店老板娘\",\"aliases\":[],\"identity\":\"古风梳子专卖店的汉服女店主。\",\"traits\":[\"热情专业形象：介绍材质与雕纹\",\"体贴经营：在苏买梳后赠木镜\"],\"portrait\":\"\",\"fate\":null,\"status\":\"完成交易后未再明确出场。\",\"statusRefs\":[\"c261\",\"c262\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"她根据苏想买百元梳及睡眠体弱的自述推荐黑檀，促成苏买青莲梳送自己。人物的商品功效说法属于销售话术，图鉴应只记推荐、价格与礼物象征，不能当医疗依据。她温和经营让购物成为苏在紧缩生活中善待自己的一刻。\",\"segmentFate\":\"完成交易后未再明确出场。\",\"refs\":[\"c261\",\"c262\"],\"layer\":\"main\"}],\"refs\":[\"c261\",\"c262\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-104\",\"name\":\"周超\",\"aliases\":[],\"identity\":\"超市防损部年轻男员工，便衣暗保；对苏雨晴有追求意图。\",\"traits\":[\"善搭讪：谎称登记号码后坦承\",\"体贴灵活：接受带林同行、尊重各付餐费\",\"照护实际：帮处理报损并包扎手指\",\"感情喜新：叙述称常换对象但通常结束旧关系才开始新关系\",\"热心替人解围：带投诉霉米的顾客去服务台。\",\"务实择业：喜欢王海峰氛围，计划毕业前离职学面点奶茶或做销售。\",\"爽朗友善：主动重叙友情、请吃烧烤。\",\"常换女友，自称被甩，不能据此断定与孙同类。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段寒假在大润发工作，恋爱状态自称单身。\",\"statusRefs\":[\"c569\",\"c570\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"他利用苏对职位的顾虑取得联系方式，随后以冰淇淋、猫咖和占卜打开话题。同行约会未促成恋爱，占卜卡甚至以幽默回绝其女友问题；但午饭、创可贴等行动使苏承认他是为数不多的外界朋友。后期久不见面，苏猜他离职并感失落，原文当时没有确认其真实去向，也未说他知道苏的身体经历。\",\"segmentFate\":\"截至c352久未被苏遇见，是否离职未交代；两人未确立恋爱。\",\"refs\":[\"c264\",\"c265\",\"c266\",\"c268\",\"c270\",\"c273\",\"c274\",\"c278\",\"c352\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"调岗后他与雨晴接触增多，亲近举动让雨晴误判感情；女友公开来访把关系重新限定为同事。面对王海峰遭上级责难，他与大家一起表达不平。节前谈话又明确自己也是实习生，准备另找方向，成为雨晴看见同龄劳动者流动生活的例子。\",\"segmentFate\":\"截至c480本段未写其实际离职，仍以计划暑假前转行作结。\",\"refs\":[\"c371\",\"c372\",\"c381\",\"c402\",\"c416\"],\"layer\":\"main\"},{\"scope\":\"正文 c481—c600\",\"arc\":\"苏以促销员身份回超市时意外重逢，周立刻记得她。他的自然交谈使苏放松，也让她再次羡慕大学生活；他不知道苏实际失学和身份经历，接受她复读的解释并鼓励。\",\"segmentFate\":\"截至本段寒假在大润发工作，恋爱状态自称单身。\",\"refs\":[\"c569\",\"c570\"],\"layer\":\"main\"}],\"refs\":[\"c264\",\"c265\",\"c266\",\"c268\",\"c270\",\"c273\",\"c274\",\"c278\",\"c352\",\"c371\",\"c372\",\"c381\",\"c402\",\"c416\",\"c569\",\"c570\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-105\",\"name\":\"大草龟、燕子一家及郊外猫狗\",\"aliases\":[],\"identity\":\"集装箱附近的动物群；大草龟能载曲奇和咖啡渡水，燕子在附近生活。\",\"traits\":[\"日常陪伴：为郊外空间增加生机\",\"动物间亲近：龟载猫鼠的童话色彩\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段仍是郊外动物伙伴，没有死亡或失散情节。\",\"statusRefs\":[\"c265\",\"c266\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"这些动物不是人物名录中的人，但承担故事地图和情绪的重要功能：城市空间常意味着身份检查与工作，郊外动物共处则让苏吹箫、伙伴畅想山居。大龟没有名字，燕子一家也不应臆造个体身份。它们未来生存没有在本段展开。\",\"segmentFate\":\"截至本段仍是郊外动物伙伴，没有死亡或失散情节。\",\"refs\":[\"c265\",\"c266\"],\"layer\":\"main\"}],\"refs\":[\"c265\",\"c266\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-106\",\"name\":\"阿灰\",\"aliases\":[],\"identity\":\"郊外猎人老王的哈士奇。\",\"traits\":[\"活跃滑稽：抓鱼却叼回鹅卵石\",\"与人熟悉：在集装箱附近玩耍\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至c267随主人回家。\",\"statusRefs\":[\"c265\",\"c266\",\"c267\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"阿灰和流浪猫狗、燕子、大龟构成郊外暂时自由的动物乐园，给合租者雨天休息添轻松。它的主人明确是猎人老王，傍晚回来便随之归家，不能认作苏的狗或王海峰的犬。\",\"segmentFate\":\"截至c267随主人回家。\",\"refs\":[\"c265\",\"c266\",\"c267\"],\"layer\":\"main\"}],\"refs\":[\"c265\",\"c266\",\"c267\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-107\",\"name\":\"猎人老王\",\"aliases\":[],\"identity\":\"郊外哈士奇阿灰主人，持弓带猎物回家的猎人，非主管王海峰。\",\"traits\":[\"关照动物：阿灰见其回归便随行\",\"熟悉乡间：与扛农具村民自然往来\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段带阿灰回家，生活于附近村落。\",\"statusRefs\":[\"c267\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"集装箱房旁动物多与人亲近，老王傍晚的出现为阿灰提供清楚归属，也让苏等的郊外生活与邻村日常连接。猎弓和兔子只是返家所见，不需要展开实用狩猎说明。名字只有姓与称呼，不能补真实身份。\",\"segmentFate\":\"截至本段带阿灰回家，生活于附近村落。\",\"refs\":[\"c267\"],\"layer\":\"main\"}],\"refs\":[\"c267\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-108\",\"name\":\"占卜店老店主及售票搭档\",\"aliases\":[],\"identity\":\"步行街占卜店雇主与年轻售票者，莫空工作的同事。\",\"traits\":[\"经营神秘体验：灯光、门票、卡牌与分工\",\"信任莫：老店主让他接替占卜主持\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段店铺会议后恢复，莫仍从业。\",\"statusRefs\":[\"c270\",\"c272\",\"c275\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"占卜店本身有明确机关和商业设计，莫在其中给出触及内心的回答，二者不可混为全靠神力。老店主认可莫能力，售票搭档配合日常；会议停业又使他们的安排暂停。具体姓名、是否知道莫家世及神秘卡牌来历本段未说明。\",\"segmentFate\":\"本段店铺会议后恢复，莫仍从业。\",\"refs\":[\"c270\",\"c272\",\"c275\"],\"layer\":\"main\"}],\"refs\":[\"c270\",\"c272\",\"c275\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-109\",\"name\":\"天台幻见少女与失语少女\",\"aliases\":[],\"identity\":\"c271莫困倦时见脚铃仙女；c272占卜店前来无法说话少女，两者相似却身份未定。\",\"traits\":[\"沉默神秘：一者触额，一者赠狐狸木卡\",\"被动式呈现：所有信息由莫观察，未给说明\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段均未解释身份、来意或再次接触。\",\"statusRefs\":[\"c271\",\"c272\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"天台少女从星空似走来点额，莫随即睡去，现实与幻觉界线未明。翌日无法说话少女在店门静坐，给他精致薄木卡后离开，莫感觉相似。二者可作为同一待核线索组呈现，却不应直接宣布同一人，也不能指定为雯雯、水水或柳的披衣狐女。\",\"segmentFate\":\"本段均未解释身份、来意或再次接触。\",\"refs\":[\"c271\",\"c272\"],\"layer\":\"main\"}],\"refs\":[\"c271\",\"c272\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-110\",\"name\":\"莫空女房东\",\"aliases\":[],\"identity\":\"莫租住楼的年轻女性房东，对股票感兴趣。\",\"traits\":[\"愿听信息：与莫谈股票\",\"日常务实：作为租住关系中的普通邻近者\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段无投资后果与其他结局。\",\"statusRefs\":[\"c272\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"莫上班前与她短谈市场风险，显示他的阅历与观察并不只用于占卜。此章没有她按意见交易或盈亏结果，不能延伸为投资成功事件；对她个人性格也仅能保留短暂互动。\",\"segmentFate\":\"截至本段无投资后果与其他结局。\",\"refs\":[\"c272\"],\"layer\":\"main\"}],\"refs\":[\"c272\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-111\",\"name\":\"城市封店中的管理者、司机和居民\",\"aliases\":[],\"identity\":\"会议期间的官员考察团、清扫者、店家、司机与受检查居民等无名群像。\",\"traits\":[\"权力整饰：封店和检查以迎接来访\",\"谋生受阻：店主居民冲突，司机趁稀缺加价\",\"普通关怀仍在：村里因放假团聚、面馆多给面\"],\"portrait\":\"\",\"fate\":null,\"status\":\"八月底会议结束城市恢复，个体赔偿和行政结局未详。\",\"statusRefs\":[\"c275\",\"c276\",\"c281\",\"c286\",\"c297\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"城市事件并非只作背景，它改变所有人的工作休息与出行，使莫能赴海边、胡需回村、苏与林暂得写生时间。叙述混合批评与对不同视角的补充，不能把角色抱怨全当现实社会统计；各个官员未具名，也没有可核真实城市坐标。\",\"segmentFate\":\"八月底会议结束城市恢复，个体赔偿和行政结局未详。\",\"refs\":[\"c275\",\"c276\",\"c281\",\"c286\",\"c297\"],\"layer\":\"main\"}],\"refs\":[\"c275\",\"c276\",\"c281\",\"c286\",\"c297\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-112\",\"name\":\"小越与哥哥、二狗子与母亲\",\"aliases\":[],\"identity\":\"莫赴海边经过村庄时见的两组兄弟/母子。\",\"traits\":[\"家人保护：阻孩子入森林，以野兽危险劝回\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段仍在村里生活，无后续交代。\",\"statusRefs\":[\"c276\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"普通村落里的亲昵关心让莫放慢脚步，并想起自己孤独的大少爷童年和忠仆。小越的哥哥用孩子听得懂的比喻解释野猪，二狗子的母亲阻其跑入林中。只在短场景出现，姓名不能扩展成后续重要支线或与其他狗名混同。\",\"segmentFate\":\"本段仍在村里生活，无后续交代。\",\"refs\":[\"c276\"],\"layer\":\"main\"}],\"refs\":[\"c276\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-113\",\"name\":\"海边别墅管家与厨师女仆\",\"aliases\":[],\"identity\":\"陪大小姐帆船活动、准备饮食及病中照护的工作人员。\",\"traits\":[\"工作有秩序：外出陪同、配合落姨照顾病人\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段仍在别墅服务，个人结局未交代。\",\"statusRefs\":[\"c276\",\"c277\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"他们构成大小姐物质优裕而又受保护的生活背景。帆船与海滩似有自由，实际旁边始终有服务者；发热时又能迅速提供饮食和照护。此群体无个人名字的成员不应凭空补设家庭、动机或秘密知识，是否知时间接替也未说明。\",\"segmentFate\":\"截至本段仍在别墅服务，个人结局未交代。\",\"refs\":[\"c276\",\"c277\"],\"layer\":\"main\"}],\"refs\":[\"c276\",\"c277\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-114\",\"name\":\"莫空家人及老仆\",\"aliases\":[],\"identity\":\"莫的祖父、父母、奶奶及长期照护他的老仆；家族权斗的受害者。\",\"traits\":[\"老仆忠诚：如祖父般陪伴莫，曾保护祖父与父亲\",\"奶奶关爱：年少失亲后的支柱\",\"家族争权残酷：亲人遭杀害而权位仍具诱惑\"],\"portrait\":\"\",\"fate\":null,\"status\":\"爷爷、父亲、奶奶及老仆死亡为回忆事实；母失踪未明，凶手经莫复仇付代价。\",\"statusRefs\":[\"c276\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"祖父在莫出生前已死，父亲死而母亲失踪，不能把母也写成已故。奶奶受迫自尽，年迈忠仆被毒杀，他有军旅背景并曾护上一代。失去亲近者使莫卷入复仇，他以派系相争报复，获得压倒威望却最终离开家主之位。无名争权者不可添名，母亲下落是本段重要未决。\",\"segmentFate\":\"爷爷、父亲、奶奶及老仆死亡为回忆事实；母失踪未明，凶手经莫复仇付代价。\",\"refs\":[\"c276\"],\"layer\":\"main\"}],\"refs\":[\"c276\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-115\",\"name\":\"女仆长落姨\",\"aliases\":[\"落姨\"],\"identity\":\"海边别墅女仆长。\",\"traits\":[\"成熟体贴：安排照护病中大小姐、关心水水\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段继续在别墅工作。\",\"statusRefs\":[\"c277\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"大小姐发热时，她与厨师及女仆们一起维持家中照料，体现别墅里的保护网络。她并非未来自述的直接讲述者，本段也没有她解释神秘转变的情节。管家、厨师长等其他人员可归同一服务群体，但落姨作为有称谓的主导者单独登记。\",\"segmentFate\":\"截至本段继续在别墅工作。\",\"refs\":[\"c277\"],\"layer\":\"main\"}],\"refs\":[\"c277\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-116\",\"name\":\"金晶\",\"aliases\":[\"女班长\",\"班长\"],\"identity\":\"苏与冉原同届班长、校长女儿；二人留级后高一届，现赴别城高中。\",\"traits\":[\"强势保护弱者：直接呵退孔荀并要求苏以后求助\",\"关心延续：升初三仍借事务探望苏\",\"气质有变化：苏记忆中由女王般威严转温柔文静\",\"能力强、保护过苏；冉评价其可能对苏有好感。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段在高中求学的旧闻，后续未写。\",\"statusRefs\":[\"c526\",\"c529\",\"c570\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"回忆中她凭职务与家庭背景能制止体育课代表霸凌，并认真维护苏；苏与冉留级后，她仍有意保持联系。苏怀疑她喜欢自己，却认为可能是姐姐照顾弟弟，不敢把自己的感受定为爱情。中秋冉告知她已赴其他城市上高中，使苏感觉一条旧生活的路渐远。气质变温柔原因只由苏猜为成熟，不能自行填入超自然解释。\",\"segmentFate\":\"截至本段已赴别城读高中，未与苏现实重逢；情感性质和气质变化原因待核。\",\"refs\":[\"c279\",\"c309\",\"c339\",\"c340\"],\"layer\":\"main\"},{\"scope\":\"正文 c481—c600\",\"arc\":\"冉来访谈到班级变化和同学录时提及她，使苏重新理解过去的学校关系。苏也把她与海边别墅少女并列为印象深刻的美丽人物。对苏的恋爱意图并未由本人证实，不宜直接列成确定暗恋关系。\",\"segmentFate\":\"截至本段在高中求学的旧闻，后续未写。\",\"refs\":[\"c526\",\"c529\",\"c570\"],\"layer\":\"main\"}],\"refs\":[\"c279\",\"c309\",\"c339\",\"c340\",\"c526\",\"c529\",\"c570\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-117\",\"name\":\"平凡少年\",\"aliases\":[],\"identity\":\"苏绕路在住处附近中学操场看见独练羽毛球的无名少年。\",\"traits\":[\"孤独自处：独自打球仍继续练习\"],\"portrait\":\"\",\"fate\":null,\"status\":\"仅被苏远望，未在本段确定姓名、关系和后续。\",\"statusRefs\":[\"c280\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"他的身影触发苏回忆自己因怕拖累冉而拒绝陪伴。苏没有实际与他交谈，人物的作用主要为情绪镜像和可能的后续身份线索。本段不足以确认他就是被胡救过的人、吕布卡男生或其他同样普通相貌人物。\",\"segmentFate\":\"仅被苏远望，未在本段确定姓名、关系和后续。\",\"refs\":[\"c280\"],\"layer\":\"main\"}],\"refs\":[\"c280\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-118\",\"name\":\"无名面馆老板夫妇\",\"aliases\":[],\"identity\":\"胡回乡前停留的面馆经营者，勿与此前新闻中冲突的面馆自动合并。\",\"traits\":[\"朴素善意：额外加面照顾顾客\",\"面临封店损失：受城市会议整饰影响\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段仍营业或面临停业安排，个人后果未交代。\",\"statusRefs\":[\"c281\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"胡因不敢归家逗留，听食客抱怨封店，又从老板多加一份面获得小小温暖。此事让他在迷惘中看见普通人互助，并接续之后与莫河堤饮酒。店主未承担后续主线，不应因都是面馆就并作新闻案件地点。\",\"segmentFate\":\"本段仍营业或面临停业安排，个人后果未交代。\",\"refs\":[\"c281\"],\"layer\":\"main\"}],\"refs\":[\"c281\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-119\",\"name\":\"胡玉牛父母及大伯\",\"aliases\":[],\"identity\":\"乡村习武家庭长辈；父亲承受家族道馆衰落，母亲料理家庭。\",\"traits\":[\"父严厉但出现松动：发现身体变化后没有照旧动手，承认孩子应有想法\",\"母亲细致：天未亮做海鲜丸子\",\"延续男性期待：催女友婚事，把虚弱当需要进补\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段不知道胡女性愿望，仍盼其婚育；中秋胡计划返家。\",\"statusRefs\":[\"c281\",\"c282\",\"c283\",\"c325\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"胡归家看见旧武馆衰败，理解父亲为何执着锻炼与家族荣光；父令其演醉拳后肯定技艺，也意外让其拥有一定自我决定空间。母的饭食与父母操心使胡感动，却同时把他推回儿子、未来丈夫的预设位置。他谎称文员、公司形象要求等来掩身体改变。大伯仅在虎鞭酒话题被提及，未实际参与本段冲突。\",\"segmentFate\":\"截至本段不知道胡女性愿望，仍盼其婚育；中秋胡计划返家。\",\"refs\":[\"c281\",\"c282\",\"c283\",\"c325\"],\"layer\":\"main\"}],\"refs\":[\"c281\",\"c282\",\"c283\",\"c325\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-120\",\"name\":\"合租屋二房东\",\"aliases\":[],\"identity\":\"把白兔街住房租给苏等人的本地户籍转租人。\",\"traits\":[\"提供租住渠道：会议清理外来人员时，本地户籍使五人暂能继续住下。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段继续作为住房租赁关系的中间人，更多经历未交代。\",\"statusRefs\":[\"c286\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"本段只以租赁关系的重要条件被介绍。会议期间许多房东受压力终止外来人员租住，五位室友因租自当地户籍二房东而没有马上被赶走，但仍怕上门查验。原文没有给出此人的姓名、外貌、主动抗争行动或额外承诺，不宜把居住结果补成其舍身保护的故事。\",\"segmentFate\":\"截至本段继续作为住房租赁关系的中间人，更多经历未交代。\",\"refs\":[\"c286\"],\"layer\":\"main\"}],\"refs\":[\"c286\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-121\",\"name\":\"黄枸\",\"aliases\":[\"黄苟\",\"狗哥\",\"黄枸（黄苟）\",\"黄枸／黄苟\"],\"identity\":\"狗头帮帮主，黄发；本段原文两种字形混用同人。\",\"traits\":[\"救人果断：跳河救柳\",\"重责任与组织：分工、聚会、严禁沾毒\",\"选择性道德：反侵害又放任部分偷打行为\",\"有民族偏激情绪：曾弃游戏王而学围棋\",\"冷静有组织野心：与军师规划扩张、费用及盘店。\",\"有帮规约束手下，却也会替他人决定幸福。\",\"重情且果断：得讯带约四十人救援。\",\"存在利益盘算，但实际优先救人。\",\"本篇主要以地盘关系被提及，缺少足够行动判定性格\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段完成救援、配合警方；后续去向无详写。\",\"statusRefs\":[\"c483\",\"c490\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"先以有偏见的混混形象出现，却用救落水少女打破简单善恶标签。他与胡友好结识，也主动探望曾有地盘冲突的天并赔礼。两帮和解后共享基地，他仍主张让天开始新生活。旧部认出胡时，黄获知天侵害柳在先，选择两不相帮，维护自己的义气尺度。帮中仍有伤害与歧视，不可只用救人把其团体净化。\",\"segmentFate\":\"截至c360仍管理狗头帮，共用区域事实上由其占主导；未加入对胡报复。\",\"refs\":[\"c288\",\"c289\",\"c300\",\"c348\",\"c353\",\"c354\",\"c360\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"天语遥退出后旧帮解散，黄枸接收中立据点，着手更系统的地盘和经营计划。夏归月来问下落，他明知天家住址却隐瞒，认定天离开是在尽责任、给她更好未来。这种自以为理解朋友的行动实际阻断了两位当事人的交流。\",\"segmentFate\":\"截至c480仍在扩张帮会，盘酒吧和合作计划尚未落定。\",\"refs\":[\"c427\",\"c478\"],\"layer\":\"main\"},{\"scope\":\"正文 c481—c600\",\"arc\":\"他得到与夏相近的消息后介入地下室事件，看到天受伤立即安排医院与通知家属。身边军师提醒先报警急救，不忙扩地盘，呈现街头组织的人情面与其粗糙秩序并存。\",\"segmentFate\":\"本段完成救援、配合警方；后续去向无详写。\",\"refs\":[\"c483\",\"c490\"],\"layer\":\"main\"},{\"scope\":\"c601—c665；x001—x079（全部补充篇）\",\"arc\":\"其名字用于说明天冲云与雷神帮周边的势力关系和行动边界，并未在本篇形成独立的感情或成长故事。适合地图与组织索引保留，不能仅凭恶名式称呼补写暴力行为或最终遭遇。\",\"segmentFate\":\"前传没有交代独立结局。\",\"refs\":[\"x070\"],\"layer\":\"prequel\"}],\"refs\":[\"c288\",\"c289\",\"c300\",\"c348\",\"c353\",\"c354\",\"c360\",\"c427\",\"c478\",\"c483\",\"c490\",\"x070\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-122\",\"name\":\"凤凰\",\"aliases\":[],\"identity\":\"狗头帮红发、凤凰纹身长腿成员，速度快。\",\"traits\":[\"跑腿可靠：迅速买回泡面与热水\",\"适于侦察：被狗哥比作斥候\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段仍属狗头帮。\",\"statusRefs\":[\"c289\",\"c353\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"他的特长使团体分工有具体形状，不是只靠统一“混混”标签。正式介绍和雨天代购两处呈现一致行动，体现骨干间的熟悉与协作。本段未给个人原名、年龄或恋爱信息。\",\"segmentFate\":\"截至本段仍属狗头帮。\",\"refs\":[\"c289\",\"c353\"],\"layer\":\"main\"}],\"refs\":[\"c289\",\"c353\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-123\",\"name\":\"剑鱼\",\"aliases\":[\"变色鱼\",\"军师\"],\"identity\":\"狗头帮军师，高中毕业未考上大学，尖耸发型常换颜色。\",\"traits\":[\"能谋划：负责策略与成员排忧\",\"文数较好但英语弱：以民族自尊话术遮掩\",\"组织实务：偷来垃圾桶维护基地卫生仍属不当行为\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段仍任狗头帮军师，未介入天旧部报复决定。\",\"statusRefs\":[\"c289\",\"c353\",\"c354\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"他被介绍为不用单靠蛮力的人，平时协助学习、人际和帮派策略。雨天聚会解题与吹嘘并置，让知识优势和狭隘观念同现。公共基地建设中与彩虹合作，胡柳到访时热情邀泡面；并无此段独立制定复仇方案的证据。\",\"segmentFate\":\"截至本段仍任狗头帮军师，未介入天旧部报复决定。\",\"refs\":[\"c289\",\"c353\",\"c354\"],\"layer\":\"main\"}],\"refs\":[\"c289\",\"c353\",\"c354\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-124\",\"name\":\"彩虹\",\"aliases\":[],\"identity\":\"狗头帮七彩发元老，消息灵通，父亲是木匠。\",\"traits\":[\"好学好说：读多份报纸、解释字词却添油加醋\",\"有木工能力：带众用废料制床\",\"争功好面子：吹嘘基地都是自己布置\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至c354木床正在制作，仍属狗头帮骨干。\",\"statusRefs\":[\"c289\",\"c353\",\"c354\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"初登场以情报灵通被介绍，后续雨天聚会补出阅报习惯和文化能力。最鲜明的实际工作是木板床，虽然只看父亲做过，他仍耐心刨磨组装，努力把废料做得整洁。才能与不良群体结合，是莫此前青年学艺故事的现实对照，但不能据此预写他日后改行。\",\"segmentFate\":\"截至c354木床正在制作，仍属狗头帮骨干。\",\"refs\":[\"c289\",\"c353\",\"c354\"],\"layer\":\"main\"}],\"refs\":[\"c289\",\"c353\",\"c354\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-125\",\"name\":\"赤脚大仙\",\"aliases\":[],\"identity\":\"狗头帮骨干，以金脚项链和夸张脚臭喜剧设定识别。\",\"traits\":[\"作为奇特特长成员：狗哥介绍其在撤退中曾发挥作用\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段仍为狗头帮成员。\",\"statusRefs\":[\"c289\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"他在正式互相介绍时提供荒诞喜剧，让柳对这一群体既惊奇又难信。袜子“削弱战力”的说法显然夸张，不宜当真实生物威力或战斗方法展开。除名号、项链、群体位置之外，个人生活与后续没有在本段提供。\",\"segmentFate\":\"截至本段仍为狗头帮成员。\",\"refs\":[\"c289\"],\"layer\":\"main\"}],\"refs\":[\"c289\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-126\",\"name\":\"金毛狮王\",\"aliases\":[],\"identity\":\"狗头帮八名骨干之一，披散金发，善于打斗。\",\"traits\":[\"力量型骨干：狗哥称特能打\",\"懂分寸：在更强大的胡面前谦虚\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段仍属狗头帮，未有独立结局。\",\"statusRefs\":[\"c289\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"c289正式被介绍给胡柳，他没有因自己能打就冒进，而是表现谦虚。后文公共聚会未以姓名独立承担重大转折，图鉴应限于明确特长和成员关系，不把其他无名打斗全归给他。\",\"segmentFate\":\"截至本段仍属狗头帮，未有独立结局。\",\"refs\":[\"c289\"],\"layer\":\"main\"}],\"refs\":[\"c289\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-127\",\"name\":\"青蛙\",\"aliases\":[],\"identity\":\"狗头帮跑酷特长成员。\",\"traits\":[\"行动敏捷：在农民房间穿行，能执行牵引和接应\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段仍属狗头帮，个人结局未写。\",\"statusRefs\":[\"c289\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"狗哥介绍他曾配合军师调虎离山，是群体中靠具体技能而被认可的人。此段没有以他为视角的支线，也没有实际展示需要复现的战术或跑酷动作，只须记录功能及关系。\",\"segmentFate\":\"截至本段仍属狗头帮，个人结局未写。\",\"refs\":[\"c289\"],\"layer\":\"main\"}],\"refs\":[\"c289\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-128\",\"name\":\"鼠标\",\"aliases\":[],\"identity\":\"狗头帮黑发、瘦小成员，擅电脑与下载。\",\"traits\":[\"技术有用：帮众处理网络娱乐\",\"言行猥琐但讲兄弟关系：自夸后让柳不适\",\"知识有边界：部分字仍问彩虹\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段仍属狗头帮，是否直接造成天帮电脑中毒待核。\",\"statusRefs\":[\"c289\",\"c353\",\"c360\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"他代表在暴力团体里技术也能成为位置来源。介绍时有关成人娱乐的自夸使柳退避，狗哥替其强调不侵犯朋友伴侣；雨天又和朋友聊网络资源。c360老三电脑中毒被称来自黄手下擅下载者，但未直书其名，不宜完全确定责任归鼠标。\",\"segmentFate\":\"截至本段仍属狗头帮，是否直接造成天帮电脑中毒待核。\",\"refs\":[\"c289\",\"c353\",\"c360\"],\"layer\":\"main\"}],\"refs\":[\"c289\",\"c353\",\"c360\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-129\",\"name\":\"天语遥父母\",\"aliases\":[\"天语遥父亲\",\"天语遥母亲\"],\"identity\":\"小康白领家庭父母，无显赫权势；照护受创的天冲云并推动改名为天语遥。\",\"traits\":[\"最初控制：替孩子定女性化方向和新姓名\",\"危机后反思：父承认不该逼、愿改回名字与寻找治疗\",\"持续劳动和关心：请假照护、买食物礼物、考虑未来保障\",\"母有越界：熟睡时换女装，关心不等于获得同意\",\"以存活与幸福为先：多次危机后严密照护，最终支持与同类共住。\",\"关怀也有强迫：母亲坚持衣着打扮，过问室友隐私，出发点是担心。\",\"父亲笨拙但肯付出：给钱、买相机、陪陶艺课、背孩子、帮要筷子。\",\"母亲牵挂与照顾，带电脑等陪伴资源。\",\"父亲积极诉讼，但采取腐败、混淆旧伤与新伤的手段。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段天存活但精神受损，父母仍是照护者。\",\"statusRefs\":[\"c484\",\"c491\",\"c492\",\"c494\",\"c499\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"父母想替孩子找到受伤后的出路，却把自己的最佳方案当成唯一选择，导致天第一次危机。获救后父道歉，孩子选择称小遥并要求陪伴，家庭开始能直接表达爱。母陪游园、购软陶与饼干，父不断工作以准备未来，天逐渐看懂付出。母仍把替其换装当引导，说明控制没有完全停止；父多次承诺出游受工作牵制，新的杭州之约尚未展示成行。\",\"segmentFate\":\"截至c360仍在职并支持小遥居家生活，不知道她已重新计划找胡复仇。\",\"refs\":[\"c295\",\"c296\",\"c301\",\"c302\",\"c320\",\"c323\",\"c324\",\"c335\",\"c336\",\"c350\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"两人在受创后逐渐调整对子女的期待，从盼回到过去转成只希望快乐活着。允许搬出需要彻夜商议，送去时又不断清理照看，使天感激且窒息。他们不知复仇真实计划，也未能辨识逐渐严重的幻觉；c480母亲收到雨晴电话急来接回。父亲看两本育儿书并见夏归月只是幻觉，真实买的是玄幻小说。\",\"segmentFate\":\"截至c480继续照护天语遥，母亲已将她接回；其报复细节仍未被雨晴告知。\",\"refs\":[\"c364\",\"c365\",\"c385\",\"c386\",\"c387\",\"c388\",\"c399\",\"c458\",\"c459\",\"c463\",\"c464\",\"c480\"],\"layer\":\"main\"},{\"scope\":\"正文 c481—c600\",\"arc\":\"重伤消息到来后赶赴医院，最初相信身体能恢复，也怀疑夏能坚持多久。长期昏迷与醒来后的严重精神问题打碎期待，父亲仍推动从重判罚。梦中年轻父母及复活外公只是天重新安排的记忆。\",\"segmentFate\":\"截至本段天存活但精神受损，父母仍是照护者。\",\"refs\":[\"c484\",\"c491\",\"c492\",\"c494\",\"c499\"],\"layer\":\"main\"}],\"refs\":[\"c295\",\"c296\",\"c301\",\"c302\",\"c320\",\"c323\",\"c324\",\"c335\",\"c336\",\"c350\",\"c364\",\"c365\",\"c385\",\"c386\",\"c387\",\"c388\",\"c399\",\"c458\",\"c459\",\"c463\",\"c464\",\"c480\",\"c484\",\"c491\",\"c492\",\"c494\",\"c499\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-130\",\"name\":\"防损部刻薄女员工\",\"aliases\":[],\"identity\":\"苏领软标和仓库盘点时遇到的无名女性员工，与周超及防损员工指导不同。\",\"traits\":[\"反复挑剔：敲门、流程、借笔、字迹皆责难\",\"迁怒基层：把失窃及工作问题压给来办事者\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段与陈冲突暂经促销员调停，未见正式处分。\",\"statusRefs\":[\"c298\",\"c299\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"她先让取软标的苏在礼貌回应中备受紧张，后到独立酒仓核对又与陈互相讥讽，延误工作。苏亲历后更厌倦官腔和权力施压。原文带身体与婚恋贬低，这些不应被采作性格原因；只依据其具体行为评述。\",\"segmentFate\":\"截至本段与陈冲突暂经促销员调停，未见正式处分。\",\"refs\":[\"c298\",\"c299\"],\"layer\":\"main\"}],\"refs\":[\"c298\",\"c299\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-131\",\"name\":\"文澜学院腼腆男生\",\"aliases\":[\"求吕布闪卡的高中生\"],\"identity\":\"相貌普通、穿文澜学院高中校服的少年，苏觉得眼熟但未确认。\",\"traits\":[\"真诚珍惜：愿出两百并坚持付钱\",\"腼腆：被注视便低头、收卡入册很认真\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至c310收卡离开，姓名与后续未说明。\",\"statusRefs\":[\"c310\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"他在学生竞价时出现，苏没有利用高价而免费送卡。少年把这张少数缺卡之一郑重收进齐整卡册，表明礼物落在真正珍视者手里。苏的眼熟感只是伏笔；不能单凭普通相貌将他与c280练羽毛球少年或后来的秋易合并。\",\"segmentFate\":\"截至c310收卡离开，姓名与后续未说明。\",\"refs\":[\"c310\"],\"layer\":\"main\"}],\"refs\":[\"c310\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-132\",\"name\":\"朱雀\",\"aliases\":[\"小红鸡\"],\"identity\":\"苏雨晴购买并命名的红色雏鸡，短暂加入她、曲奇与咖啡的日常。\",\"traits\":[\"大胆亲人：抢猫粮、跟随和回应苏\",\"生命短促：数日后迅速萎靡病死\"],\"portrait\":\"\",\"fate\":{\"name\":\"朱雀\",\"label\":\"病死并被埋葬\",\"tone\":\"red\",\"text\":\"雨晴购买并取名的染红雏鸡，后来病死，被她与曲奇、咖啡一起埋在小区绿化处。\",\"note\":\"它的死亡先于几条重大人物悲剧，让雨晴直接触到生命有限。\",\"refs\":[\"c310\",\"c328\"]},\"status\":\"c328明确病死并埋葬，c329墓渐不起眼。\",\"statusRefs\":[\"c316\",\"c319\",\"c325\",\"c327\",\"c328\",\"c329\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"由一元冲动购买开始，它很快被苏视为家庭成员，猫鼠从警惕到照护。健康时活泼与急病时无力形成强烈反差，众人无法挽回，苏自责带它安葬。红色与朱雀名让小生命显得热烈，实际并无复生，墓土随时间淡去。它的死亡并非主角死亡，却推动苏面对朋友宠物和父母的有限生命。\",\"segmentFate\":\"c328明确病死并埋葬，c329墓渐不起眼。\",\"refs\":[\"c310\",\"c316\",\"c319\",\"c325\",\"c327\",\"c328\",\"c329\"],\"layer\":\"main\"}],\"refs\":[\"c310\",\"c316\",\"c319\",\"c325\",\"c327\",\"c328\",\"c329\"],\"group\":\"动物伙伴\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-133\",\"name\":\"相似年轻女人\",\"aliases\":[],\"identity\":\"教师节雷暴后在步行街接走大小姐的年轻女性，与其容貌相似。\",\"traits\":[\"亲近照护：买等身熊，横抱大小姐上跑车\"],\"portrait\":\"\",\"fate\":null,\"status\":\"c312后带大小姐离开步行街，具体去向未见。\",\"statusRefs\":[\"c312\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"她在大小姐明显改变后出现，与她交谈，随后买毛绒熊并将其带走。苏只能看到两人相貌近似和亲密举动，本段未给出姓名与亲属关系，不能直接指定为母亲、姐姐或另一时间版本。她的出现与雨止一起加强苏“时间被截断”的异样感。\",\"segmentFate\":\"c312后带大小姐离开步行街，具体去向未见。\",\"refs\":[\"c312\"],\"layer\":\"main\"}],\"refs\":[\"c312\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-134\",\"name\":\"林夕晨父母及姐姐们\",\"aliases\":[],\"identity\":\"偏远山村家庭，父把林视为唯一儿子，另有几位亲姐姐。\",\"traits\":[\"父严重重男轻女：打骂姐姐并急于嫁出\",\"家人联系条件有限：无银行卡、无电话\",\"林仍牵挂：现金信报平安却避留地址\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段家人不知林女性生活，仍收到或等待她寄出的信款；具体后果未交代。\",\"statusRefs\":[\"c313\",\"c340\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"c313把林“有家不能回”具体化：父把浓烈期待集中于唯一儿子，姐姐却被当作可处置的负担。林已一年多不回，担心父发现性别变化后断绝关系，因此仅每年一两次寄钱写信。父尚未现实发现或作出断亲反应，那只是她的担忧；母与各姐姐的名字、当前婚姻及去向本段未交代。\",\"segmentFate\":\"截至本段家人不知林女性生活，仍收到或等待她寄出的信款；具体后果未交代。\",\"refs\":[\"c313\",\"c340\"],\"layer\":\"main\"}],\"refs\":[\"c313\",\"c340\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-135\",\"name\":\"天语遥的爷爷\",\"aliases\":[],\"identity\":\"天童年回忆中会制作糖人及各类糖画的祖父。\",\"traits\":[\"手艺精湛：能做生动人物\",\"影响兴趣：童年让天接触可自由塑形材料\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段仅回忆，当前去向未交代。\",\"statusRefs\":[\"c314\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"天浏览制陶广告时记起与爷爷学做糖人的快乐，从而发现自己一直喜欢积木、泥土和糖这类可造形材料。祖父没有在当前时间线出场，是否健在也未明；他的作用在于为软陶新路提供并非凭空出现的童年根源。\",\"segmentFate\":\"本段仅回忆，当前去向未交代。\",\"refs\":[\"c314\"],\"layer\":\"main\"}],\"refs\":[\"c314\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-136\",\"name\":\"黑皇\",\"aliases\":[\"黑皇\",\"大黑狼犬\",\"大黑\",\"小黑\",\"狗王\",\"大黑狗\",\"黑皇（小黑）\",\"小黑（黑皇）\"],\"identity\":\"也与“小黑”称呼相关的大黑犬，曾亲近天语遥，后被秋易收养，由莫空取名黑皇。\",\"traits\":[\"忠诚识人：闻到天便飞奔扑迎\",\"体型大、需较多食物：天常专带一份\",\"容许其他动物分食：饱后放任小猫狗吃剩罐\",\"忠厚安静：听天倾诉并亲近回应。\",\"在狗群有地位：能与曲奇和平相处，呈狗背猫、猫背鼠画面。\",\"温顺有灵性：舔手、克制吃食、不咬喂食者。\",\"忠于照顾者：跟天到小区被赶，又跟秋上天台。\",\"机警协助：随主人发现并救助受伤雨晴\",\"与动物友好：同曲奇交流，提到另一只聪明黄白猫\"],\"portrait\":\"\",\"fate\":{\"name\":\"黑皇\",\"label\":\"由秋易收养，后续仍在\",\"text\":\"天语遥曾亲近的大黑犬，后来被秋易收养，由莫空命名黑皇。旧城回访时与秋易出现。\",\"note\":\"第348章叙述已提前称它黑皇，后文第590章才呈现莫空取名；另与小黑及投影线索有关，完整机制未说明。\",\"refs\":[\"c589\",\"c590\",\"c650\"]},\"status\":\"正文末段重逢时仍在，最终去向未交代。\",\"statusRefs\":[\"c604\",\"c609\",\"c650\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"它曾随天参与帮派活动，也被她视为旧生活重要伴侣。天病休后担忧无人按习惯喂它，重访见它消瘦而补丰盛食物；莫也给它饼干。大黑不因她外表与身体改变而陌生，正衬天害怕人会拒绝。耗三天软陶像让旧情感进入新生活，但仍未阻止她再回帮派。\",\"segmentFate\":\"截至c355仍在公共河边生活，天重访投喂并为其做陶像。\",\"refs\":[\"c321\",\"c322\",\"c347\",\"c348\",\"c355\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"它不评价天的身体或身份，是她可以诉说且不怕受辱的对象。春节其他人暂散，它仍在原地，让天感到旧世界还有不变的陪伴。天后来决意斩断过去，连想找它也忍住，因此狗不仅是宠物，也标记了主动离开支持关系的代价。\",\"segmentFate\":\"截至c459仍被天想念，但她不再去找；后续去向未写。\",\"refs\":[\"c380\",\"c384\",\"c427\",\"c459\"],\"layer\":\"main\"},{\"scope\":\"正文 c481—c600\",\"arc\":\"天孤独时喂它、从它身上取得温暖；天受害后旧照护链散去，它瘦弱受伤、蜷在泡沫盒中。秋坚持喂养并愿与它作伴，莫空赐名黑皇，从半散养流浪转为有稳定主人的生活。\",\"segmentFate\":\"c590正式被秋易收养，住天台，有新名字。\",\"refs\":[\"c483\",\"c589\",\"c590\"],\"layer\":\"main\"},{\"scope\":\"c601—c665；x001—x079（全部补充篇）\",\"arc\":\"它与秋易、莫空一同进入雨晴生命危机，也在曲奇视角中参与动物间的交往。后来雨晴重返旧天台再次见到它和秋易，成为空间与关系仍在的见证。它提到的另一只聪明猫仅是跨故事线索，本段没有充分解答身份。\",\"segmentFate\":\"正文末段重逢时仍在，最终去向未交代。\",\"refs\":[\"c604\",\"c609\",\"c650\"],\"layer\":\"main\"}],\"refs\":[\"c321\",\"c322\",\"c347\",\"c348\",\"c355\",\"c380\",\"c384\",\"c427\",\"c459\",\"c483\",\"c589\",\"c590\",\"c604\",\"c609\",\"c650\"],\"group\":\"动物伙伴\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-137\",\"name\":\"饼干\",\"aliases\":[],\"identity\":\"天语遥与母亲在游乐园买的黑白兔。\",\"traits\":[\"温顺好吃：在笼中吃叶草，允许熟人抚摸\",\"带来情绪安稳：天无意识抚兔时平复愤怒\",\"依靠人饲喂，安稳却受限。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至c464仍在天家，由天与母亲照看，后续未展开。\",\"statusRefs\":[\"c385\",\"c390\",\"c458\",\"c464\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"母亲先买后递给天，黑白毛像格子饼干而得名。天克制“可爱”评价以维护男性自尊，独处终于放开，后来主动查照护、换精致笼具。宠物使天从被照顾者重新成为照顾者，也在c360的解离般空白后成为她回神时抚着的生命；不应自行诊断其心理疾病。\",\"segmentFate\":\"截至c360健康生活在天家阳台笼内。\",\"refs\":[\"c322\",\"c323\",\"c335\",\"c360\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"天语遥借它思考安全与自由：放出笼子看似更自由，却也会让它暴露于危险，自己的处境似乎同样难以两全。饲养并不总细心，她在沉溺复仇或幻觉时会烦躁、忘记是否喂过，母亲于是接手补食。兔子逐渐变胖，仍是家庭日常中的依赖者。\",\"segmentFate\":\"截至c464仍在天家，由天与母亲照看，后续未展开。\",\"refs\":[\"c385\",\"c390\",\"c458\",\"c464\"],\"layer\":\"main\"}],\"refs\":[\"c322\",\"c323\",\"c335\",\"c360\",\"c385\",\"c390\",\"c458\",\"c464\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-138\",\"name\":\"方莜莜父母及继母\",\"aliases\":[],\"identity\":\"生父母在方幼年离婚，抚养归父；生母主动不要她，父另娶后与继母又分居。\",\"traits\":[\"长期缺席：方多年生日缺少家庭关照\",\"父亲赴大城市工作：留给方少管束的自由，也缺陪伴\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段与方疏远，不知其女性生活和手术计划，未有团聚。\",\"statusRefs\":[\"c325\",\"c332\",\"c346\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"这些家庭关系主要在中秋前谈话和生日回顾中说明，是方温柔照顾他人而对被记住特别动容的背景。她称自己已习惯、无人管束便能做喜欢的事，但神情显黯然。父今年外出工作、继母去年起不同住，不能等同两段婚姻都已法律离婚。方计划辞职做手术也不先说，因为认为家里本来不管，潜在冲突未解决。\",\"segmentFate\":\"截至本段与方疏远，不知其女性生活和手术计划，未有团聚。\",\"refs\":[\"c325\",\"c332\",\"c346\"],\"layer\":\"main\"}],\"refs\":[\"c325\",\"c332\",\"c346\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-139\",\"name\":\"秋易与天台男子（梦中）\",\"aliases\":[\"秋易\"],\"identity\":\"c338梦中男子接待苏并称她女友，介绍普通相貌大学生客人秋易。\",\"traits\":[\"男子熟络：称苏小晴、欢迎来家中坐\",\"秋易腼腆：作为旧邻居心情郁闷来排解\"],\"portrait\":\"\",\"fate\":null,\"status\":\"此段仅在梦出现，现实身份联系未明。\",\"statusRefs\":[\"c338\",\"c339\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"这场短梦与前一串惨剧不同，苏像看第一人称电影，无法控制动作和言语，只觉男子熟悉却看不清脸。男子说秋易是以前邻居、现大学生。苏醒后误把可能性联想到冉，但不能因此把男子认定为冉或把两人已经交往写成现实。秋易姓名是明确梦中信息，等待后文现实核验。\",\"segmentFate\":\"此段仅在梦出现，现实身份联系未明。\",\"refs\":[\"c338\",\"c339\"],\"layer\":\"main\"}],\"refs\":[\"c338\",\"c339\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-140\",\"name\":\"孔荀\",\"aliases\":[\"孔狗\"],\"identity\":\"苏旧校体育课代表，体育老师是其表哥。\",\"traits\":[\"恃势欺弱：要求体弱苏搬水\",\"滥用小权力：曾干扰冉体育成绩\",\"畏惧更强身份：金晶呵斥后退去\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段仅回忆出场，无现实结局。\",\"statusRefs\":[\"c339\",\"c340\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"只在校园回忆中出现，他借体格与体育课代表权限要求苏承担难以完成的活，以锻炼为名掩盖欺辱。冉为苏反抗，孔把冉扔入垃圾桶；直到校长女儿金晶介入才离开。他将小权力变为压制他人的工具，与苏超市见到的官威构成对应，后续是否受学校处分未交代。\",\"segmentFate\":\"本段仅回忆出场，无现实结局。\",\"refs\":[\"c339\",\"c340\"],\"layer\":\"main\"}],\"refs\":[\"c339\",\"c340\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-141\",\"name\":\"叶祖\",\"aliases\":[\"叶族祖先\"],\"identity\":\"叶族博物馆巨大镀金祖像与家族神话中的存在，非本段现实登场人物。\",\"traits\":[\"传说形象：征战、弑仙、夺取神物\",\"祖像气质：肃杀、苍凉，持轮回剑\"],\"portrait\":\"\",\"fate\":null,\"status\":\"仅在传说、雕像和画中出现，真实存在层级待后文。\",\"statusRefs\":[\"c343\",\"c344\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"博物馆将其作为先祖供奉，书册描述夸张神迹，苏把它当传说看待；轮回剑却与百流山所见对应，使纯神话与物证之间出现疑问。林回家画现代各国军人共抗似叶祖巨人，仍是画作，不能视为现实战斗或预定结局。\",\"segmentFate\":\"仅在传说、雕像和画中出现，真实存在层级待后文。\",\"refs\":[\"c343\",\"c344\"],\"layer\":\"main\"}],\"refs\":[\"c343\",\"c344\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-142\",\"name\":\"孔医生\",\"aliases\":[],\"identity\":\"胡玉牛曾去接受身份相关治疗的医生，仅在c349提及。\",\"traits\":[\"本段无直接出场或具体言行证据，不能评判医德与治疗质量。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段仅被提及，没有新就诊场面。\",\"statusRefs\":[\"c349\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"胡在与柳约会时回顾已经一月没有去孔医生处，且另有大半月停药，体力回升。他仍想恢复原来的安排，显示恋爱并未彻底取代女性人生愿望。孔医生本人的诊断、知情讨论、所在诊所和后续态度均未在本段交代，仅能作为胡先前治疗关系的一名具名人物记录。\",\"segmentFate\":\"截至本段仅被提及，没有新就诊场面。\",\"refs\":[\"c349\"],\"layer\":\"main\"}],\"refs\":[\"c349\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-143\",\"name\":\"老三\",\"aliases\":[\"老三\",\"天语遥帮老三\",\"猛哥\"],\"identity\":\"天的亲信旧部，曾在柳被围事件现场，后来发出关键留言。\",\"traits\":[\"忠诚而冲动：看到胡即想报复\",\"真诚接纳：无论变化仍认老大\",\"表达笨拙：留言与电话把温暖和暴力愿望相连\",\"忠诚重旧情：记得初见地点与一个甜筒。\",\"执行能力强：按嘱查得柳家住址、送达信件。\",\"具反思能力：帮会衰败时想起父母期待与木匠理想。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至c478帮会已经解散，天换号断联；他未来是否成为木匠，本段未交代。\",\"statusRefs\":[\"c380\",\"c431\",\"c434\",\"c436\",\"c458\",\"c478\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"他在公共基地首先认出胡，因记得重伤场面而激动，但被老二以人数和实力劝住。给天的长留言并未嫌弃变化，反而让天第一次真切知道旧部已知仍愿接纳；同一留言又恢复天的痛苦记忆。c360电话解释木马，求老大回帮以免分裂，最终把她拉回旧基地。其关爱真实，但复仇推动也同样真实。\",\"segmentFate\":\"截至c360执行天寻找胡的安排，并与众人迎回老大。\",\"refs\":[\"c354\",\"c359\",\"c360\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"儿时被勒索欺负而不敢反抗，天语遥带他奋起，虽输了却改变其性格。他随帮会成长，身先士卒，天退帮后承接领导，却无法留住众人。接受最后送信任务时仍满怀忠诚，不完全认识其后果；任务做完，他开始问混混生活是否值得延续。\",\"segmentFate\":\"截至c478帮会已经解散，天换号断联；他未来是否成为木匠，本段未交代。\",\"refs\":[\"c361\",\"c363\",\"c364\",\"c380\",\"c431\",\"c434\",\"c436\",\"c458\",\"c478\"],\"layer\":\"main\"}],\"refs\":[\"c354\",\"c359\",\"c360\",\"c361\",\"c363\",\"c364\",\"c380\",\"c431\",\"c434\",\"c436\",\"c458\",\"c478\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-144\",\"name\":\"老二\",\"aliases\":[\"老二\",\"天语遥帮老二\"],\"identity\":\"天缺席期间协助管理帮派的元老，电脑属于他。\",\"traits\":[\"相对冷静：顾及六人不是胡对手\",\"忠于原老大：坚持让其自行决定报仇\",\"关心集体损伤：认为不必无谓牺牲兄弟\",\"危难时忠诚：参与雨中营救。\",\"为救人寻找理由：醒后用报仇鼓励天活下去，并非希望她立即再陷危险。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段帮会已散，与换号后的天语遥失去联系；个人后路未展开。\",\"statusRefs\":[\"c361\",\"c362\",\"c363\",\"c364\",\"c365\",\"c431\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"面对老三被仇恨驱动，他没有否认报复目标，而是用人数、能力与决定权阻止当场冲突，给胡柳离开空间。后来电脑被同伴弄中木马，他在电话背景抱怨，凸显基地日常仍在；与老三一起希望天回来稳定面临分裂的帮派。冷静是策略层面，不能写为已反对暴力或劝终止复仇。\",\"segmentFate\":\"截至c360在旧木屋基地，天返回前由其等人暂管。\",\"refs\":[\"c354\",\"c360\"],\"layer\":\"main\"},{\"scope\":\"正文 c361—c480\",\"arc\":\"他与老三、老四代表天语遥仍能依靠的旧日情谊。帮内分裂时没有因老大身体变化而离开，危急时拼力营救。见她不愿醒来、难寻目标，他把报仇作为挽留生命的说辞，甚至宁可仇人一直找不到，好让她活下去。这个出于关心的理由被天转成真实复仇计划，构成善意未能预料的反面。\",\"segmentFate\":\"截至本段帮会已散，与换号后的天语遥失去联系；个人后路未展开。\",\"refs\":[\"c361\",\"c362\",\"c363\",\"c364\",\"c365\",\"c431\"],\"layer\":\"main\"}],\"refs\":[\"c354\",\"c360\",\"c361\",\"c362\",\"c363\",\"c364\",\"c365\",\"c431\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-145\",\"name\":\"论坛群友\",\"aliases\":[\"轨迹\",\"小猫\",\"群主及其他成员\"],\"identity\":\"新世界之门论坛及好想做个女孩子群的网友；轨迹、小猫等只是聊天昵称，尚无完整现实身份。\",\"traits\":[\"互相安慰：聊天中拥抱、回应低落者。\",\"外貌羡慕：称赞轨迹并议论身高与天赋。\",\"寻求同伴：发现同城后分享所在城市、商量见面。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"截至本段仍在网上互动；不等同于所有网友已在线下相聚。\",\"statusRefs\":[\"c355\"],\"segments\":[{\"scope\":\"正文 c241—c360\",\"arc\":\"c355群内从天气、工作、衣服和心情聊起，天逐渐感到融入。轨迹出现引发热情招呼，小猫被抱抱安慰，但不能据少量消息指定每句发言归属。张与方的同城聊天使天受邀拜访，并引发其他网友报城市；群主提出共同聚会却响应少，尚未组织成行。\",\"segmentFate\":\"截至本段仍在网上互动；不等同于所有网友已在线下相聚。\",\"refs\":[\"c355\"],\"layer\":\"main\"}],\"refs\":[\"c355\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-146\",\"name\":\"老四\",\"aliases\":[],\"identity\":\"天语遥忠心部下之一，参与帮内支持及查找仇人。\",\"traits\":[\"不因受创弃旧主：与兄弟共同维护她。\",\"能提供线索：发现阿牛在小城第一高中附近。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"帮会解散后的生活未交代，旧领袖已主动换号断联。\",\"statusRefs\":[\"c361\",\"c363\",\"c380\",\"c422\"],\"segments\":[{\"scope\":\"正文 c361—c480\",\"arc\":\"老四在本段更多通过行动体现友情：面对老六的羞辱与分裂，他站在天语遥一边，危机时参与援助。后来再次找到了胡玉牛，促成天表面和解与暗中改变报复方式。他与兄弟仍有个人生活理想，被天在返乡怀念中想起，之后的独立去向未展开。\",\"segmentFate\":\"帮会解散后的生活未交代，旧领袖已主动换号断联。\",\"refs\":[\"c361\",\"c363\",\"c380\",\"c422\"],\"layer\":\"main\"}],\"refs\":[\"c361\",\"c363\",\"c380\",\"c422\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-147\",\"name\":\"老六\",\"aliases\":[],\"identity\":\"原帮会成员、离心派带头者；对夏归月曾与天语遥交往怀恨。\",\"traits\":[\"趁弱夺权：借老大受伤的变化公开辱骂挑战。\",\"输后报复心强：不遵守结束约定，以暴露隐私实施羞辱。\",\"缺乏担当：救援混乱时带人逃走。\",\"善于设局：安排假危机以赢夏归月好感兼试探地盘\",\"两面行动：以天的手下身份潜伏，却服务另一帮派\"],\"portrait\":\"\",\"fate\":null,\"status\":\"c363乘救援混乱逃离，之后下落及是否受惩罚未交代。\",\"statusRefs\":[\"c362\",\"c363\"],\"segments\":[{\"scope\":\"正文 c361—c480\",\"arc\":\"他把争夺老大位置与旧恋情嫉恨混在一起，恶意歪曲归月与天之间的救助和恋爱。被击败后不再正面对抗，而改伤人格尊严，触发天语遥严重危机。忠心兄弟虽制伏他，但在救人优先的混乱中未能继续追究。\",\"segmentFate\":\"c363乘救援混乱逃离，之后下落及是否受惩罚未交代。\",\"refs\":[\"c362\",\"c363\"],\"layer\":\"main\"},{\"scope\":\"c601—c665；x001—x079（全部补充篇）\",\"arc\":\"夏归月遇险表面是普通帮派欺凌，读者随后知道这原是老六策划的英雄救美。天冲云带人闯入并真正把女孩带走，反而破坏了老六的追求计划。这个视角反转使男女主初识同时包含真实援手与人为操控，但天冲云并未在本篇识破幕后。\",\"segmentFate\":\"前传计划被天冲云意外打断，卧底身份尚未向其暴露；后续去向未交代。\",\"refs\":[\"x070\"],\"layer\":\"prequel\"}],\"refs\":[\"c362\",\"c363\",\"x070\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-148\",\"name\":\"管医生\",\"aliases\":[],\"identity\":\"医院医生，管鹏之父，负责天语遥的急救手术。\",\"traits\":[\"仁厚尽责：平等温和救治受伤的天语遥。\",\"对不良医疗环境不满，考虑离职。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段叙述明确说后来辞职；离职后的职业与生活未交代。\",\"statusRefs\":[\"c364\"],\"segments\":[{\"scope\":\"正文 c361—c480\",\"arc\":\"在外包急救人员先收费、途中缺少照料的冷漠背景下，管医生提供专业而有尊严的照护，使天语遥脱离危险。他的正直并未使环境立刻改变，儿子送来午饭并支持他离开。叙述明确告诉读者他后来确实辞职，留下个体善意与制度压力间的张力。\",\"segmentFate\":\"本段叙述明确说后来辞职；离职后的职业与生活未交代。\",\"refs\":[\"c364\"],\"layer\":\"main\"}],\"refs\":[\"c364\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-149\",\"name\":\"九尾狐少女\",\"aliases\":[],\"identity\":\"天语遥c365梦境中出现的无名狐耳九尾少女；与正式死后外传太阴形象相似，此段没有直接确认同一。\",\"traits\":[\"在虚构婚后幸福破灭时推动她离开梦境。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段只有梦中显现，未在现实接触角色。\",\"statusRefs\":[\"c365\"],\"segments\":[{\"scope\":\"正文 c361—c480\",\"arc\":\"她短暂进入天语遥的昏迷叙事，与黑色空间、六芒阵和苏醒相连。天希望继续与夏归月及儿女生活在梦里，少女的动作使她回到现实。此角色并未被确认为现实存在，其具体身份和是否与其他超自然线索相关需后文核验。\",\"segmentFate\":\"本段只有梦中显现，未在现实接触角色。\",\"refs\":[\"c365\"],\"layer\":\"main\"}],\"refs\":[\"c365\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-150\",\"name\":\"投诉霉米的老人\",\"aliases\":[],\"identity\":\"把雨晴误当服务台处理人的顾客。\",\"traits\":[\"因投诉烦躁，对无关员工厉声斥责。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"由周超引往服务台，投诉最终结果未明。\",\"statusRefs\":[\"c371\"],\"segments\":[{\"scope\":\"正文 c361—c480\",\"arc\":\"他让雨晴第一次在这组章节里直接面对顾客辱骂，也促使周超出面解释并带去正确服务台。其投诉是否最终退换成功没有在本段写明，不能把顾客闹事解决和商品售后结果混为一谈。\",\"segmentFate\":\"由周超引往服务台，投诉最终结果未明。\",\"refs\":[\"c371\"],\"layer\":\"main\"}],\"refs\":[\"c371\"],\"group\":\"配角与相关人物\",\"layer\":\"main\",\"core\":false},{\"id\":\"person-151\",\"name\":\"热心老大娘\",\"aliases\":[],\"identity\":\"在小公园看到天语遥状态异常的老人。\",\"traits\":[\"愿留意陌生年轻人的难过。\"],\"portrait\":\"\",\"fate\":null,\"status\":\"本段后续未交代。\",\"statusRefs\":[\"c374\"],\"segments\":[{\"scope\":\"正文 c361—c480\",\"arc\":\"天语遥独坐公园沉浸于旧爱与身体变化的痛苦，老人注意到她的处境。这个普通旁观者的短暂关心，与随后夏归月出现、认出她的关键重逢相邻，营造出偶遇尚有可能提供援手的生活环境。\",\"segmentFate\":\"本段后续未交代。\",\"refs\":[\"c374\"],\"layer\":\"main\"}],\"refs\":[\"c374\"],\"group\":\"配角与相关");
